function centersFor(area,centers){
  if(area==='jabodetabek')return centers.filter(c=>c.region==='jabodetabek');
  if(area==='bandung')return centers.filter(c=>c.region==='bandung');
  if(area==='jabodetabek_bandung')return centers;
  if(area==='kota')return centers.filter(c=>BOGOR_CITY.has(c.name));
  if(area==='kabupaten')return centers.filter(c=>BOGOR_KAB.has(c.name));
  if(area==='both')return centers.filter(c=>BOGOR_CITY.has(c.name)||BOGOR_KAB.has(c.name));
  const allowed=AREA_CENTER_NAMES[area];
  return allowed?centers.filter(c=>allowed.includes(c.name)):centers;
}
exports.handler=async(event)=>{if(event.httpMethod==='OPTIONS')return{statusCode:204,headers:cors(event)};if(event.httpMethod!=='POST')return{statusCode:405,headers:cors(event),body:JSON.stringify({error:'POST only'})};const auth=await requireAuth(event);if(!auth.ok)return{statusCode:auth.statusCode,headers:cors(event),body:JSON.stringify({error:auth.error})};const key=process.env.GOOGLE_MAPS_API_KEY;if(!key)return{statusCode:503,headers:cors(event),body:JSON.stringify({error:'Google Places belum dikonfigurasi: GOOGLE_MAPS_API_KEY'})};let body;try{body=JSON.parse(event.body||'{}')}catch{return{statusCode:400,headers:cors(event),body:JSON.stringify({error:'Invalid JSON'})}};if(body.healthcheck)return{statusCode:200,headers:cors(event),body:JSON.stringify({ok:true,provider:'Google Places API (New)'})};let centers=Array.isArray(body.centers)?body.centers:[];centers=centersFor(body.area||'jabodetabek_bandung',centers);const queries=Array.isArray(body.queries)&&body.queries.length?body.queries:(TERMS[body.category]||TERMS.all);const radius=Math.max(1000,Math.min(10000,Number(body.radius||5000)));const maxJobs=Math.max(1,Math.min(80,Number(process.env.GOOGLE_MAX_SEARCHES||80)));const jobs=[];for(const c of centers)for(const q of queries)jobs.push({center:c,query:String(q).trim()});const planned=jobs.slice(0,maxJobs);const truncated=jobs.length>planned.length;const timeout=Math.max(1000,Number(process.env.GOOGLE_TIMEOUT_MS||6000));const globalDeadline=Math.max(timeout+500,Math.min(22000,Number(process.env.GOOGLE_GLOBAL_DEADLINE_MS||20000)));const globalController=new AbortController();const globalTimer=setTimeout(()=>globalController.abort(),globalDeadline);const concurrency=Math.max(1,Math.min(8,Number(process.env.GOOGLE_CONCURRENCY||4)));const places=new Map(),failures=[],completed=[];await runPool(planned,concurrency,async(job,signal)=>{const {center,query}=job;const payload={textQuery:`${query} in ${center.name}, Indonesia`,pageSize:20,languageCode:'id',locationBias:{circle:{center:{latitude:center.lat,longitude:center.lng},radius}}};try{const r=await fetchWithTimeout(GOOGLE_URL,{method:'POST',headers:{'content-type':'application/json','X-Goog-Api-Key':key,'X-Goog-FieldMask':FIELD_MASK},body:JSON.stringify(payload)},timeout,signal);const text=await r.text();if(!r.ok){failures.push({center:center.name,query,status:r.status,detail:text.slice(0,160)});return;}const data=JSON.parse(text);for(const p of data.places||[])if(p.id)places.set(p.id,p);completed.push({center:center.name,query,count:(data.places||[]).length});}catch(e){failures.push({center:center.name,query,error:e?.name==='AbortError'?'timeout':(e?.message||'request_failed')});}} ,globalController.signal);clearTimeout(globalTimer);return{statusCode:200,headers:{...cors(event),'content-type':'application/json'},body:JSON.stringify({places:[...places.values()],diagnostics:{plannedJobs:planned.length,totalJobs:jobs.length,successfulJobs:completed.length,failedJobs:failures.length,uniquePlaces:places.size,truncated,completed,failures,globalDeadlineMs:globalDeadline,deadlineExceeded:globalController.signal.aborted}})};};

// Daftar mirror Overpass publik. Bisa di-override lewat env var
// OVERPASS_MIRRORS (pisahkan pakai koma) tanpa perlu ubah kode ini.
const DEFAULT_OVERPASS = [
  'https://overpass-api.de/api/interpreter',
  'https://lz4.overpass-api.de/api/interpreter',
  'https://z.overpass-api.de/api/interpreter',
  'https://overpass.kumi.systems/api/interpreter',
  'https://overpass.private.coffee/api/interpreter',
  'https://overpass.openstreetmap.fr/api/interpreter',
  'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
];

const OVERPASS = (process.env.OVERPASS_MIRRORS
  ? process.env.OVERPASS_MIRRORS.split(',').map((s) => s.trim()).filter(Boolean)
  : DEFAULT_OVERPASS);

// Opsional: kalau OVERPASS_PROXY_URL di-set (misal alamat Cloudflare Worker),
// semua request Overpass dilewatkan lewat proxy itu supaya tidak kena
// blokir IP data-center Netlify. Kalau kosong, request langsung seperti biasa.
const OVERPASS_PROXY_URL = process.env.OVERPASS_PROXY_URL || '';

function resolveFetchUrl(targetUrl) {
  if (!OVERPASS_PROXY_URL) return targetUrl;
  return `${OVERPASS_PROXY_URL}?target=${encodeURIComponent(targetUrl)}`;
}

const PROVIDER_TIMEOUT_MS = Math.max(1000, Number(process.env.OVERPASS_PROVIDER_TIMEOUT_MS || 9000));
const GLOBAL_DEADLINE_MS = Math.max(PROVIDER_TIMEOUT_MS + 500, Number(process.env.OVERPASS_GLOBAL_DEADLINE_MS || 12000));
const PROVIDER_CONCURRENCY = Math.max(1, Math.min(OVERPASS.length, Number(process.env.OVERPASS_CONCURRENCY || 3)));

const { cors, requireAuth, fetchWithTimeout } = require('./_auth');

async function callProvider(url, query, timeoutMs, signal) {
  const startedAt = Date.now();

  try {
    const body = new URLSearchParams({ data: query }).toString();
    const response = await fetchWithTimeout(
      resolveFetchUrl(url),
      {
        method: 'POST',
        headers: {
          'content-type': 'application/x-www-form-urlencoded; charset=UTF-8',
          accept: 'application/json, text/plain, */*',
          'user-agent': 'TRACE-Consultant-OS/1.0',
        },
        body,
        signal,
      },
      timeoutMs,
    );

    const text = await response.text();

    return {
      provider: url,
      ok: response.ok && !!text,
      status: response.status,
      text,
      elapsedMs: Date.now() - startedAt,
    };
  } catch (error) {
    return {
      provider: url,
      ok: false,
      status: 0,
      text: '',
      elapsedMs: Date.now() - startedAt,
      timeout: error?.name === 'AbortError',
      networkError:
        error?.name === 'AbortError'
          ? undefined
          : error?.message || String(error),
    };
  }
}

exports.handler = async (event) => {
  if (event.httpMethod === 'OPTIONS') {
    return { statusCode: 204, headers: cors(event), body: '' };
  }

  if (event.httpMethod !== 'POST') {
    return {
      statusCode: 405,
      headers: { ...cors(event), 'content-type': 'application/json' },
      body: JSON.stringify({ error: 'POST only' }),
    };
  }

  const auth = await requireAuth(event);
  if (!auth.ok) {
    return {
      statusCode: auth.statusCode,
      headers: { ...cors(event), 'content-type': 'application/json' },
      body: JSON.stringify({ error: auth.error }),
    };
  }

  const query = event.body || '';
  if (!query.trim()) {
    return {
      statusCode: 400,
      headers: { ...cors(event), 'content-type': 'application/json' },
      body: JSON.stringify({ error: 'Empty Overpass query' }),
    };
  }

  const startedAt = Date.now();
  console.log(JSON.stringify({
    stage: 'overpass_parallel_start',
    providers: OVERPASS,
    providerTimeoutMs: PROVIDER_TIMEOUT_MS,
  }));

  // Bounded parallelism + hard global deadline. This prevents one discovery request
  // from spawning seven long-lived provider requests and hanging past the job budget.
  const globalController = new AbortController();
  const globalTimer = setTimeout(() => globalController.abort(), GLOBAL_DEADLINE_MS);
  const allResults = [];
  try {
    for (let offset = 0; offset < OVERPASS.length && !globalController.signal.aborted; offset += PROVIDER_CONCURRENCY) {
      const batch = OVERPASS.slice(offset, offset + PROVIDER_CONCURRENCY);
      const attempts = batch.map(async (url) => {
        console.log(JSON.stringify({ stage: 'overpass_attempt', provider: url, timeoutMs: PROVIDER_TIMEOUT_MS }));
        const result = await callProvider(url, query, PROVIDER_TIMEOUT_MS, globalController.signal);
        allResults.push(result);
        if (result.ok) {
          console.log(JSON.stringify({ stage: 'overpass_success', provider: url, status: result.status, elapsedMs: result.elapsedMs }));
          return result;
        }
        console.warn(JSON.stringify({ stage: 'overpass_failure', provider: url, status: result.status, timeout: !!result.timeout, networkError: result.networkError, elapsedMs: result.elapsedMs, detail: result.text ? result.text.slice(0, 300) : undefined }));
        throw result;
      });
      try {
        const success = await Promise.any(attempts);
        globalController.abort();
        return { statusCode: 200, headers: { ...cors(event), 'content-type': 'application/json', 'x-overpass-provider': success.provider }, body: success.text };
      } catch {
        if (globalController.signal.aborted) break;
      }
    }

    const results = allResults;
    const reason = results.some((x) => x.status === 429)
      ? 'rate_limited'
      : globalController.signal.aborted && (Date.now() - startedAt) >= GLOBAL_DEADLINE_MS
        ? 'global_timeout'
        : results.some((x) => x.timeout)
          ? 'timeout'
          : results.some((x) => x.status >= 500)
            ? 'server_error'
            : results.some((x) => x.status === 406)
              ? 'request_rejected'
              : results.some((x) => x.networkError)
                ? 'network_error'
                : 'unknown';
    console.error(JSON.stringify({ stage: 'overpass_all_failed', elapsedMs: Date.now() - startedAt, reason, providerConcurrency: PROVIDER_CONCURRENCY, globalDeadlineMs: GLOBAL_DEADLINE_MS, attempts: results.map((result) => ({ provider: result.provider, status: result.status, timeout: !!result.timeout, networkError: result.networkError, detail: result.text ? result.text.slice(0, 300) : undefined })) }));
    return { statusCode: reason === 'global_timeout' ? 504 : 502, headers: { ...cors(event), 'content-type': 'application/json' }, body: JSON.stringify({ error: 'All Overpass providers failed', reason, elapsedMs: Date.now() - startedAt, providerConcurrency: PROVIDER_CONCURRENCY, globalDeadlineMs: GLOBAL_DEADLINE_MS, attempts: results.map((result) => ({ provider: result.provider, status: result.status, timeout: !!result.timeout, networkError: result.networkError, detail: result.text ? result.text.slice(0, 300) : undefined })) }) };
  } finally {
    clearTimeout(globalTimer);
  }

};

const {cors,requireAuth}=require('./_auth');
const {isPublicHttpUrl,fetchPublicUrl}=require('./_url');

exports.handler = async (event) => {
  if (event.httpMethod === 'OPTIONS') return {statusCode:204,headers:cors(event)};
  if (event.httpMethod !== 'POST') return {statusCode:405,headers:cors(event),body:JSON.stringify({error:'POST only'})};
  const auth=await requireAuth(event); if(!auth.ok) return {statusCode:auth.statusCode,headers:cors(event),body:JSON.stringify({error:auth.error})};
  let body={}; try{body=JSON.parse(event.body||'{}')}catch(e){return {statusCode:400,headers:cors(event),body:JSON.stringify({error:'Invalid JSON'})}};

  const websites=(Array.isArray(body.websites)?body.websites:[]).slice(0,40);
  const timeoutMs=Math.max(1500,Math.min(9000,Number(process.env.SOCIAL_TIMEOUT_MS||7000)));
  const globalDeadlineMs=Math.max(timeoutMs,Math.min(15000,Number(process.env.SOCIAL_ENRICH_GLOBAL_DEADLINE_MS||12000)));
  const concurrency=Math.max(1,Math.min(4,Number(process.env.SOCIAL_ENRICH_CONCURRENCY||3)));
  const started=Date.now();
  const globalController=new AbortController();
  const timer=setTimeout(()=>globalController.abort(),globalDeadlineMs);
  const results=new Array(websites.length);
  let cursor=0;

  async function worker(){
    while(!globalController.signal.aborted){
      const index=cursor++;
      if(index>=websites.length) return;
      const item=websites[index]||{};
      const externalId=item.external_id;
      const website=String(item.website||'').trim();
      let instagram=null;
      let blocked=false;
      let error=null;
      if(!(await isPublicHttpUrl(website))){
        blocked=true;
      } else {
        try{
          const r=await fetchPublicUrl(website,{headers:{'user-agent':'TRACE-Acquisition-OS/1.0'}},timeoutMs,3,globalController.signal);
          const contentType=(r.headers.get('content-type')||'').toLowerCase();
          // Instagram discovery only needs HTML. Avoid spending time parsing
          // PDFs, images, archives, or other binary responses.
          if(contentType && !contentType.includes('text/html') && !contentType.includes('application/xhtml+xml')) {
            error='UNSUPPORTED_CONTENT_TYPE';
          } else {
            const html=(await r.text()).slice(0,750000);
            const matches=[...html.matchAll(/https?:\/\/(?:www\.)?instagram\.com\/([A-Za-z0-9_.-]+)/ig)];
            for(const m of matches){
              const handle=String(m[1]||'').toLowerCase();
              if(!['p','reel','reels','explore','accounts','about','direct'].includes(handle)){
                instagram='@'+m[1];
                break;
              }
            }
          }
        }catch(e){
          error=e?.name==='AbortError' ? 'TIMEOUT_OR_GLOBAL_DEADLINE' : String(e?.message||e);
        }
      }
      results[index]={external_id:externalId,instagram,blocked,error};
    }
  }

  await Promise.all(Array.from({length:Math.min(concurrency,websites.length)},worker));
  clearTimeout(timer);
  for(let i=0;i<results.length;i++){
    if(!results[i]) results[i]={external_id:websites[i]?.external_id,instagram:null,blocked:false,error:'GLOBAL_DEADLINE_REACHED'};
  }
  return {statusCode:200,headers:{...cors(event),'content-type':'application/json'},body:JSON.stringify({
    results,
    diagnostics:{requested:websites.length,completed:results.length,timeoutMs,globalDeadlineMs,concurrency,elapsedMs:Date.now()-started,deadlineExceeded:globalController.signal.aborted}
  })};
};

const {cors,requireAuth}=require('./_auth');
const {isPublicHttpUrl,fetchPublicUrl}=require('./_url');
exports.handler = async (event) => {
  if (event.httpMethod === 'OPTIONS') return {statusCode:204,headers:cors(event)};
  if (event.httpMethod !== 'POST') return {statusCode:405,headers:cors(event),body:JSON.stringify({error:'POST only'})};
  const auth=await requireAuth(event); if(!auth.ok)return {statusCode:auth.statusCode,headers:cors(event),body:JSON.stringify({error:auth.error})};
  let body={}; try{body=JSON.parse(event.body||'{}')}catch(e){return {statusCode:400,headers:cors(event),body:JSON.stringify({error:'Invalid JSON'})}};
  const lead=body.lead||{};
  const urls=[];
  if(lead.website && (await isPublicHttpUrl(lead.website))) urls.push({url:lead.website,type:'website'});
  if(lead.instagram){
    const handle=String(lead.instagram).replace(/^@/,'').trim();
    if(/^[A-Za-z0-9_.-]+$/.test(handle)) urls.push({url:`https://www.instagram.com/${handle}/`,type:'instagram'});
  }
  const unique=[]; const seen=new Set();
  for(const item of urls){const key=item.url.toLowerCase();if(!seen.has(key)){seen.add(key);unique.push(item)}}
  const timeoutMs=Math.max(1500,Math.min(9000,Number(process.env.SOCIAL_TIMEOUT_MS||7000)));
  const globalDeadlineMs=Math.max(timeoutMs,Math.min(12000,Number(process.env.SOCIAL_GLOBAL_DEADLINE_MS||9000)));
  const concurrency=Math.max(1,Math.min(2,Number(process.env.SOCIAL_CONCURRENCY||2)));
  const started=Date.now();
  const globalController=new AbortController();
  const globalTimer=setTimeout(()=>globalController.abort(),globalDeadlineMs);
  const docs=[];
  let cursor=0;
  async function worker(){
    while(cursor<unique.length && !globalController.signal.aborted){
      const item=unique[cursor++];
      try{
        if(globalController.signal.aborted) break;
        const r=await fetchPublicUrl(item.url,{headers:{'user-agent':'Mozilla/5.0 TRACE-Acquisition-OS/1.0'}},timeoutMs,3,globalController.signal);
        const html=(await r.text()).slice(0,1000000);
        const title=meta(html,'og:title')||meta(html,'twitter:title')||tag(html,'title');
        const description=meta(html,'og:description')||meta(html,'description')||meta(html,'twitter:description');
        const h1=(html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)||[])[1]||'';
        const text=strip(`${title||''} ${description||''} ${h1||''}`).replace(/\s+/g,' ').trim();
        docs.push({type:item.type,url:item.url,title:title||null,description:description||null,text:text.slice(0,2000),status:r.status});
      }catch(e){
        docs.push({type:item.type,url:item.url,error:e?.name==='AbortError'?'timeout':String(e?.message||e)});
      }
    }
  }
  await Promise.all(Array.from({length:Math.min(concurrency,unique.length)},worker));
  clearTimeout(globalTimer);

  const combined=docs.map(d=>d.text||'').join(' ').toLowerCase();
  const keywords={food:['coffee','kopi','cafe','café','restaurant','resto','bakery','dessert','kitchen','brunch'],promo:['promo','discount','diskon','voucher','order','delivery','reservasi','booking'],community:['community','event','music','workshop','space'],premium:['specialty','artisan','premium','signature','roastery'],conversion:['menu','whatsapp','contact','order','booking','reservasi']};
  const hits={}; Object.entries(keywords).forEach(([k,arr])=>hits[k]=arr.filter(x=>combined.includes(x)));
  const websiteReachable=docs.some(d=>d.type==='website'&&d.status>=200&&d.status<400);
  const instagramReachable=docs.some(d=>d.type==='instagram'&&d.status>=200&&d.status<400);
  const hasCTA=hits.promo.length>0;
  const evidence={website:websiteReachable,instagram:instagramReachable,offerSignals:hits.promo.length,communitySignals:hits.community.length,premiumSignals:hits.premium.length,conversionSignals:hits.conversion.length};
  const publicSignals=[];
  if(lead.instagram) publicSignals.push({signal:'Instagram profile identified',type:'fact',detail:'Profil Instagram tersedia dari data lead.'});
  if(instagramReachable) publicSignals.push({signal:'Public Instagram page reachable',type:'fact',detail:'Halaman publik Instagram dapat diakses saat pengecekan.'});
  if(websiteReachable) publicSignals.push({signal:'Website reachable',type:'fact',detail:'Website bisnis dapat diakses saat pengecekan.'});
  if(hasCTA) publicSignals.push({signal:'Offer / CTA language detected',type:'fact',detail:`Tema CTA terdeteksi: ${hits.promo.join(', ')}.`});
  if(hits.community.length) publicSignals.push({signal:'Community/event signal',type:'fact',detail:`Tema community/event terdeteksi: ${hits.community.join(', ')}.`});
  if(hits.premium.length) publicSignals.push({signal:'Premium/specialty positioning signal',type:'fact',detail:`Tema premium/specialty terdeteksi: ${hits.premium.join(', ')}.`});
  // Evidence-derived scoring: every point is tied to an observed signal.
  // Missing evidence contributes 0 and is reported as a coverage limitation;
  // it is never converted into a made-up positive score.
  const brand=Math.min(100,(websiteReachable?35:0)+(lead.instagram?20:0)+(instagramReachable?20:0)+(lead.rating>=4.5?10:0));
  const content=Math.min(100,(instagramReachable?35:0)+(hits.community.length?20:0)+(hits.premium.length?20:0)+(hits.food.length?10:0));
  const reach=Math.min(100,(instagramReachable?30:0)+(lead.review_count>=500?20:0)+(lead.rating>=4.5?15:0)+(lead.outlet_count>1?15:0));
  const conversion=Math.min(100,(hasCTA?30:0)+(websiteReachable?20:0)+(hits.conversion.length?25:0)+(lead.review_count>=500?10:0));
  const evidenceCount=Object.values(evidence).filter(v=>typeof v==='boolean'?v:v>0).length;
  const coveragePct=Math.round((evidenceCount/Object.keys(evidence).length)*100);
  let angle='Business & Profitability Insight';
  if(instagramReachable && reach>=50) angle='Social Media Growth / Reach';
  else if(conversion>=50) angle='Content-to-Conversion';
  else if(lead.outlet_count>1) angle='Operational Scaling + Profitability';
  const sourceNote=instagramReachable||websiteReachable
    ? 'Analisis otomatis hanya memakai sinyal publik yang berhasil diakses saat pemeriksaan; tidak mengklaim observasi feed pixel-level.'
    : 'Tidak ada sumber publik yang berhasil diverifikasi saat pemeriksaan; sistem tidak mengarang isi social/website.';
  const result={
    status:instagramReachable?'auto_public_data':(websiteReachable?'partial_public_data':'limited_public_data'),
    instagram:lead.instagram||null,source_note:sourceNote,
    public_pages:docs.map(d=>({type:d.type,url:d.url,status:d.status||null,title:d.title||null,description:d.description||null,error:d.error||null})),
    signals:publicSignals,metrics:{brand_presence:brand,content_opportunity:content,reach_opportunity:reach,conversion_opportunity:conversion},
    detected_themes:hits, evidence_coverage_pct:coveragePct, evidence,
    primary_opportunity:coveragePct>=40?`Peluang utama yang perlu diuji: ${angle}.`:'Data publik belum cukup untuk menyimpulkan peluang utama; validasi lewat percakapan atau sumber tambahan.',
    recommended_sales_angle:angle,
    dm_hook:coveragePct>=40?`Saya sempat melihat presence digital ${lead.business_name}; ada satu peluang yang menurut saya menarik dari sisi ${angle.toLowerCase()}.`:`Saya melihat data publik ${lead.business_name} masih terbatas; ada satu insight bisnis yang menurut saya menarik untuk divalidasi.`,
    diagnostics:{requestedSources:unique.length,completedSources:docs.length,timeoutMs,globalDeadlineMs,elapsedMs:Date.now()-started,deadlineExceeded:globalController.signal.aborted},
    analyzed_at:new Date().toISOString()
  };
  return {statusCode:200,headers:{...cors(event),'content-type':'application/json'},body:JSON.stringify(result)};
};

function meta(html,name){const re=new RegExp(`<meta[^>]+(?:property|name)=["']${name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}["'][^>]+content=["']([^"']*)["'][^>]*>`,'i');const m=html.match(re);return m?decode(m[1]):null}
function tag(html,name){const m=html.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)<\\/${name}>`,'i'));return m?decode(m[1]):null}
function strip(s){return decode(s.replace(/<[^>]+>/g,' '))}
function decode(s){return String(s||'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>')}

