export type AccountingAccountType = 'asset'|'liability'|'equity'|'revenue'|'cogs'|'expense';
export interface Account { id:string; clientId:string; code:string; name:string; type:AccountingAccountType; parentId?:string; active:boolean; }
export interface JournalLine { accountId:string; debit:number; credit:number; memo?:string; }
export interface JournalEntry { id:string; clientId:string; date:string; memo:string; source:'manual'|'imported'|'system'|'adjustment'; lines:JournalLine[]; }
export interface AccountingBalance { accountId:string; debit:number; credit:number; balance:number; }
export interface TrialBalance { balanced:boolean; totalDebit:number; totalCredit:number; accounts:AccountingBalance[]; missingAccountIds:string[]; }
export interface CogsInput { productId:string; qty:number; components:Array<{itemId:string;qtyPerSale:number;unitCost:number|null}>; }
export interface CogsResult { productId:string; qty:number; cogs:number|null; missingItemIds:string[]; formula:string; status:'calculated'|'insufficient_data'; }

export function buildTrialBalance(accounts:Account[], entries:JournalEntry[]):TrialBalance {
  const balances=new Map<string,{debit:number;credit:number}>(); const missing=new Set<string>();
  for(const a of accounts) balances.set(a.id,{debit:0,credit:0});
  for(const e of entries) for(const l of e.lines){
    if(!Number.isFinite(l.debit)||!Number.isFinite(l.credit)||l.debit<0||l.credit<0||(l.debit>0&&l.credit>0)||(l.debit===0&&l.credit===0)) continue;
    const b=balances.get(l.accountId); if(!b){missing.add(l.accountId);continue;} b.debit+=l.debit;b.credit+=l.credit;
  }
  const rows=accounts.filter(a=>balances.has(a.id)).map(a=>{const b=balances.get(a.id)!;return {accountId:a.id,debit:b.debit,credit:b.credit,balance:b.debit-b.credit};});
  const totalDebit=rows.reduce((s,r)=>s+r.debit,0), totalCredit=rows.reduce((s,r)=>s+r.credit,0);
  return {balanced:missing.size===0&&Math.abs(totalDebit-totalCredit)<0.005,totalDebit,totalCredit,accounts:rows,missingAccountIds:[...missing]};
}

export function calculateRecipeCogs(inputs:CogsInput[]):CogsResult[] {
  return inputs.map(i=>{
    if(!Number.isFinite(i.qty)||i.qty<=0) return {productId:i.productId,qty:i.qty,cogs:null,missingItemIds:[],formula:'qty × Σ(component qty per sale × unit cost)',status:'insufficient_data'};
    const missing=i.components.filter(c=>!Number.isFinite(c.unitCost)||c.unitCost!<0).map(c=>c.itemId);
    if(missing.length) return {productId:i.productId,qty:i.qty,cogs:null,missingItemIds:[...new Set(missing)],formula:'qty × Σ(component qty per sale × unit cost)',status:'insufficient_data'};
    const unit=i.components.reduce((s,c)=>s+c.qtyPerSale*c.unitCost!,0);
    return {productId:i.productId,qty:i.qty,cogs:i.qty*unit,missingItemIds:[],formula:'qty × Σ(component qty per sale × unit cost)',status:'calculated'};
  });
}

export interface BusinessProfitChain { revenue:number|null; cogs:number|null; grossProfit:number|null; labor:number|null; opex:number|null; operatingProfit:number|null; missing:string[]; }
export function buildProfitChain(values:{revenue?:number|null;cogs?:number|null;labor?:number|null;opex?:number|null}):BusinessProfitChain {
  const revenue=finiteOrNull(values.revenue),cogs=finiteOrNull(values.cogs),labor=finiteOrNull(values.labor),opex=finiteOrNull(values.opex);
  const missing:string[]=[]; if(revenue===null)missing.push('Revenue');if(cogs===null)missing.push('COGS');if(labor===null)missing.push('Labor');if(opex===null)missing.push('OPEX');
  const grossProfit=revenue!==null&&cogs!==null?revenue-cogs:null;
  const operatingProfit=revenue!==null&&cogs!==null&&labor!==null&&opex!==null?revenue-cogs-labor-opex:null;
  return {revenue,cogs,grossProfit,labor,opex,operatingProfit,missing};
}
function finiteOrNull(v:number|null|undefined){return typeof v==='number'&&Number.isFinite(v)?v:null;}

/**
 * ============================================================================
 * UTANG USAHA (ACCOUNTS PAYABLE) + LAPORAN UMUR UTANG (AGING)
 * ============================================================================
 * Kebalikan dari accountsReceivable.ts: melacak tagihan dari SUPPLIER (bahan
 * baku, sewa, dll) yang belum dibayar klien. Ini krusial untuk F&B karena
 * arus kas yang sehat sering rusak bukan karena tidak untung, tapi karena
 * telat bayar supplier sampai kena penalti atau putus pasokan.
 */

export interface ApBill {
  id: string;
  clientId: string;
  vendorName: string;
  billDate: string; // ISO date
  dueDate: string;  // ISO date
  amount: number;
}

export interface ApPayment {
  billId: string;
  amount: number;
  paidDate: string; // ISO date
}

export type ApAgingBucket = 'belum_jatuh_tempo' | '0-30' | '31-60' | '61-90' | '>90';

export interface ApBillStatus {
  bill: ApBill;
  paidAmount: number;
  outstanding: number;
  status: 'lunas' | 'sebagian' | 'belum_dibayar';
  daysOverdue: number;
  agingBucket: ApAgingBucket;
}

export interface ApAgingSummary {
  asOfDate: string;
  buckets: Record<ApAgingBucket, number>;
  totalOutstanding: number;
  bills: ApBillStatus[];
}

function daysBetween(from: string, to: string): number {
  return Math.round((new Date(to).getTime() - new Date(from).getTime()) / 86_400_000);
}

export function buildApAging(bills: ApBill[], payments: ApPayment[], asOfDate: string): ApAgingSummary {
  const paidByBill = new Map<string, number>();
  for (const p of payments) paidByBill.set(p.billId, (paidByBill.get(p.billId) ?? 0) + p.amount);

  const statuses: ApBillStatus[] = bills.map(bill => {
    const paid = Math.round((paidByBill.get(bill.id) ?? 0) * 100) / 100;
    const outstanding = Math.max(0, Math.round((bill.amount - paid) * 100) / 100);
    const overdue = daysBetween(bill.dueDate, asOfDate);

    let agingBucket: ApAgingBucket;
    if (overdue < 0) agingBucket = 'belum_jatuh_tempo';
    else if (overdue <= 30) agingBucket = '0-30';
    else if (overdue <= 60) agingBucket = '31-60';
    else if (overdue <= 90) agingBucket = '61-90';
    else agingBucket = '>90';

    const status: ApBillStatus['status'] = outstanding <= 0 ? 'lunas' : paid > 0 ? 'sebagian' : 'belum_dibayar';
    return { bill, paidAmount: paid, outstanding, status, daysOverdue: Math.max(0, overdue), agingBucket };
  });

  const buckets: Record<ApAgingBucket, number> = { belum_jatuh_tempo: 0, '0-30': 0, '31-60': 0, '61-90': 0, '>90': 0 };
  for (const s of statuses) if (s.outstanding > 0) buckets[s.agingBucket] += s.outstanding;

  return {
    asOfDate,
    buckets,
    totalOutstanding: Math.round(statuses.reduce((sum, s) => sum + s.outstanding, 0) * 100) / 100,
    bills: statuses,
  };
}

/**
 * ============================================================================
 * PIUTANG USAHA (ACCOUNTS RECEIVABLE) + LAPORAN UMUR PIUTANG (AGING)
 * ============================================================================
 * Berguna untuk klien F&B yang melayani corporate/catering/event dengan
 * termin bayar (bukan cash langsung seperti dine-in biasa). Tanpa modul ini,
 * konsultan tidak bisa menjawab pertanyaan paling dasar: "klien mana yang
 * belum bayar, sudah berapa lama, dan berapa total uang yang masih nyangkut?"
 */

export interface ArInvoice {
  id: string;
  clientId: string;
  customerName: string;
  invoiceDate: string; // ISO date
  dueDate: string;     // ISO date
  amount: number;
}

export interface ArPayment {
  invoiceId: string;
  amount: number;
  paidDate: string; // ISO date
}

export type ArAgingBucket = 'belum_jatuh_tempo' | '0-30' | '31-60' | '61-90' | '>90';

export interface ArInvoiceStatus {
  invoice: ArInvoice;
  paidAmount: number;
  outstanding: number;
  status: 'lunas' | 'sebagian' | 'belum_dibayar';
  daysOverdue: number;
  agingBucket: ArAgingBucket;
}

export interface ArAgingSummary {
  asOfDate: string;
  buckets: Record<ArAgingBucket, number>;
  totalOutstanding: number;
  invoices: ArInvoiceStatus[];
}

function daysBetween(from: string, to: string): number {
  return Math.round((new Date(to).getTime() - new Date(from).getTime()) / 86_400_000);
}

/** Menyusun status pembayaran tiap invoice + laporan umur piutang per tanggal `asOfDate`. */
export function buildArAging(invoices: ArInvoice[], payments: ArPayment[], asOfDate: string): ArAgingSummary {
  const paidByInvoice = new Map<string, number>();
  for (const p of payments) paidByInvoice.set(p.invoiceId, (paidByInvoice.get(p.invoiceId) ?? 0) + p.amount);

  const statuses: ArInvoiceStatus[] = invoices.map(invoice => {
    const paid = Math.round((paidByInvoice.get(invoice.id) ?? 0) * 100) / 100;
    const outstanding = Math.max(0, Math.round((invoice.amount - paid) * 100) / 100);
    const overdue = daysBetween(invoice.dueDate, asOfDate);

    let agingBucket: ArAgingBucket;
    if (overdue < 0) agingBucket = 'belum_jatuh_tempo';
    else if (overdue <= 30) agingBucket = '0-30';
    else if (overdue <= 60) agingBucket = '31-60';
    else if (overdue <= 90) agingBucket = '61-90';
    else agingBucket = '>90';

    const status: ArInvoiceStatus['status'] = outstanding <= 0 ? 'lunas' : paid > 0 ? 'sebagian' : 'belum_dibayar';
    return { invoice, paidAmount: paid, outstanding, status, daysOverdue: Math.max(0, overdue), agingBucket };
  });

  const buckets: Record<ArAgingBucket, number> = { belum_jatuh_tempo: 0, '0-30': 0, '31-60': 0, '61-90': 0, '>90': 0 };
  for (const s of statuses) if (s.outstanding > 0) buckets[s.agingBucket] += s.outstanding;

  return {
    asOfDate,
    buckets,
    totalOutstanding: Math.round(statuses.reduce((sum, s) => sum + s.outstanding, 0) * 100) / 100,
    invoices: statuses,
  };
}

/**
 * ============================================================================
 * INFERENSI SUB-TYPE AKUN DARI DATA YANG SUDAH ADA (TANPA MIGRATION)
 * ============================================================================
 * `chartOfAccounts.ts` mendefinisikan `AccountSubType` (aset_lancar, aset_tetap,
 * dst.) yang dibutuhkan `balanceSheet.ts` untuk menyusun Neraca. Tapi tabel
 * `trace_accounts` yang SUDAH ADA di Supabase (lihat
 * `supabase/migrations/028_accounting_and_cogs_v72.sql`) cuma punya kolom
 * `account_type` (asset/liability/equity/revenue/cogs/expense) — TIDAK ada
 * kolom untuk sub-type.
 *
 * Dua pilihan untuk menutup celah ini:
 *   (a) migration baru menambah kolom `sub_type` ke `trace_accounts`, atau
 *   (b) menebak sub-type dari data yang SUDAH ADA (kode akun + tipe akun),
 *       tanpa mengubah skema database sama sekali.
 *
 * File ini memilih (b) untuk sementara, karena:
 *   1. Project Supabase TRACE sedang berstatus INACTIVE (paused) saat file ini
 *      ditulis — tidak bisa diverifikasi/diuji migration terhadap skema live-nya.
 *      Menulis SQL migration tanpa bisa menjalankannya adalah tebakan, bukan
 *      kerja yang sudah diverifikasi.
 *   2. Akun standar yang dibuat lewat `defaultChartOfAccounts()` SELALU memakai
 *      pola kode 1100-6900 yang konsisten (lihat komentar di `chartOfAccounts.ts`),
 *      jadi sub-type-nya bisa ditebak dengan akurat dari kode akun tanpa perlu
 *      menyimpannya ulang di database.
 *   3. Kalau nanti project Supabase-nya aktif lagi dan tim MEMANG mau kolom
 *      `sub_type` eksplisit (mis. karena konsultan sering bikin akun custom di
 *      luar pola kode standar), migration (a) tetap bisa dibuat sebagai langkah
 *      terpisah — file ini tidak menghalangi itu, `AccountWithSubType` di
 *      `chartOfAccounts.ts` tetap struktur yang sama persis.
 *
 * PENTING: ini TEBAKAN berbasis pola kode, bukan sumber kebenaran. Kalau
 * konsultan membuat akun custom dengan kode di luar pola standar (mis. akun
 * aset dengan kode "9001"), fallback di bawah akan menebak berdasarkan
 * `account_type` saja (asset → aset_lancar, liability → liabilitas_lancar,
 * dst.) — cukup aman untuk kasus umum, tapi konsultan tetap perlu mengecek
 * manual kalau ada akun custom yang tidak mengikuti pola kode standar.
 */

import type { Account, AccountingAccountType } from './accounting.js';
import type { AccountSubType, AccountWithSubType } from './chartOfAccounts.js';

/** Fallback paling aman kalau kode akun tidak cocok pola manapun di bawah — dipilih
 *  supaya akun tetap MUNCUL di kelompok yang masuk akal, bukan hilang dari Neraca. */
const DEFAULT_SUBTYPE_BY_TYPE: Record<AccountingAccountType, AccountSubType> = {
  asset: 'aset_lancar',
  liability: 'liabilitas_lancar',
  equity: 'ekuitas',
  revenue: 'pendapatan_usaha',
  cogs: 'harga_pokok_penjualan',
  expense: 'beban_operasional',
};

/**
 * Menebak `AccountSubType` dari kode + tipe satu akun, mengikuti pola kode
 * yang sama persis dengan `defaultChartOfAccounts()`:
 *   1100-1499 aset lancar · 1500-1599 aset tetap
 *   2100-2499 liabilitas lancar · 2500-2999 liabilitas jangka panjang
 *   3xxx ekuitas · 4xxx pendapatan · 5xxx HPP · 6xxx beban
 */
export function inferAccountSubType(account: Pick<Account, 'code' | 'type'>): AccountSubType {
  const codeNum = Number.parseInt(account.code, 10);
  const hasNumericCode = Number.isFinite(codeNum);

  if (account.type === 'asset' && hasNumericCode) {
    if (codeNum >= 1500 && codeNum < 1600) return 'aset_tetap';
    if (codeNum >= 1100 && codeNum < 1500) return 'aset_lancar';
  }
  if (account.type === 'liability' && hasNumericCode) {
    if (codeNum >= 2500 && codeNum < 3000) return 'liabilitas_jangka_panjang';
    if (codeNum >= 2100 && codeNum < 2500) return 'liabilitas_lancar';
  }

  return DEFAULT_SUBTYPE_BY_TYPE[account.type];
}

/** Mengubah daftar `Account` polos (persis bentuk yang keluar dari
 *  `trace_read_client_dataset` RPC / kolom `accounts` di Supabase) menjadi
 *  `AccountWithSubType[]` yang siap dipakai `buildBalanceSheet()` — tanpa
 *  butuh kolom `sub_type` apa pun di database. */
export function withInferredSubTypes(accounts: Account[]): AccountWithSubType[] {
  return accounts.map(a => ({ ...a, subType: inferAccountSubType(a) }));
}

export const ACQUISITION_STAGES = [
  'discovery', 'raw_leads', 'normalized', 'deduplicated', 'enriched',
  'analyzed', 'qualified', 'prioritized', 'outreach', 'response',
  'meeting', 'proposal', 'client'
] as const;
export type AcquisitionStage = typeof ACQUISITION_STAGES[number];

export type AcquisitionLead = {
  id: string;
  businessName: string;
  category?: string | null;
  city?: string | null;
  phone?: string | null;
  website?: string | null;
  instagram?: string | null;
  address?: string | null;
  rating?: number | null;
  reviewCount?: number | null;
  outletCount?: number | null;
  source?: string | null;
  externalId?: string | null;
  latitude?: number | null;
  longitude?: number | null;
  fitScore?: number | null;
  status?: string | null;
};

export type AcquisitionEvidence = {
  field: string;
  value: unknown;
  source?: string | null;
  available: boolean;
};

export type ProblemHypothesis = {
  title: string;
  rationale: string;
  evidenceFields: string[];
  status: 'hypothesis' | 'validated' | 'rejected';
};

export type Qualification = {
  fitScore: number;
  dataCoveragePct: number;
  priority: 'P1' | 'P2' | 'P3' | 'P4';
  fitStatus: 'high' | 'medium' | 'low' | 'insufficient_data';
  reasons: string[];
  hypotheses: ProblemHypothesis[];
};

export type PipelineMetrics = {
  total: number;
  byStage: Record<AcquisitionStage, number>;
  qualified: number;
  prioritized: number;
  contactable: number;
  conversionRate: number | null;
};

const has = (v: unknown) => v !== null && v !== undefined && v !== '' && v !== 'Unknown' && v !== 'Not Found';
const clamp = (n: number) => Math.max(0, Math.min(100, Math.round(n)));

export function normalizeLead(input: AcquisitionLead): AcquisitionLead {
  return {
    ...input,
    businessName: String(input.businessName || '').trim(),
    category: has(input.category) ? String(input.category).trim() : null,
    city: has(input.city) ? String(input.city).trim() : null,
    phone: has(input.phone) ? String(input.phone).trim() : null,
    website: has(input.website) ? String(input.website).trim() : null,
    instagram: has(input.instagram) ? String(input.instagram).trim() : null,
    address: has(input.address) ? String(input.address).trim() : null,
    rating: typeof input.rating === 'number' && Number.isFinite(input.rating) ? input.rating : null,
    reviewCount: typeof input.reviewCount === 'number' && Number.isFinite(input.reviewCount) ? input.reviewCount : null,
    outletCount: typeof input.outletCount === 'number' && Number.isFinite(input.outletCount) ? input.outletCount : null,
  };
}

export function deduplicateLeads(leads: AcquisitionLead[]): AcquisitionLead[] {
  const out: AcquisitionLead[] = [];
  const seen = new Set<string>();
  for (const raw of leads) {
    const lead = normalizeLead(raw);
    const keys = [
      lead.externalId ? `id:${lead.externalId}` : '',
      has(lead.phone) ? `phone:${String(lead.phone).replace(/\D/g, '').replace(/^62/, '0')}` : '',
      has(lead.website) ? `web:${String(lead.website).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '')}` : '',
      has(lead.instagram) ? `ig:${String(lead.instagram).toLowerCase().replace(/^@/, '').replace(/\/$/, '')}` : '',
      `name:${lead.businessName.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()}:${String(lead.city || '').toLowerCase().trim()}`
    ].filter(Boolean);
    if (keys.some(k => seen.has(k))) continue;
    keys.forEach(k => seen.add(k));
    out.push(lead);
  }
  return out;
}

export function qualifyLead(lead: AcquisitionLead, evidence: AcquisitionEvidence[] = []): Qualification {
  const l = normalizeLead(lead);
  const available = new Set(evidence.filter(e => e.available && has(e.value)).map(e => e.field));
  const reasons: string[] = [];
  let score = 0;

  // Fit is consulting potential, not data availability. Data completeness is
  // reported separately so a well-documented but low-fit business cannot score
  // highly merely because it has many fields populated.
  const category = String(l.category || '').toLowerCase();
  const isTargetFnb = /coffee|cafe|café|restaurant|resto|bakery|dessert|food|kuliner|kedai/.test(category);
  if (isTargetFnb) { score += 20; reasons.push('Kategori bisnis sesuai target F&B consulting.'); }
  else if (has(l.category)) reasons.push('Kategori tersedia, tetapi kecocokan F&B belum terkonfirmasi.');

  if (typeof l.outletCount === 'number') {
    if (l.outletCount >= 5) { score += 30; reasons.push('Multi-outlet skala tinggi memberi sinyal kebutuhan kontrol dan standardisasi.'); }
    else if (l.outletCount >= 2) { score += 20; reasons.push('Multi-outlet memberi sinyal kebutuhan scaling dan operational control.'); }
    else if (l.outletCount === 1) { score += 5; reasons.push('Single outlet memiliki potensi consulting, tetapi kompleksitas operasional belum tinggi.'); }
  }

  if (typeof l.reviewCount === 'number') {
    if (l.reviewCount >= 1000) { score += 15; reasons.push('Traction publik tinggi memberi basis untuk menguji growth/operations opportunity.'); }
    else if (l.reviewCount >= 300) { score += 10; reasons.push('Traction publik cukup untuk contextual business analysis.'); }
    else if (l.reviewCount >= 50) { score += 5; reasons.push('Ada traction publik yang dapat digunakan sebagai evidence awal.'); }
  }

  const digitalSignals = Number(has(l.website)) + Number(has(l.instagram));
  if (digitalSignals === 2) { score += 15; reasons.push('Website dan Instagram tersedia untuk menguji digital-to-business opportunity.'); }
  else if (digitalSignals === 1) { score += 8; reasons.push('Satu digital presence tersedia untuk analisis lanjutan.'); }

  if (has(l.phone)) { score += 5; reasons.push('Kontak tersedia sehingga lead dapat ditindaklanjuti.'); }
  if (available.has('revenue') || available.has('cogs') || available.has('labor') || available.has('opex')) {
    score += 15;
    reasons.push('Ada evidence finansial yang dapat membuka diagnosis profitability.');
  }

  score = clamp(score);
  const expectedFields = ['category','city','phone','website','instagram','address','rating','reviewCount','outletCount'];
  const coveragePct = Math.round((expectedFields.filter(field => has((l as Record<string, unknown>)[field])).length / expectedFields.length) * 100);

  const hypotheses: ProblemHypothesis[] = [];
  if ((l.outletCount || 0) > 1) hypotheses.push({
    title: 'Scaling / operational control',
    rationale: 'Multi-outlet is a scale signal; it does not prove an operational problem.',
    evidenceFields: ['outletCount'], status: 'hypothesis'
  });
  if ((l.reviewCount || 0) >= 500 && has(l.instagram)) hypotheses.push({
    title: 'Content-to-conversion opportunity',
    rationale: 'Public traction plus digital presence creates a reason to test conversion, not a claim that conversion is weak.',
    evidenceFields: ['reviewCount', 'instagram'], status: 'hypothesis'
  });
  if (available.has('revenue') || available.has('cogs') || available.has('labor') || available.has('opex')) hypotheses.push({
    title: 'Profitability diagnosis opportunity',
    rationale: 'Financial evidence is available for diagnosis; no specific financial problem is claimed until calculation confirms it.',
    evidenceFields: ['revenue', 'cogs', 'labor', 'opex'].filter(x => available.has(x)), status: 'hypothesis'
  });
  if (!hypotheses.length) hypotheses.push({
    title: 'Business system opportunity requires validation',
    rationale: 'Public evidence is insufficient to assert a specific pain point.',
    evidenceFields: [], status: 'hypothesis'
  });

  const fitStatus = score >= 75 ? 'high' : score >= 50 ? 'medium' : score > 0 ? 'low' : 'insufficient_data';
  const priority = fitStatus === 'high' ? 'P1' : fitStatus === 'medium' ? 'P2' : fitStatus === 'low' ? 'P3' : 'P4';
  return { fitScore: score, dataCoveragePct: coveragePct, priority, fitStatus, reasons, hypotheses };
}

type AcquisitionPipelineLead = AcquisitionLead & { acquisitionStage?: AcquisitionStage | null; status?: string | null; fitStatus?: Qualification['fitStatus']; priority?: Qualification['priority'] | null };

export function buildPipelineMetrics(leads: AcquisitionPipelineLead[]): PipelineMetrics {
  const byStage = Object.fromEntries(ACQUISITION_STAGES.map(s => [s, 0])) as Record<AcquisitionStage, number>;
  for (const lead of leads) {
    if (lead.acquisitionStage && lead.acquisitionStage in byStage) byStage[lead.acquisitionStage] += 1;
  }
  const qualified = leads.filter(l => ['high','medium'].includes(l.fitStatus ?? 'insufficient_data') || (!l.fitStatus && typeof l.fitScore === 'number' && l.fitScore >= 50)).length;
  const prioritized = leads.filter(l => ['P1','P2','P3'].includes(l.priority ?? 'P4') || (!l.priority && typeof l.fitScore === 'number')).length;
  const contactable = leads.filter(l => has(l.phone) || has(l.instagram) || has(l.website)).length;
  const clients = byStage.client;
  return {
    total: leads.length,
    byStage,
    qualified,
    prioritized,
    contactable,
    conversionRate: prioritized > 0 ? Number(((clients / prioritized) * 100).toFixed(2)) : null,
  };
}

export type ActionStatus='planned'|'in_progress'|'blocked'|'completed'|'cancelled';
export type ActionPriority='P0'|'P1'|'P2'|'P3';
export interface ActionEvidence{source:string;period?:string;value?:string|number;notes?:string}
export interface ActionItem{id:string;title:string;owner:string;priority:ActionPriority;status:ActionStatus;dueDate?:string;measure:string;baseline?:number|null;target?:number|null;evidence:ActionEvidence[];dependencies:string[]}
export interface ActionPlan{clientId:string;objective:string;items:ActionItem[];createdAt:string;version:number}
const validStatuses=new Set<ActionStatus>(['planned','in_progress','blocked','completed','cancelled']);
export function validateActionItem(item:ActionItem){const issues:string[]=[];if(!item.id||!item.title||!item.owner)issues.push('id, title, and owner are required');if(!validStatuses.has(item.status))issues.push('invalid status');if(!item.measure)issues.push('measure is required');if(item.target!=null&&item.baseline!=null&&item.priority==='P0'&&item.target===item.baseline)issues.push('P0 target must differ from baseline');if(item.status==='completed'&&item.evidence.length===0)issues.push('completed action requires evidence');return issues}
export function buildActionPlan(input:{clientId:string;objective:string;items:ActionItem[];now?:string}):ActionPlan{const items=input.items.map(x=>({...x,evidence:[...x.evidence],dependencies:[...x.dependencies]}));const issues=items.flatMap(validateActionItem);if(issues.length)throw new Error(`INVALID_ACTION_PLAN: ${issues.join('; ')}`);return{clientId:input.clientId,objective:input.objective,items,createdAt:input.now??new Date().toISOString(),version:1}}
export function summarizeActionPlan(plan:ActionPlan){const total=plan.items.length;const completed=plan.items.filter(x=>x.status==='completed').length;const blocked=plan.items.filter(x=>x.status==='blocked').length;const weighted=plan.items.reduce((s,x)=>s+(x.status==='completed'?1:x.status==='in_progress'?.5:0),0);return{total,completed,blocked,completionPct:total?Number((completed/total*100).toFixed(1)):0,executionPct:total?Number((weighted/total*100).toFixed(1)):0}}

export type DiagnosticSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';
export type DiagnosticCategory = 'syntax' | 'missing_dependency' | 'missing_data' | 'runtime_risk' | 'performance' | 'security' | 'persistence' | 'integration' | 'file_ingestion';

export interface DiagnosticEvidence {
  file: string;
  line?: number;
  code?: string;
  reason: string;
}

export interface DiagnosticFinding {
  id: string;
  severity: DiagnosticSeverity;
  category: DiagnosticCategory;
  title: string;
  cause: string;
  impact: string;
  solution: string;
  evidence: DiagnosticEvidence[];
  confidence: number;
  status: 'confirmed' | 'suspected' | 'blocked';
}

export interface DiagnosticInput {
  files: Array<{ path: string; content: string }>;
  missingFiles?: string[];
  missingDependencies?: string[];
  runtimeErrors?: Array<{ message: string; file?: string; line?: number; stack?: string }>;
  performance?: Array<{ file?: string; metric: string; valueMs: number; thresholdMs: number }>;
}

const severityRank: Record<DiagnosticSeverity, number> = { critical: 5, high: 4, medium: 3, low: 2, info: 1 };

function lineOf(content: string, index: number): number { return content.slice(0, index).split(/\r?\n/).length; }
function snippet(content: string, index: number): string { return content.slice(Math.max(0, index - 80), Math.min(content.length, index + 180)).replace(/\s+/g, ' ').trim(); }

export function diagnoseApplication(input: DiagnosticInput): DiagnosticFinding[] {
  const findings: DiagnosticFinding[] = [];

  for (const file of input.files) {
    const path = file.path;
    const content = file.content;
    if (/\b(?:TODO|FIXME|XXX)\b|throw new Error\(['"]TODO/i.test(content)) {
      const index = content.search(/\b(?:TODO|FIXME|XXX)\b|throw new Error\(['"]TODO/i);
      findings.push({ id:`todo:${path}:${lineOf(content,index)}`, severity:'medium', category:'runtime_risk', title:'Unfinished error path detected', cause:'The file contains an explicit TODO/FIXME or placeholder error path.', impact:'The affected workflow may fail when this path is reached.', solution:'Implement the missing branch and add a regression test before release.', evidence:[{file:path,line:lineOf(content,index),code:snippet(content,index),reason:'Explicit unfinished marker detected.'}], confidence:0.99,status:'suspected' });
    }
    const infiniteLoop = /while\s*\(\s*true\s*\)/.exec(content);
    if (infiniteLoop && !/(?:break\s*;|return\b)/.test(content.slice(infiniteLoop.index, infiniteLoop.index + 1000))) {
      findings.push({ id:`loop:${path}:${lineOf(content,infiniteLoop.index)}`, severity:'high', category:'runtime_risk', title:'Potential non-terminating loop', cause:'A while(true) loop has no nearby break or return in the inspected block.', impact:'The request/job can hang, consume CPU, or prevent the UI from completing.', solution:'Add an explicit termination condition, cancellation signal, and bounded retry/deadline.', evidence:[{file:path,line:lineOf(content,infiniteLoop.index),code:snippet(content,infiniteLoop.index),reason:'Unbounded loop pattern.'}], confidence:0.9,status:'suspected' });
    }
    const fetches = [...content.matchAll(/fetch\s*\(/g)];
    if (fetches.length >= 5 && !/AbortController|AbortSignal/.test(content)) {
      const idx = fetches[0].index ?? 0;
      findings.push({ id:`fetch-timeout:${path}`, severity:'medium', category:'performance', title:'Network calls without visible cancellation', cause:`The file contains ${fetches.length} fetch calls but no AbortController/AbortSignal reference.`, impact:'Slow or stalled providers can hold the workflow open longer than intended.', solution:'Use bounded request deadlines and propagate AbortSignal through provider calls.', evidence:[{file:path,line:lineOf(content,idx),code:snippet(content,idx),reason:'Multiple network calls without cancellation primitive.'}], confidence:0.86,status:'suspected' });
    }
    if (/\.map\([^\n]+=>[^\n]+fetch\s*\(/.test(content)) {
      const idx = content.search(/\.map\([^\n]+=>[^\n]+fetch\s*\(/);
      findings.push({ id:`parallel-map-fetch:${path}:${lineOf(content,idx)}`, severity:'medium', category:'performance', title:'Potential unbounded request fan-out', cause:'fetch appears inside a map callback, which can launch one request per item.', impact:'Large datasets can create bursts, rate limiting, memory pressure, or slowdowns.', solution:'Replace with a bounded concurrency pool and global deadline.', evidence:[{file:path,line:lineOf(content,idx),code:snippet(content,idx),reason:'fetch inside map pattern.'}], confidence:0.82,status:'suspected' });
    }
    if (/localStorage\.(setItem|removeItem)\([^\n]*(JSON\.stringify\([^\n]*\*|LEADS|acquisitionLeads)/.test(content)) {
      const idx = content.search(/localStorage\.(setItem|removeItem)/);
      findings.push({ id:`storage:${path}:${lineOf(content,idx)}`, severity:'medium', category:'persistence', title:'Large client-side persistence path detected', cause:'Operational data appears to be serialized into localStorage.', impact:'Large writes can block the main thread and are not a durable transactional database workflow.', solution:'Use relational Supabase persistence with batch checkpoints and retain localStorage only as a bounded compatibility fallback.', evidence:[{file:path,line:lineOf(content,idx),code:snippet(content,idx),reason:'Client-side operational persistence pattern.'}], confidence:0.88,status:'suspected' });
    }
  }

  for (const path of input.missingFiles ?? []) findings.push({ id:`missing-file:${path}`, severity:'high', category:'integration', title:'Referenced file is missing', cause:`The expected file ${path} is unavailable.`, impact:'Imports, routes, builds, or runtime workflows depending on it may fail.', solution:'Restore the file or update the reference to the canonical existing file, then run the relevant regression test.', evidence:[{file:path,reason:'Declared missing file.'}], confidence:1,status:'confirmed' });
  for (const dep of input.missingDependencies ?? []) findings.push({ id:`missing-dep:${dep}`, severity:'high', category:'missing_dependency', title:'Required dependency is unavailable', cause:`Dependency ${dep} is not installed or cannot be resolved.`, impact:'Build/typecheck/runtime may fail before the affected feature can start.', solution:`Install and lock ${dep}, then rerun typecheck/build and runtime tests. Do not claim PASS while dependency resolution is blocked.`, evidence:[{file:'package.json',reason:`Dependency resolution reported missing: ${dep}`}], confidence:1,status:'blocked' });
  for (const error of input.runtimeErrors ?? []) findings.push({ id:`runtime:${error.file ?? 'unknown'}:${error.line ?? 0}:${error.message}`, severity:'critical', category:'runtime_risk', title:'Runtime error reported', cause:error.message, impact:'The reported execution path failed at runtime.', solution:'Inspect the referenced file/line, reproduce the failure, fix the root cause, and add a regression test. Do not suppress the error.', evidence:[{file:error.file ?? 'runtime',line:error.line,code:error.stack,reason:'Runtime error telemetry.'}], confidence:1,status:'confirmed' });
  for (const p of input.performance ?? []) if (p.valueMs > p.thresholdMs) findings.push({ id:`perf:${p.file ?? 'runtime'}:${p.metric}`, severity:p.valueMs > p.thresholdMs * 2 ? 'high' : 'medium', category:'performance', title:`${p.metric} exceeded performance budget`, cause:`Measured ${p.valueMs}ms against a ${p.thresholdMs}ms budget.`, impact:'The workflow is slower than the defined performance target.', solution:'Profile the measured path, identify the slow operation, then optimize or move work off the critical UI/request path while preserving correctness.', evidence:[{file:p.file ?? 'runtime',reason:'Measured performance telemetry.'}], confidence:1,status:'confirmed' });

  return findings.sort((a,b)=>severityRank[b.severity]-severityRank[a.severity] || a.id.localeCompare(b.id));
}

export function summarizeDiagnostics(findings: DiagnosticFinding[]) {
  const counts = findings.reduce<Record<DiagnosticSeverity,number>>((acc,f)=>{ acc[f.severity]++; return acc; }, {critical:0,high:0,medium:0,low:0,info:0});
  return { total: findings.length, counts, releaseBlocked: findings.some(f=>f.status === 'confirmed' && (f.severity === 'critical' || f.severity === 'high')) };
}

export type EvolutionPriority='P0'|'P1'|'P2'|'P3'; export type EvolutionStatus='suggested'|'approved'|'rejected'|'applied'|'blocked';
export interface UsageSignal{feature:string;uses:number;failures:number;avgDurationMs?:number;completionRate?:number;missingDataRate?:number}
export interface EvolutionRecommendation{id:string;priority:EvolutionPriority;title:string;rationale:string;evidence:string[];expectedImpact:string;status:EvolutionStatus;requiresApproval:true}
export function buildEvolutionRecommendations(signals:UsageSignal[]):EvolutionRecommendation[]{const out:EvolutionRecommendation[]=[];for(const s of signals){if(s.failures>=3)out.push({id:`failure:${s.feature}`,priority:s.failures>=10?'P0':'P1',title:`Stabilize ${s.feature}`,rationale:'Failure frequency is high enough to prioritize reliability before adding features.',evidence:[`${s.failures} failures across ${s.uses} uses.`],expectedImpact:'Reduce operational errors.',status:'suggested',requiresApproval:true});if(typeof s.completionRate==='number'&&s.completionRate<.7&&s.uses>=5)out.push({id:`dropoff:${s.feature}`,priority:'P1',title:`Improve ${s.feature} workflow completion`,rationale:'A significant portion of users leave before completion.',evidence:[`Completion rate: ${(s.completionRate*100).toFixed(1)}%.`],expectedImpact:'Reduce workflow drop-off.',status:'suggested',requiresApproval:true});if(typeof s.missingDataRate==='number'&&s.missingDataRate>.3&&s.uses>=5)out.push({id:`data:${s.feature}`,priority:'P1',title:`Improve data completeness in ${s.feature}`,rationale:'Missing-data frequency is materially affecting downstream analysis.',evidence:[`Missing-data rate: ${(s.missingDataRate*100).toFixed(1)}%.`],expectedImpact:'Increase evidence quality without inventing values.',status:'suggested',requiresApproval:true});if(typeof s.avgDurationMs==='number'&&s.avgDurationMs>5000&&s.uses>=5)out.push({id:`perf:${s.feature}`,priority:'P1',title:`Optimize ${s.feature} performance`,rationale:'Observed latency is high for an interactive workflow.',evidence:[`Average duration: ${Math.round(s.avgDurationMs)}ms.`],expectedImpact:'Shorter workflows and lower resource pressure.',status:'suggested',requiresApproval:true});}return out}

export type MaintenanceEnvironment='workspace'|'staging'|'production';
export type MaintenanceAction='inspect'|'diagnose'|'generate_patch'|'run_tests'|'apply_patch'|'commit'|'push'|'merge'|'migrate'|'deploy';
export interface MaintenanceApproval{id:string;action:MaintenanceAction;environment:MaintenanceEnvironment;approvedBy:string|null;approvedAt:string|null;expiresAt:string|null}
const WRITES=new Set<MaintenanceAction>(['apply_patch','commit','push','merge','migrate','deploy']);
export function requiresApproval(action:MaintenanceAction,environment:MaintenanceEnvironment){return environment==='production'||WRITES.has(action)}
export function validateApproval(a:MaintenanceApproval,action:MaintenanceAction,environment:MaintenanceEnvironment,now=Date.now()){if(a.action!==action||a.environment!==environment)return{ok:false,reason:'approval_scope_mismatch'};if(!a.approvedBy||!a.approvedAt)return{ok:false,reason:'approval_missing'};if(a.expiresAt&&Date.parse(a.expiresAt)<=now)return{ok:false,reason:'approval_expired'};return{ok:true as const}}
export function canDeployAfterExplicitApproval(a:MaintenanceApproval,now=Date.now()){return validateApproval(a,'deploy','production',now).ok}
export function deploymentDecision(a:MaintenanceApproval|null){if(!a)return{allowed:false,reason:'confirmation_required'};const check=validateApproval(a,'deploy','production');return check.ok?{allowed:true,reason:'explicit_approval_valid'}:{allowed:false,reason:check.reason}}

export type SecuritySeverity='critical'|'high'|'medium'|'low'|'info';
export type SecurityStatus='confirmed'|'suspected'|'blocked'|'healthy';
export type SecurityCategory='auth'|'rls'|'secrets'|'data_access'|'api'|'dependency'|'anomaly'|'transport';
export interface SecurityEvidence{source:string;detail:string;file?:string;line?:number}
export interface SecurityFinding{id:string;severity:SecuritySeverity;category:SecurityCategory;status:SecurityStatus;title:string;cause:string;impact:string;recommendation:string;evidence:SecurityEvidence[]}
export interface SecurityTelemetryEvent{kind:'auth'|'data_access'|'network'|'runtime'|'supabase'|'job';event:Record<string,unknown>;timestamp?:string}
const rank:Record<SecuritySeverity,number>={critical:5,high:4,medium:3,low:2,info:1};
export function analyzeSecurity(files:Array<{path:string;content:string}>,telemetry:SecurityTelemetryEvent[]=[]):SecurityFinding[]{
 const out:SecurityFinding[]=[]; const add=(x:Omit<SecurityFinding,'id'>,id:string)=>out.push({...x,id});
 for(const file of files){const c=file.content;
  if(/(?:SUPABASE_SERVICE_ROLE_KEY|SERVICE_ROLE|PRIVATE_KEY|SECRET_KEY)\s*=\s*["'`]?\w[\w.\-]{15,}/.test(c)) add({severity:'critical',category:'secrets',status:'confirmed',title:'Potential secret embedded in source',cause:'A privileged/secret key pattern appears in source.',impact:'A leaked repository or bundle could expose privileged credentials.',recommendation:'Remove it from source, rotate it if real, and keep privileged keys server-side only.',evidence:[{source:'static scan',file:file.path,detail:'Secret-like assignment detected.'}]},`secret:${file.path}`);
  if(/createClient\([^\n]*(SERVICE_ROLE|service_role)|Authorization:\s*`Bearer \$\{[^}]*SERVICE_ROLE/i.test(c)) add({severity:'critical',category:'data_access',status:'suspected',title:'Privileged Supabase credential may reach client code',cause:'Client-visible code appears to reference a service-role credential.',impact:'An ordinary user could potentially gain privileged database access.',recommendation:'Use only the publishable/anon key in the browser; keep service-role access inside trusted server functions.',evidence:[{source:'static scan',file:file.path,detail:'Privileged credential reference detected.'}]},`priv-client:${file.path}`);
  if(/localStorage\.(?:setItem|getItem)\([^\n]*(?:token|session|password|secret|apikey)/i.test(c)) add({severity:'high',category:'secrets',status:'suspected',title:'Sensitive authentication material may be stored in localStorage',cause:'Local storage uses a token/session/password/secret-like key.',impact:'XSS or a compromised browser context could expose reusable credentials.',recommendation:'Prefer the auth library session mechanism and secure cookies where applicable; never persist secrets manually.',evidence:[{source:'static scan',file:file.path,detail:'Sensitive localStorage key pattern detected.'}]},`storage-secret:${file.path}`);
  if(/Access-Control-Allow-Origin[^\n]*\*/i.test(c)) add({severity:'medium',category:'transport',status:'confirmed',title:'Wildcard CORS detected',cause:'The response policy allows every origin.',impact:'Cross-origin callers may reach the endpoint if other controls fail.',recommendation:'Use an explicit production origin allowlist.',evidence:[{source:'static scan',file:file.path,detail:'Wildcard CORS policy detected.'}]},`cors:${file.path}`);
 }
 const authFailures=telemetry.filter(x=>x.kind==='auth'&&/fail|denied|invalid|expired|unauthorized|forbidden/i.test(JSON.stringify(x.event))).length;
 if(authFailures>=5) add({severity:'high',category:'anomaly',status:'confirmed',title:'Repeated authentication failures detected',cause:`${authFailures} authentication failure events were recorded.`,impact:'Could indicate credential abuse, session probing, or a misconfigured integration.',recommendation:'Inspect server-side audit evidence, rate-limit the endpoint, revoke suspicious sessions, and review access logs.',evidence:[{source:'runtime telemetry',detail:`${authFailures} matching auth-failure events.`}]},'auth-failure-burst');
 return out.sort((a,b)=>rank[b.severity]-rank[a.severity]||a.id.localeCompare(b.id));
}
export function securityStatus(findings:SecurityFinding[]){if(findings.some(f=>f.status==='confirmed'&&f.severity==='critical'))return 'CRITICAL' as const;if(findings.some(f=>f.status==='confirmed'&&(f.severity==='high'||f.severity==='critical')))return 'HIGH_RISK' as const;if(findings.some(f=>f.status==='suspected'))return 'REVIEW' as const;return 'NO_CONFIRMED_FINDING' as const}

import type { POSAnomaly } from './posHealth.js';
import type { InventoryVariance } from './inventoryIntelligence.js';
export type AlertSeverity='INFO'|'LOW'|'MEDIUM'|'HIGH'|'CRITICAL';
export interface BusinessAlert { id:string; severity:AlertSeverity; title:string; what:string; why:string; impact:number|null; confidence:string; evidenceIds:string[]; status:'OPEN'|'ACKNOWLEDGED'|'RESOLVED'|'DISMISSED'; createdAt:string; }
export function buildAlerts(anomalies:POSAnomaly[], inventory:InventoryVariance[], now=new Date().toISOString()):BusinessAlert[]{
 const out:BusinessAlert[]=[];
 anomalies.forEach(a=>out.push({id:`anomaly:${a.code}:${a.evidenceIds[0]??'none'}`,severity:a.severity,title:a.title,what:a.explanation,why:'Baseline comparison atau event langsung menunjukkan pola yang perlu ditinjau.',impact:a.financialImpact,confidence:a.confidence,evidenceIds:a.evidenceIds,status:'OPEN',createdAt:now}));
 inventory.filter(v=>v.status==='HIGH_VARIANCE'||v.status==='WATCH').forEach(v=>out.push({id:`inventory:${v.itemId}`,severity:v.status==='HIGH_VARIANCE'?'HIGH':'MEDIUM',title:'Inventory variance terdeteksi',what:`Variance ${v.varianceQty===null?'tidak dapat dihitung':v.varianceQty.toFixed(2)} unit pada item ${v.itemId}.`,why:'Perbandingan theoretical consumption dengan actual inventory movement.',impact:v.estimatedImpact,confidence:v.expectedQty===null?'INSUFFICIENT DATA':'HIGH CONFIDENCE',evidenceIds:v.evidenceIds,status:'OPEN',createdAt:now}));
 return out;
}

export type AuditAction='create'|'update'|'delete'|'approve'|'reject'|'execute'|'login'|'security';
export interface AuditEvent { id:string; actorUserId:string; action:AuditAction; entityType:string; entityId:string; occurredAt:string; before?:unknown; after?:unknown; reason?:string; correlationId?:string; }
export function validateAuditEvent(e:AuditEvent){const issues:string[]=[];if(!e.id||!e.actorUserId||!e.entityType||!e.entityId||!e.occurredAt)issues.push('audit identity fields are required');if(!['create','update','delete','approve','reject','execute','login','security'].includes(e.action))issues.push('invalid action');if(e.action==='update'&&e.before===undefined&&e.after===undefined)issues.push('update requires before or after state');return issues}
export function auditDiff(before:Record<string,unknown>|null,after:Record<string,unknown>|null){const keys=new Set([...Object.keys(before??{}),...Object.keys(after??{})]);return [...keys].filter(k=>JSON.stringify(before?.[k])!==JSON.stringify(after?.[k])).map(k=>({field:k,before:before?.[k],after:after?.[k]}));}
export function assertAppendOnly(existing:AuditEvent[], incoming:AuditEvent[]){const ids=new Set(existing.map(e=>e.id));for(const e of incoming){if(ids.has(e.id))throw new Error(`AUDIT_DUPLICATE_ID: ${e.id}`);ids.add(e.id);}return true;}

/**
 * ============================================================================
 * NERACA (BALANCE SHEET)
 * ============================================================================
 * Ini modul yang paling penting yang sebelumnya belum ada di TRACE.
 * Tanpa Neraca, TRACE baru bisa menjawab "apakah bisnis untung bulan ini"
 * (lewat Laba Rugi), tapi TIDAK bisa menjawab "berapa total kekayaan bisnis
 * ini sekarang, dan dari mana sumbernya (utang atau modal sendiri)".
 *
 * Prinsip dasar Neraca yang tidak boleh dilanggar:
 *     TOTAL ASET  =  TOTAL LIABILITAS  +  TOTAL EKUITAS
 * Kalau angka ini tidak sama (`balanced: false`), itu tanda pasti ada
 * kesalahan input jurnal yang HARUS dicek sebelum laporan dikirim ke klien —
 * bukan sekadar selisih pembulatan yang boleh diabaikan.
 */

import type { AccountingBalance, TrialBalance } from './accounting.js';
import { normalBalanceOf } from './chartOfAccounts.js';
import type { AccountSubType, AccountWithSubType } from './chartOfAccounts.js';

export interface BalanceSheetLine {
  accountId: string;
  accountCode: string;
  accountName: string;
  balance: number;
}

export interface BalanceSheetGroup {
  subType: AccountSubType;
  label: string;
  lines: BalanceSheetLine[];
  total: number;
}

export interface BalanceSheet {
  asOfPeriod: string;
  asetLancar: BalanceSheetGroup;
  asetTetap: BalanceSheetGroup;
  totalAset: number;
  liabilitasLancar: BalanceSheetGroup;
  liabilitasJangkaPanjang: BalanceSheetGroup;
  totalLiabilitas: number;
  ekuitas: BalanceSheetGroup;
  /** Laba/rugi bersih periode berjalan (dari Income Statement), yang secara
   *  akuntansi ikut menambah Ekuitas SELAMA buku belum ditutup (lihat periodClose.ts).
   *  Kalau ini `null`, berarti Laba Rugi periode ini belum dihitung — Neraca
   *  tidak dipaksa "balanced" secara palsu dengan menganggapnya 0. */
  labaBerjalan: number | null;
  totalEkuitas: number;
  totalLiabilitasDanEkuitas: number;
  /** true hanya kalau Total Aset benar-benar sama dengan Total Liabilitas + Ekuitas,
   *  DAN tidak ada akun yang datanya hilang dari Trial Balance. */
  balanced: boolean;
  /** Selisih Total Aset dikurangi (Total Liabilitas + Ekuitas). Harusnya 0.
   *  Kalau tidak 0, ini bukti konkret ada jurnal yang salah/tidak seimbang. */
  selisih: number;
  missingAccountIds: string[];
}

const GROUP_LABEL: Record<AccountSubType, string> = {
  aset_lancar: 'Aset Lancar',
  aset_tetap: 'Aset Tetap',
  liabilitas_lancar: 'Liabilitas Jangka Pendek',
  liabilitas_jangka_panjang: 'Liabilitas Jangka Panjang',
  ekuitas: 'Ekuitas',
  pendapatan_usaha: 'Pendapatan Usaha',
  harga_pokok_penjualan: 'Harga Pokok Penjualan',
  beban_operasional: 'Beban Operasional',
};

function buildGroup(
  subType: AccountSubType,
  accounts: AccountWithSubType[],
  balances: Map<string, AccountingBalance>,
): BalanceSheetGroup {
  const lines: BalanceSheetLine[] = accounts
    .filter(a => a.subType === subType)
    .map(a => {
      const b = balances.get(a.id);
      const stored = b ? b.balance : 0; // accounting.ts selalu menyimpan saldo sebagai (debit − credit)
      // Untuk akun yang saldo normalnya KREDIT (Liabilitas, Ekuitas), (debit − credit) akan
      // tampil dengan tanda TERBALIK dari yang seharusnya dilaporkan (mis. Modal Rp10jt yang
      // dicatat lewat kredit akan tersimpan sebagai -10.000.000). Baris ini membalik tandanya
      // supaya Neraca menampilkan angka yang benar — tanpa ini, Total Aset TIDAK PERNAH akan
      // sama dengan Total Liabilitas + Ekuitas walaupun jurnalnya sendiri sudah seimbang.
      const raw = normalBalanceOf(a.type) === 'credit' ? -stored : stored;
      // Akun kontra-aset (mis. "Akumulasi Penyusutan") tetap bertipe 'asset' (saldo normal debit
      // menurut normalBalanceOf), padahal secara praktik selalu bertambah lewat sisi kredit dan
      // harus tampil sebagai PENGURANG di kelompok Aset, bukan dijumlah biasa seperti aset lain.
      const isContraAsset = a.type === 'asset' && a.name.toLowerCase().includes('akumulasi penyusutan');
      return {
        accountId: a.id,
        accountCode: a.code,
        accountName: a.name,
        balance: isContraAsset ? -Math.abs(raw) : raw,
      };
    })
    .filter(line => line.balance !== 0); // akun yang belum pernah dipakai tidak perlu memenuhi laporan

  return { subType, label: GROUP_LABEL[subType], lines, total: lines.reduce((s, l) => s + l.balance, 0) };
}

export function buildBalanceSheet(
  accounts: AccountWithSubType[],
  trialBalance: TrialBalance,
  asOfPeriod: string,
  labaBerjalanSaatIni: number | null,
): BalanceSheet {
  const balances = new Map(trialBalance.accounts.map(b => [b.accountId, b]));

  const asetLancar = buildGroup('aset_lancar', accounts, balances);
  const asetTetap = buildGroup('aset_tetap', accounts, balances);
  const totalAset = asetLancar.total + asetTetap.total;

  const liabilitasLancar = buildGroup('liabilitas_lancar', accounts, balances);
  const liabilitasJangkaPanjang = buildGroup('liabilitas_jangka_panjang', accounts, balances);
  const totalLiabilitas = liabilitasLancar.total + liabilitasJangkaPanjang.total;

  const ekuitas = buildGroup('ekuitas', accounts, balances);
  const totalEkuitas = ekuitas.total + (labaBerjalanSaatIni ?? 0);

  const totalLiabilitasDanEkuitas = totalLiabilitas + totalEkuitas;
  const selisih = Math.round((totalAset - totalLiabilitasDanEkuitas) * 100) / 100;

  return {
    asOfPeriod,
    asetLancar,
    asetTetap,
    totalAset,
    liabilitasLancar,
    liabilitasJangkaPanjang,
    totalLiabilitas,
    ekuitas,
    labaBerjalan: labaBerjalanSaatIni,
    totalEkuitas,
    totalLiabilitasDanEkuitas,
    balanced: Math.abs(selisih) < 0.5 && trialBalance.missingAccountIds.length === 0,
    selisih,
    missingAccountIds: trialBalance.missingAccountIds,
  };
}

/** Browser-side bounded request helper. A caller timeout must cancel the underlying fetch. */
export async function fetchWithTimeout(url:string, options:RequestInit={}, timeoutMs=15000):Promise<Response>{
  if(!Number.isFinite(timeoutMs) || timeoutMs<=0) throw new Error('INVALID_TIMEOUT');
  const controller=new AbortController();
  const parent=options.signal;
  const abort=()=>controller.abort();
  if(parent){if(parent.aborted) controller.abort(); else parent.addEventListener('abort',abort,{once:true});}
  const timer=setTimeout(()=>controller.abort(),timeoutMs);
  try{return await fetch(url,{...options,signal:controller.signal});}
  finally{clearTimeout(timer);if(parent)parent.removeEventListener('abort',abort);}
}

export type EntityStatus = 'active' | 'inactive' | 'archived';

export interface Client {
  id: string;
  name: string;
  status: EntityStatus;
  createdAt?: string;
  updatedAt?: string;
}

export interface Company {
  id: string;
  clientId: string;
  name: string;
  status: EntityStatus;
}

export interface Brand {
  id: string;
  companyId: string;
  name: string;
  status: EntityStatus;
}

export interface Outlet {
  id: string;
  brandId: string;
  name: string;
  address?: string;
  city?: string;
  status: EntityStatus;
}

export interface BusinessHierarchy {
  clients: Client[];
  companies: Company[];
  brands: Brand[];
  outlets: Outlet[];
}

export interface BusinessTwinSummary {
  client: Client;
  companies: Company[];
  brands: Brand[];
  outlets: Outlet[];
  counts: { companies: number; brands: number; outlets: number };
}

export function validateHierarchy(data: BusinessHierarchy): string[] {
  const errors: string[] = [];
  const clientIds = new Set(data.clients.map(x => x.id));
  const companyIds = new Set(data.companies.map(x => x.id));
  const brandIds = new Set(data.brands.map(x => x.id));
  for (const company of data.companies) if (!clientIds.has(company.clientId)) errors.push(`Company ${company.id} references missing client ${company.clientId}`);
  for (const brand of data.brands) if (!companyIds.has(brand.companyId)) errors.push(`Brand ${brand.id} references missing company ${brand.companyId}`);
  for (const outlet of data.outlets) if (!brandIds.has(outlet.brandId)) errors.push(`Outlet ${outlet.id} references missing brand ${outlet.brandId}`);
  return errors;
}

export function buildBusinessTwin(data: BusinessHierarchy, clientId: string): BusinessTwinSummary | null {
  const client = data.clients.find(x => x.id === clientId);
  if (!client) return null;
  const companies = data.companies.filter(x => x.clientId === clientId);
  const companyIds = new Set(companies.map(x => x.id));
  const brands = data.brands.filter(x => companyIds.has(x.companyId));
  const brandIds = new Set(brands.map(x => x.id));
  const outlets = data.outlets.filter(x => brandIds.has(x.brandId));
  return { client, companies, brands, outlets, counts: { companies: companies.length, brands: brands.length, outlets: outlets.length } };
}

import type { EvidenceItem } from './evidence.js';
import { explainScore, type ScoreDimension } from './intelligence.js';
import type { FinanceSummary } from './finance.js';
import type { POSHealthResult } from './posHealth.js';
import type { InventoryVariance } from './inventoryIntelligence.js';
export interface BusinessHealthResult { score:number|null; dimensions:Array<ScoreDimension & {methodology:string}>; confidencePct:number|null; why:string[]; evidence:ReturnType<typeof explainScore>['evidence']; }
const clamp=(v:number)=>Math.max(0,Math.min(100,v));
function average(values:number[]):number|null{return values.length?values.reduce((a,b)=>a+b,0)/values.length:null;}
function financeScore(f:FinanceSummary):{value:number|null;methodology:string}{
 const parts:number[]=[];
 if(f.operatingMarginPct!==null) parts.push(clamp(f.operatingMarginPct/20*100));
 if(f.cogsPct!==null) parts.push(clamp((50-f.cogsPct)/15*100));
 if(f.laborPct!==null) parts.push(clamp((35-f.laborPct)/15*100));
 if(f.opexPct!==null) parts.push(clamp((30-f.opexPct)/15*100));
 return {value:average(parts),methodology:'Rata-rata sub-score tersedia: operating margin target 20%; COGS target <=35%; labor target <=20%; OPEX target <=15%. Nilai di luar batas dikunci 0–100.'};
}
export function buildBusinessHealth(input:{finance:FinanceSummary;pos?:POSHealthResult|null;inventory?:InventoryVariance[];marketingScore?:number|null;evidence:EvidenceItem[]}):BusinessHealthResult{
 const f=input.finance; const fin=financeScore(f);
 const inv=input.inventory?.length?clamp(100-input.inventory.filter(v=>v.status==='HIGH_VARIANCE').length/input.inventory.length*100):null;
 const risk=input.pos?clamp(100-input.pos.anomalies.reduce((s,a)=>s+(a.severity==='CRITICAL'?30:a.severity==='HIGH'?20:a.severity==='MEDIUM'?10:5),0)):null;
 const dimensions=( [
  {key:'financial',label:'Financial Health',value:fin.value,weight:30,evidence:['finance'],methodology:fin.methodology},
  {key:'pos',label:'POS Health',value:input.pos?.score??null,weight:15,evidence:['pos'],methodology:'100 dikurangi penalty anomaly berbobot severity; transaksi kosong menghasilkan data tidak tersedia.'},
  {key:'cash',label:'Cash Health',value:null,weight:15,evidence:['cash'],methodology:'Belum dihitung karena canonical cash movement/reconciliation belum tersedia; tidak dipaksa menjadi 0.'},
  {key:'inventory',label:'Inventory Health',value:inv,weight:15,evidence:['inventory'],methodology:'100 dikurangi proporsi item berstatus HIGH_VARIANCE; tanpa inventory evidence hasil tidak tersedia.'},
  {key:'marketing',label:'Marketing Health',value:input.marketingScore??null,weight:10,evidence:['marketing'],methodology:'Hanya digunakan bila marketing score berasal dari data terukur; tidak ada score default.'},
  {key:'operations',label:'Operational Health',value:f.grossMarginPct===null?null:clamp(f.grossMarginPct/65*100),weight:10,evidence:['finance'],methodology:'Gross margin dibandingkan target 65%; dikunci 0–100.'},
  {key:'risk',label:'Risk Health',value:risk,weight:5,evidence:['risk'],methodology:'100 dikurangi penalty severity anomaly POS; anomaly bukan bukti fraud.'}
 ] as Array<ScoreDimension & {methodology:string}>);
 const result=explainScore(dimensions,input.evidence); return {score:result.score,dimensions:result.dimensions.map(d=>({...d,methodology:dimensions.find(x=>x.key===d.key)!.methodology})),confidencePct:result.confidencePct,why:result.why,evidence:result.evidence};
}

export interface CalculationInput {
  current: number;
  previous?: number | null;
  metric: string;
  currentPeriod: string;
  previousPeriod?: string;
  source: string;
}

export interface CalculationResult {
  metric: string;
  current: number;
  previous: number | null;
  change: number | null;
  changePct: number | null;
  formula: string;
  source: string;
  currentPeriod: string;
  previousPeriod: string | null;
  status: 'calculated' | 'insufficient_data' | 'undefined_baseline';
  explanation: string;
}

export function calculateChange(input: CalculationInput): CalculationResult {
  const { current, previous = null } = input;
  if (!Number.isFinite(current)) {
    return { ...base(input), change: null, changePct: null, status: 'insufficient_data', explanation: 'Data belum cukup untuk menghitung perubahan.' };
  }
  if (previous === null || !Number.isFinite(previous)) {
    return { ...base(input), change: null, changePct: null, status: 'insufficient_data', explanation: 'Data periode pembanding tidak tersedia.' };
  }
  const change = current - previous;
  if (previous === 0) {
    return { ...base(input), change, changePct: null, status: 'undefined_baseline', explanation: `Perubahan absolut ${format(current)} - ${format(previous)} = ${format(change)}. Persentase tidak dihitung karena baseline 0.` };
  }
  const changePct = (change / previous) * 100;
  const direction = change > 0 ? 'meningkat' : change < 0 ? 'menurun' : 'tetap';
  return {
    ...base(input), change, changePct,
    status: 'calculated',
    explanation: `${input.metric} ${input.currentPeriod} ${format(current)} dibanding ${input.previousPeriod || 'periode sebelumnya'} ${format(previous)} → ${direction} ${format(changePct)}%. Formula: (current - previous) / previous × 100.`
  };
}

function base(input: CalculationInput) {
  return {
    metric: input.metric,
    current: input.current,
    previous: input.previous ?? null,
    formula: '(current - previous) / previous × 100',
    source: input.source,
    currentPeriod: input.currentPeriod,
    previousPeriod: input.previousPeriod ?? null
  };
}

function format(value: number) { return Number.isInteger(value) ? String(value) : value.toFixed(2); }

export type DataProvider = 'moka'|'pawoon'|'majoo'|'qasir'|'custom_pos'|'csv'|'excel'|'api'|'webhook'|'manual'|'unknown';
export interface DataProvenance { source: string; provider: DataProvider; recordId: string; importedAt: string; normalizedAt: string; sourceFile?: string; sourceRow?: number; }
export interface CanonicalSale { id:string; organizationId:string; outletId?:string; cashierId?:string; employeeId?:string; customerId?:string; productId?:string; productName:string; qty:number; unitPrice:number; grossAmount:number; discountAmount:number; netAmount:number; paymentAmount:number; currency:string; soldAt:string; status:'completed'|'voided'|'refunded'|'comped'|'cancelled'; source:DataProvenance; }
export interface ValidationIssue { code:string; field:string; severity:'error'|'warning'; message:string; }
export interface ValidationResult<T> { valid:boolean; value:T|null; issues:ValidationIssue[]; }

const money=(n:number)=>Number.isFinite(n)&&n>=0;
export function validateCanonicalSale(sale:CanonicalSale, now=new Date()):ValidationResult<CanonicalSale>{
  const issues:ValidationIssue[]=[];
  if(!sale.id) issues.push({code:'MISSING_ID',field:'id',severity:'error',message:'Sale ID wajib ada.'});
  if(!sale.organizationId) issues.push({code:'MISSING_ORG',field:'organizationId',severity:'error',message:'Organization wajib ada.'});
  if(!sale.productName.trim()) issues.push({code:'MISSING_PRODUCT',field:'productName',severity:'error',message:'Nama produk wajib ada.'});
  if(!Number.isFinite(sale.qty)||sale.qty<=0) issues.push({code:'INVALID_QTY',field:'qty',severity:'error',message:'Qty harus lebih besar dari 0.'});
  for(const field of ['unitPrice','grossAmount','discountAmount','netAmount','paymentAmount'] as const) if(!money(sale[field])) issues.push({code:'INVALID_AMOUNT',field,severity:'error',message:`${field} harus berupa angka >= 0.`});
  if(sale.discountAmount>sale.grossAmount) issues.push({code:'DISCOUNT_EXCEEDS_GROSS',field:'discountAmount',severity:'error',message:'Discount tidak boleh melebihi gross amount.'});
  if(Math.abs(sale.netAmount-(sale.grossAmount-sale.discountAmount))>0.01) issues.push({code:'TOTAL_MISMATCH',field:'netAmount',severity:'error',message:'Net amount tidak konsisten dengan gross - discount.'});
  if(!/^[A-Z]{3}$/.test(sale.currency)) issues.push({code:'INVALID_CURRENCY',field:'currency',severity:'error',message:'Currency harus ISO 4217 3 huruf.'});
  const d=new Date(sale.soldAt); if(Number.isNaN(d.getTime())) issues.push({code:'INVALID_TIMESTAMP',field:'soldAt',severity:'error',message:'Timestamp transaksi tidak valid.'}); else if(d>now) issues.push({code:'FUTURE_TIMESTAMP',field:'soldAt',severity:'error',message:'Timestamp transaksi berada di masa depan.'});
  if(!sale.source.provider||!sale.source.recordId) issues.push({code:'MISSING_PROVENANCE',field:'source',severity:'error',message:'Provider dan record ID wajib untuk provenance.'});
  return {valid:issues.every(i=>i.severity!=='error'),value:issues.some(i=>i.severity==='error')?null:sale,issues};
}

export interface ImportDuplicate { recordId:string; occurrences:number[]; }
export function detectDuplicateRecordIds(rows:Array<{recordId:string}>, limit=100):ImportDuplicate[]{
  const seen=new Map<string,number[]>(); rows.forEach((r,i)=>{const id=r.recordId.trim(); if(!id)return; const list=seen.get(id)??[]; list.push(i+1); seen.set(id,list);});
  return [...seen.entries()].filter(([,rows])=>rows.length>1).slice(0,limit).map(([recordId,occurrences])=>({recordId,occurrences}));
}

import { normalizeHeader, parseAmount } from './dataIntake.js';

export type CanonicalEventType = 'sale'|'void'|'refund'|'discount'|'price_override'|'payment'|'cash_discrepancy'|'comp'|'cancellation';
export type CanonicalImportStatus = 'VALID'|'INVALID'|'DUPLICATE';

export interface CanonicalPOSEventInput {
  sourceRecordId: string;
  outletId?: string;
  employeeId?: string;
  cashierId?: string;
  productId?: string;
  productName?: string;
  qty: number;
  unitPrice: number;
  grossAmount: number;
  discountAmount: number;
  netAmount: number;
  paymentAmount: number;
  amount: number;
  currency: string;
  occurredAt: string;
  type: CanonicalEventType;
  status: CanonicalImportStatus;
  sourceFile: string;
  sourceSheet?: string;
  sourceRow: number;
  raw: Record<string, unknown>;
  issues: string[];
}

const aliases: Record<string,string[]> = {
  sourceRecordId:['id','record id','record_id','transaction id','transaction_id','trx id','trx_id','no transaksi','nomor transaksi','invoice','invoice id','order id','order_id','receipt','receipt id','struk'],
  outletId:['outlet id','outlet_id','branch id','branch_id','cabang id','cabang_id'],
  outletName:['outlet','outlet name','nama outlet','cabang','branch','lokasi'],
  employeeId:['employee id','employee_id','staff id','staff_id','pegawai id'],
  cashierId:['cashier id','cashier_id','kasir id','kasir_id'],
  productId:['product id','product_id','item id','item_id','sku','kode produk','kode barang'],
  productName:['product','product name','product_name','item','item name','item_name','nama produk','nama barang','menu'],
  qty:['qty','quantity','jumlah','kuantitas'],
  unitPrice:['unit price','unit_price','harga satuan','harga jual','selling price','price'],
  grossAmount:['gross','gross amount','gross_amount','subtotal','total sebelum diskon'],
  discountAmount:['discount','discount amount','discount_amount','diskon','potongan'],
  netAmount:['net','net amount','net_amount','total','total amount','grand total','net sales','penjualan bersih'],
  paymentAmount:['payment','payment amount','payment_amount','paid','dibayar','jumlah bayar'],
  currency:['currency','mata uang','currency code'],
  occurredAt:['sold at','sold_at','occurred at','occurred_at','transaction date','transaction_date','tanggal transaksi','tanggal','date','datetime','timestamp','waktu'],
  type:['event type','event_type','type','jenis transaksi','jenis event','status transaksi','transaction status','status'],
  status:['status','transaction status','status transaksi']
};

export function findColumn(headers: unknown[], key: string): number {
  const normalized = headers.map(normalizeHeader);
  const candidates = aliases[key] ?? [key];
  return normalized.findIndex(h => candidates.some(a => h===a || h.includes(a)));
}

function cell(row: unknown[], headers: unknown[], key: string): unknown {
  const i=findColumn(headers,key); return i<0?null:row[i] ?? null;
}
function text(row: unknown[],headers:unknown[],key:string):string { return String(cell(row,headers,key)??'').trim(); }
function amount(row:unknown[],headers:unknown[],key:string):number|null { return parseAmount(cell(row,headers,key)); }
function canonicalType(raw:string):CanonicalEventType {
  const s=normalizeHeader(raw);
  if(/refund|retur|pengembalian/.test(s)) return 'refund';
  if(/void|batal|cancel|cancell?ation/.test(s)) return s.includes('cancel')||s.includes('batal')?'cancellation':'void';
  if(/discount|diskon|promo/.test(s)) return 'discount';
  if(/override|manual price|ubah harga|harga manual/.test(s)) return 'price_override';
  if(/payment|bayar|pembayaran/.test(s)) return 'payment';
  if(/cash discrepancy|selisih kas|cash variance/.test(s)) return 'cash_discrepancy';
  if(/comp|complimentary|gratis/.test(s)) return 'comp';
  return 'sale';
}
function isoDate(raw:string):string {
  if(!raw) return '';
  const d=new Date(raw); return Number.isNaN(d.getTime())?'':d.toISOString();
}
function deriveId(row:unknown[],headers:unknown[],rowNo:number,sourceIdentity:string):string {
  const id=text(row,headers,'sourceRecordId');
  return id || `${sourceIdentity||'source'}#row-${rowNo}`;
}

export function mapTabularRows(headers: unknown[], rows: unknown[][], sourceFile: string, sourceSheet?: string, now=new Date(), sourceIdentity=sourceFile): CanonicalPOSEventInput[] {
  const out:CanonicalPOSEventInput[]=[];
  rows.forEach((row,rowIndex)=>{
    if(!row.some(v=>String(v??'').trim()!=='')) return;
    const sourceRow=rowIndex+2;
    const sourceRecordId=deriveId(row,headers,sourceRow,sourceIdentity);
    const productName=text(row,headers,'productName');
    const qty=amount(row,headers,'qty') ?? 1;
    const unitPrice=amount(row,headers,'unitPrice') ?? 0;
    const gross=amount(row,headers,'grossAmount') ?? (qty>0?qty*unitPrice:0);
    const discount=amount(row,headers,'discountAmount') ?? 0;
    const net=amount(row,headers,'netAmount') ?? Math.max(0,gross-discount);
    const payment=amount(row,headers,'paymentAmount') ?? net;
    const amountValue=payment>0?payment:net;
    const occurredAt=isoDate(text(row,headers,'occurredAt'));
    const currency=(text(row,headers,'currency')||'IDR').toUpperCase();
    const type=canonicalType(text(row,headers,'type')||text(row,headers,'status'));
    const issues:string[]=[];
    if(!productName && type==='sale') issues.push('PRODUCT_NAME_MISSING');
    if(qty<=0) issues.push('QTY_INVALID');
    if([unitPrice,gross,discount,net,payment].some(n=>!Number.isFinite(n)||n<0)) issues.push('AMOUNT_INVALID');
    if(discount>gross) issues.push('DISCOUNT_EXCEEDS_GROSS');
    if(Math.abs(net-(gross-discount))>0.01) issues.push('TOTAL_MISMATCH');
    if(!occurredAt) issues.push('TIMESTAMP_INVALID'); else if(new Date(occurredAt)>now) issues.push('TIMESTAMP_FUTURE');
    if(!/^[A-Z]{3}$/.test(currency)) issues.push('CURRENCY_INVALID');
    const productId=text(row,headers,'productId');
    const outletId=text(row,headers,'outletId') || text(row,headers,'outletName');
    out.push({sourceRecordId,outletId:outletId||undefined,employeeId:text(row,headers,'employeeId')||undefined,cashierId:text(row,headers,'cashierId')||undefined,productId:productId||undefined,productName:productName||undefined,qty,unitPrice,grossAmount:gross,discountAmount:discount,netAmount:net,paymentAmount:payment,amount:amountValue,currency,occurredAt,type,status:issues.length?'INVALID':'VALID',sourceFile,sourceSheet,sourceRow,raw:Object.fromEntries(headers.map((h,i)=>[String(h??`column_${i+1}`),row[i]??null])),issues});
  });
  const seen=new Set<string>();
  for(const r of out){
    if(r.status!=='VALID') continue;
    if(seen.has(r.sourceRecordId)){r.status='DUPLICATE';r.issues.push('DUPLICATE_SOURCE_RECORD_ID');}
    else seen.add(r.sourceRecordId);
  }
  return out;
}

export function summarizeCanonicalImport(rows: CanonicalPOSEventInput[]) {
  const valid=rows.filter(r=>r.status==='VALID').length;
  const invalid=rows.filter(r=>r.status==='INVALID').length;
  const duplicate=rows.filter(r=>r.status==='DUPLICATE').length;
  const totals=rows.filter(r=>r.status==='VALID'&&r.type==='sale').reduce((s,r)=>({qty:s.qty+r.qty,net:s.net+r.netAmount,payment:s.payment+r.paymentAmount}),{qty:0,net:0,payment:0});
  return {total:rows.length,valid,invalid,duplicate,saleRows:rows.filter(r=>r.status==='VALID'&&r.type==='sale').length,totals};
}

/**
 * ============================================================================
 * LAPORAN ARUS KAS (CASH FLOW STATEMENT) — Metode Tidak Langsung
 * ============================================================================
 * Ini laporan yang paling sering dibutuhkan pemilik F&B tapi paling jarang
 * ada di tool internal buatan sendiri, karena orang sering mengira
 * "Laba Rugi positif = kas aman". Padahal keduanya bisa sangat berbeda:
 * restoran bisa untung di atas kertas tapi kehabisan kas kalau piutang
 * menumpuk atau baru beli banyak stok/peralatan.
 *
 * Kenapa Metode Tidak Langsung (bukan mencatat ulang tiap transaksi kas)?
 * Karena bisa disusun dari Neraca 2 periode + Laba Rugi yang SUDAH ADA di
 * TRACE — konsultan tidak perlu proses pencatatan tambahan yang berat.
 *
 * Formula inti:
 *   Kas dari Operasional
 *     = Laba Bersih
 *     + Beban Penyusutan            (biaya non-kas, uangnya tidak benar-benar keluar)
 *     − Kenaikan Piutang Usaha      (sudah diakui sbg pendapatan, uang belum masuk)
 *     − Kenaikan Persediaan         (uang sudah keluar beli stok, belum jadi HPP)
 *     + Kenaikan Utang Usaha        (biaya sudah diakui, uang belum keluar)
 *
 *   Kas dari Investasi = − (pembelian aset tetap bersih)
 *   Kas dari Pendanaan = kenaikan utang bank + setoran modal − prive
 *
 * PENTING soal kejujuran data: kalau salah satu input tidak tersedia,
 * fungsi ini TETAP menghitung total dengan asumsi 0 untuk baris itu (supaya
 * laporan tetap bisa ditampilkan), TAPI nama baris yang datanya kosong selalu
 * dicatat di `missingInputs`. UI wajib menampilkan peringatan kalau
 * `missingInputs.length > 0` — jangan pernah menampilkan angka total seolah
 * sudah final kalau ada input yang sebenarnya belum lengkap.
 */

export interface CashFlowLine { label: string; amount: number; }
export interface CashFlowSection { title: string; lines: CashFlowLine[]; total: number; }

export interface CashFlowStatement {
  period: string;
  operasional: CashFlowSection;
  investasi: CashFlowSection;
  pendanaan: CashFlowSection;
  kenaikanKasBersih: number;
  kasAwalPeriode: number | null;
  kasAkhirPeriode: number | null;
  missingInputs: string[];
}

export interface CashFlowInput {
  period: string;
  labaBersih: number | null;
  bebanPenyusutan: number | null;
  perubahanPiutangUsaha: number | null;     // (+) kalau piutang naik dibanding periode lalu
  perubahanPersediaan: number | null;       // (+) kalau persediaan naik
  perubahanUtangUsaha: number | null;       // (+) kalau utang usaha naik
  perubahanAsetTetapKotor: number | null;   // (+) kalau ada pembelian aset tetap baru (netto)
  perubahanUtangBank: number | null;
  perubahanModal: number | null;
  prive: number | null;
  kasAwalPeriode: number | null;
}

export function buildCashFlowStatement(input: CashFlowInput): CashFlowStatement {
  const missing: string[] = [];
  const need = (label: string, v: number | null): number => {
    if (v === null || !Number.isFinite(v)) { missing.push(label); return 0; }
    return v;
  };

  const labaBersih = need('Laba Bersih', input.labaBersih);
  const penyusutan = need('Beban Penyusutan', input.bebanPenyusutan);
  const dPiutang = need('Perubahan Piutang Usaha', input.perubahanPiutangUsaha);
  const dPersediaan = need('Perubahan Persediaan', input.perubahanPersediaan);
  const dUtangUsaha = need('Perubahan Utang Usaha', input.perubahanUtangUsaha);

  const operasional: CashFlowSection = {
    title: 'Arus Kas dari Aktivitas Operasional',
    lines: [
      { label: 'Laba Bersih', amount: labaBersih },
      { label: 'Beban Penyusutan (non-kas)', amount: penyusutan },
      { label: 'Perubahan Piutang Usaha', amount: -dPiutang },
      { label: 'Perubahan Persediaan', amount: -dPersediaan },
      { label: 'Perubahan Utang Usaha', amount: dUtangUsaha },
    ],
    total: labaBersih + penyusutan - dPiutang - dPersediaan + dUtangUsaha,
  };

  const dAsetTetap = need('Perubahan Aset Tetap', input.perubahanAsetTetapKotor);
  const investasi: CashFlowSection = {
    title: 'Arus Kas dari Aktivitas Investasi',
    lines: [{ label: 'Pembelian Aset Tetap (bersih)', amount: -dAsetTetap }],
    total: -dAsetTetap,
  };

  const dUtangBank = need('Perubahan Utang Bank', input.perubahanUtangBank);
  const dModal = need('Perubahan Modal', input.perubahanModal);
  const prive = need('Prive / Penarikan Pemilik', input.prive);
  const pendanaan: CashFlowSection = {
    title: 'Arus Kas dari Aktivitas Pendanaan',
    lines: [
      { label: 'Perubahan Utang Bank', amount: dUtangBank },
      { label: 'Setoran Modal', amount: dModal },
      { label: 'Prive / Penarikan Pemilik', amount: -prive },
    ],
    total: dUtangBank + dModal - prive,
  };

  const kenaikanKasBersih = operasional.total + investasi.total + pendanaan.total;
  const kasAwalPeriode = input.kasAwalPeriode;
  const kasAkhirPeriode = kasAwalPeriode !== null ? kasAwalPeriode + kenaikanKasBersih : null;
  if (kasAwalPeriode === null) missing.push('Kas Awal Periode');

  return { period: input.period, operasional, investasi, pendanaan, kenaikanKasBersih, kasAwalPeriode, kasAkhirPeriode, missingInputs: missing };
}

