}

export function summarizeAttribution(clientId: string, inquiries: ContentInquiry[]): AttributionSummary {
  const tracked = inquiries.filter(i => i.attributionSource === 'utm_click');
  const manual = inquiries.filter(i => i.attributionSource === 'manual_tag');
  const sum = (arr: ContentInquiry[]) => arr.reduce((acc, i) => acc + (i.closedRevenue ?? 0), 0);
  return {
    clientId,
    revenueFromTrackedClicks: sum(tracked),
    revenueFromManualAttribution: sum(manual),
    countTrackedClicks: tracked.length,
    countManualAttribution: manual.length,
    disclosureNote: 'Omset dari klik tercatat (presisi) ditampilkan terpisah dari omset atribusi manual/estimasi tim (perkiraan) — jangan dijumlahkan jadi satu angka tanpa keterangan ini.'
  };
}

// ---------------------------------------------------------------------------
// 4. Feedback loop / skor akurasi rekomendasi (spec poin 4 + addendum poin 2)
// ---------------------------------------------------------------------------
export interface RecommendationAccuracy {
  recommendationType: string;
  accuracyPct: number | null;
  sampleSize: number;
  measuredCount: number;
  confidenceNote: string; // WAJIB — tandai kalau sample masih kecil, jangan tampilkan sebagai "final"
}

export function computeRecommendationAccuracy(outcomes: RecommendationOutcome[], recommendationType: string, minSampleForConfidence = 20): RecommendationAccuracy {
  const relevant = outcomes.filter(o => o.recommendationType === recommendationType && o.wasFollowed);
  const measured = relevant.filter(o => o.wasSuccessful !== null);
  if (measured.length === 0) {
    return { recommendationType, accuracyPct: null, sampleSize: relevant.length, measuredCount: 0, confidenceNote: 'Belum ada hasil yang bisa diukur — skor akurasi belum bisa dihitung.' };
  }
  const successful = measured.filter(o => o.wasSuccessful === true).length;
  const accuracyPct = Math.round((successful / measured.length) * 10000) / 100;
  const confidenceNote = measured.length < minSampleForConfidence
    ? `Sample masih kecil (${measured.length} percobaan) — jangan ditampilkan sebagai skor final, tampilkan sebagai indikasi awal.`
    : `Berdasarkan ${measured.length} percobaan.`;
  return { recommendationType, accuracyPct, sampleSize: relevant.length, measuredCount: measured.length, confidenceNote };
}

// ---------------------------------------------------------------------------
// 5. Kesehatan koneksi akun — no silent fail (addendum poin 3, WAJIB)
// ---------------------------------------------------------------------------
export interface AccountHealthNotice {
  accountId: string;
  clientId: string;
  status: SocialAccountStatus;
  shouldNotifyClient: boolean;
  shouldNotifyTeam: boolean;
  message: string;
}

export function assessAccountHealth(account: SocialAccount): AccountHealthNotice | null {
  if (account.status === 'connected' && !account.lastSyncError) return null;
  const base = { accountId: account.id, clientId: account.clientId, status: account.status };
  if (account.status === 'expired') {
    return { ...base, shouldNotifyClient: true, shouldNotifyTeam: true, message: `Token akun ${account.platform} (${account.displayName ?? account.platformAccountId}) sudah expired — perlu re-auth.` };
  }
  if (account.status === 'revoked') {
    return { ...base, shouldNotifyClient: false, shouldNotifyTeam: true, message: `Akses akun ${account.platform} (${account.displayName ?? account.platformAccountId}) sudah dicabut.` };
  }
  if (account.lastSyncError) {
    return { ...base, shouldNotifyClient: false, shouldNotifyTeam: true, message: `Sync terakhir gagal: ${account.lastSyncError}` };
  }
  return null;
}

// ---------------------------------------------------------------------------
// 6. Coverage historis dibatasi API (addendum poin 2)
// ---------------------------------------------------------------------------
export function historicalCoverageDays(account: SocialAccount, now: Date = new Date()): number | null {
  if (!account.firstSyncedAt) return null;
  const first = new Date(account.firstSyncedAt).getTime();
  return Math.max(0, Math.round((now.getTime() - first) / (1000 * 60 * 60 * 24)));
}

export type IntakeSourceType = 'pdf' | 'xlsx' | 'xls' | 'ods' | 'csv' | 'tsv' | 'docx' | 'txt' | 'json' | 'image' | 'unknown';
export type IntakeFieldStatus = 'available' | 'calculated' | 'missing' | 'invalid' | 'not_applicable';

export interface IntakeCellEvidence {
  sourceFile: string;
  sourceSheet?: string;
  sourceRow?: number;
  sourceColumn?: string;
  rawValue?: string;
}

export interface IntakeField<T = unknown> {
  key: string;
  label: string;
  value: T | null;
  status: IntakeFieldStatus;
  evidence?: IntakeCellEvidence;
  note?: string;
}

export interface IntakeResult {
  businessName: IntakeField<string>;
  outletName: IntakeField<string>;
  period: IntakeField<string>;
  revenue: IntakeField<number>;
  cogs: IntakeField<number>;
  labor: IntakeField<number>;
  opex: IntakeField<number>;
  coveragePct: number;
  fields: IntakeField[];
  missingLabels: string[];
  warnings: string[];
}

const aliases: Record<string, string[]> = {
  businessName: ['business name','nama bisnis','nama usaha','company','perusahaan','coffee name','nama coffee','nama cafe','nama café'],
  outletName: ['outlet','outlet name','nama outlet','cabang','branch','lokasi'],
  period: ['period','periode','bulan','month','date','tanggal'],
  revenue: ['revenue','sales','sales revenue','penjualan','penjualan bersih','omzet','omset','total sales'],
  cogs: ['cogs','hpp','cost of goods sold','harga pokok penjualan','biaya bahan baku'],
  labor: ['labor','labour','payroll','gaji','upah','beban gaji','tenaga kerja'],
  opex: ['opex','operating expense','beban operasional','biaya operasional','operational expense']
};

export function normalizeHeader(value: unknown): string {
  return String(value ?? '').trim().toLowerCase().replace(/[\u00a0]/g, ' ').replace(/\s+/g, ' ');
}

export function detectSourceType(name: string): IntakeSourceType {
  const ext = name.toLowerCase().split('.').pop();
  if (ext === 'pdf') return 'pdf';
  if (ext === 'xlsx') return 'xlsx';
  if (ext === 'xls') return 'xls';
  if (ext === 'ods') return 'ods';
  if (ext === 'csv') return 'csv';
  if (ext === 'tsv') return 'tsv';
  if (ext === 'docx') return 'docx';
  if (ext === 'txt') return 'txt';
  if (ext === 'json') return 'json';
  if (['png','jpg','jpeg','webp'].includes(ext ?? '')) return 'image';
  return 'unknown';
}

export function findMappedField(headers: unknown[], target: string): number {
  const names = aliases[target] ?? [target];
  const normalized = headers.map(normalizeHeader);
  return normalized.findIndex(h => names.some(alias => h === alias || h.includes(alias)));
}

export function parseAmount(value: unknown): number | null {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const raw = String(value ?? '').trim();
  if (!raw) return null;
  let cleaned = raw.replace(/Rp|IDR/gi, '').replace(/\s/g, '').replace(/[^0-9,.-]/g, '');
  if (!cleaned || !/[0-9]/.test(cleaned)) return null;

  const lastDot = cleaned.lastIndexOf('.');
  const lastComma = cleaned.lastIndexOf(',');
  if (lastDot >= 0 && lastComma >= 0) {
    // The separator appearing last is treated as the decimal separator only
    // when it has 1–2 trailing digits; the other separator is then thousands.
    const decimalIsComma = lastComma > lastDot && cleaned.length - lastComma - 1 <= 2;
    const decimalIsDot = lastDot > lastComma && cleaned.length - lastDot - 1 <= 2;
    if (decimalIsComma) cleaned = cleaned.replace(/\./g, '').replace(',', '.');
    else if (decimalIsDot) cleaned = cleaned.replace(/,/g, '');
    else cleaned = cleaned.replace(/[.,]/g, '');
  } else if (lastComma >= 0) {
    const digitsAfter = cleaned.length - lastComma - 1;
    cleaned = digitsAfter === 3 ? cleaned.replace(/,/g, '') : cleaned.replace(',', '.');
  } else if (lastDot >= 0) {
    const digitsAfter = cleaned.length - lastDot - 1;
    if (digitsAfter === 3 && /^-?\d{1,3}(?:\.\d{3})+$/.test(cleaned)) cleaned = cleaned.replace(/\./g, '');
  }
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : null;
}

function field<T>(key: string, label: string, value: T | null, status: IntakeFieldStatus, note?: string): IntakeField<T> {
  return { key, label, value, status, note };
}

export function buildIntakeResult(input: Partial<Record<string, unknown>>): IntakeResult {
  const specs: Array<[string,string]> = [
    ['businessName','Nama bisnis'],['outletName','Outlet'],['period','Periode'],['revenue','Revenue'],['cogs','COGS'],['labor','Labor'],['opex','OPEX']
  ];
  const fields = specs.map(([key,label]) => {
    const value = input[key] ?? null;
    return field(key, label, value as never, value === null || value === '' ? 'missing' : 'available');
  });
  const numeric = fields.filter(f => ['revenue','cogs','labor','opex'].includes(f.key));
  const available = fields.filter(f => f.status === 'available' || f.status === 'calculated').length;
  const missingLabels = fields.filter(f => f.status === 'missing').map(f => f.label);
  const warnings: string[] = [];
  if (!input.businessName) warnings.push('Nama bisnis tidak ditemukan pada file. TRACE tidak akan menebak nama bisnis.');
  if (!input.period) warnings.push('Periode tidak ditemukan atau belum dapat dipastikan.');
  if (numeric.some(f => f.status === 'missing')) warnings.push('Analisis tetap berjalan dengan data yang tersedia; metrik yang bergantung pada data hilang akan diberi batasan.');
  return {
    businessName: fields[0] as IntakeField<string>, outletName: fields[1] as IntakeField<string>, period: fields[2] as IntakeField<string>,
    revenue: fields[3] as IntakeField<number>, cogs: fields[4] as IntakeField<number>, labor: fields[5] as IntakeField<number>, opex: fields[6] as IntakeField<number>,
    coveragePct: Math.round((available / fields.length) * 100), fields, missingLabels, warnings
  };
}

export interface DelimitedAggregate {
  businessName: string | null;
  outletName: string | null;
  period: string | null;
  revenue: number | null;
  cogs: number | null;
  labor: number | null;
  opex: number | null;
  rowCount: number;
}

/** Aggregate every non-empty data row. The first row is headers; no row is silently dropped. */
export function aggregateDelimitedRows(headers: unknown[], rows: unknown[][]): DelimitedAggregate {
  const dataRows = rows.filter(r => r.some(v => String(v ?? '').trim() !== ''));
  const idx = (key: string) => findMappedField(headers, key);
  const first = (key: string) => {
    const i = idx(key);
    if (i < 0) return null;
    return String(dataRows.find(r => String(r[i] ?? '').trim() !== '')?.[i] ?? '').trim() || null;
  };
  const sum = (key: string) => {
    const i = idx(key);
    if (i < 0) return null;
    const values = dataRows.map(r => parseAmount(r[i])).filter((v): v is number => v !== null);
    return values.length ? values.reduce((a, b) => a + b, 0) : null;
  };
  return { businessName:first('businessName'), outletName:first('outletName'), period:first('period'), revenue:sum('revenue'), cogs:sum('cogs'), labor:sum('labor'), opex:sum('opex'), rowCount:dataRows.length };
}

export function applyManualCompletion(input: IntakeResult, values: Partial<Record<'businessName'|'outletName'|'period'|'revenue'|'cogs'|'labor'|'opex', unknown>>): IntakeResult {
  const result = structuredClone(input);
  for (const key of ['businessName','outletName','period','revenue','cogs','labor','opex'] as const) {
    const raw = values[key];
    if (raw === undefined || raw === null || String(raw).trim() === '') continue;
    const target = result[key];
    if (['revenue','cogs','labor','opex'].includes(key)) {
      const parsed = parseAmount(raw);
      if (parsed === null || parsed < 0) { target.status = 'invalid'; target.note = 'Nilai manual harus berupa angka non-negatif yang dapat dibaca.'; continue; }
      target.value = parsed as never;
    } else {
      target.value = String(raw).trim() as never;
    }
    target.status = 'available';
    target.evidence = { sourceFile:'Manual', rawValue:String(raw) };
    target.note = 'Owner-provided manual completion; perlu review sebelum commit.';
  }
  return calculateAvailableFinance(result);
}

export function calculateAvailableFinance(input: IntakeResult): IntakeResult {
  const result = structuredClone(input);
  // Recompute derived fields idempotently. Repeated manual completion/review must
  // never append duplicate Gross/Operating Profit fields and inflate coverage.
  result.fields = result.fields.filter(f => f.key !== 'grossProfit' && f.key !== 'operatingProfit');
  const revenue = result.revenue.value;
  const cogs = result.cogs.value;
  if (revenue !== null && cogs !== null && Number.isFinite(revenue) && Number.isFinite(cogs)) {
    result.fields.push(field('grossProfit','Gross Profit', revenue - cogs, 'calculated', 'Dihitung dari Revenue - COGS.'));
  }
  const labor = result.labor.value;
  const opex = result.opex.value;
  if (revenue !== null && cogs !== null && labor !== null && opex !== null && [revenue,cogs,labor,opex].every(Number.isFinite)) {
    result.fields.push(field('operatingProfit','Operating Profit', revenue - cogs - labor - opex, 'calculated', 'Dihitung dari Revenue - COGS - Labor - OPEX.'));
  }
  const available = result.fields.filter(f => f.status === 'available' || f.status === 'calculated').length;
  result.coveragePct = result.fields.length ? Math.round((available / result.fields.length) * 100) : 0;
  result.missingLabels = result.fields.filter(f => f.status === 'missing').map(f => f.label);
  return result;
}

import type { FinanceComparison } from './finance.js';
import type { EvidenceItem } from './evidence.js';
import { assessEvidence } from './evidence.js';

export type DiagnosisSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';
export type DiagnosisStatus = 'confirmed' | 'suspected' | 'blocked';
export type DiagnosisArea = 'revenue' | 'cost' | 'margin' | 'profitability' | 'data_quality';

export interface DiagnosisEvidence {
  id: string;
  metric: string;
  current: number | null;
  previous: number | null;
  change: number | null;
  changePct: number | null;
  currentPeriod: string;
  previousPeriod: string | null;
  source: string;
}

export interface DiagnosisFinding {
  id: string;
  area: DiagnosisArea;
  severity: DiagnosisSeverity;
  status: DiagnosisStatus;
  title: string;
  problem: string;
  cause: string;
  impact: string;
  recommendation: string;
  evidence: DiagnosisEvidence[];
  /** Evidence coverage, not a probability of business truth. Null means no explicit evidence was supplied. */
  confidencePct: number | null;
}

export interface DiagnosisReport {
  currentPeriod: string;
  previousPeriod: string | null;
  findings: DiagnosisFinding[];
  evidenceAssessment: ReturnType<typeof assessEvidence>;
  conclusion: string;
  limitations: string[];
}

export interface DiagnosisThresholds {
  revenueDeclinePct: number;
  cogsRatioIncreasePp: number;
  laborRatioIncreasePp: number;
  opexRatioIncreasePp: number;
  operatingMarginDeclinePp: number;
}

const DEFAULT_THRESHOLDS: DiagnosisThresholds = {
  revenueDeclinePct: 5,
  cogsRatioIncreasePp: 3,
  laborRatioIncreasePp: 3,
  opexRatioIncreasePp: 3,
  operatingMarginDeclinePp: 3
};

/**
 * Evidence-first business diagnosis. Thresholds are explicit configuration,
 * not hidden claims about what is universally "bad" for every business.
 */
export function diagnoseBusiness(
  comparison: FinanceComparison,
  evidenceItems: EvidenceItem[] = [],
  thresholds: Partial<DiagnosisThresholds> = {}
): DiagnosisReport {
  const t = { ...DEFAULT_THRESHOLDS, ...thresholds };
  const c = comparison.current;
  const p = comparison.previous;
  const evidenceAssessment = assessEvidence(evidenceItems);
  const findings: DiagnosisFinding[] = [];
  const limitations: string[] = [];

  if (!p) {
    limitations.push('Periode pembanding tidak tersedia; diagnosis perubahan antarperiode tidak dapat dikonfirmasi.');
  }
  for (const metric of c.missingMetrics) {
    limitations.push(`${metric} tidak tersedia pada periode ${c.period}; kesimpulan terkait metric tersebut dibatasi.`);
  }

  if (p) {
    const revenue = metric(comparison, 'Revenue');
    if (revenue.changePct !== null && revenue.changePct <= -t.revenueDeclinePct) {
      findings.push(makeFinding(
        'revenue-decline', 'revenue', revenue.changePct <= -10 ? 'high' : 'medium',
        'Revenue menurun dibanding periode pembanding',
        `Revenue turun ${fmtPctAbs(revenue.changePct)} dari ${fmt(revenue.previous)} menjadi ${fmt(revenue.current)}.`,
        'Penurunan revenue terkonfirmasi secara matematis; penyebab operasional belum dapat ditentukan hanya dari P&L.',
        'Penurunan revenue menekan kapasitas gross profit dan operating profit.',
        'Telusuri driver revenue: volume transaksi, average ticket, outlet, produk, channel, promo, dan perubahan periode operasional.',
        [revenue], evidenceConfidence(revenue, evidenceItems)
      ));
    }

    const cogs = metric(comparison, 'COGS');
    const cogsPp = pctPointChange(c.cogsPct, p.cogsPct);
    if (cogsPp !== null && cogsPp >= t.cogsRatioIncreasePp) {
      findings.push(makeRatioFinding('cogs-ratio', 'cost', cogsPp >= 5 ? 'high' : 'medium', 'COGS ratio memburuk',
        `COGS terhadap revenue naik ${fmtPp(cogsPp)} percentage point, dari ${fmtPct(p.cogsPct)} menjadi ${fmtPct(c.cogsPct)}.`,
        'Peningkatan rasio biaya terkonfirmasi; penyebab spesifik perlu ditelusuri ke harga bahan, waste, recipe yield, purchasing, atau mix produk.',
        'Margin kotor berpotensi tertekan meskipun revenue tidak berubah.',
        'Drill down COGS per produk/outlet dan cocokkan dengan histori harga bahan, purchasing, waste, dan perubahan recipe.',
        [cogs], evidenceConfidence(cogs, evidenceItems)
      ));
    }

    const labor = metric(comparison, 'Labor');
    const laborPp = pctPointChange(c.laborPct, p.laborPct);
    if (laborPp !== null && laborPp >= t.laborRatioIncreasePp) {
      findings.push(makeRatioFinding('labor-ratio', 'cost', laborPp >= 5 ? 'high' : 'medium', 'Labor ratio memburuk',
        `Labor terhadap revenue naik ${fmtPp(laborPp)} percentage point, dari ${fmtPct(p.laborPct)} menjadi ${fmtPct(c.laborPct)}.`,
        'Kenaikan rasio terkonfirmasi; penyebab belum dapat dipastikan tanpa payroll, jam kerja, headcount, dan revenue per outlet.',
        'Beban tenaga kerja menyerap porsi revenue yang lebih besar.',
        'Periksa payroll, headcount, jam kerja, overtime, produktivitas per outlet, dan perubahan jam operasional.',
        [labor], evidenceConfidence(labor, evidenceItems)
      ));
    }

    const opex = metric(comparison, 'OPEX');
    const opexPp = pctPointChange(c.opexPct, p.opexPct);
    if (opexPp !== null && opexPp >= t.opexRatioIncreasePp) {
      findings.push(makeRatioFinding('opex-ratio', 'cost', opexPp >= 5 ? 'high' : 'medium', 'OPEX ratio memburuk',
        `OPEX terhadap revenue naik ${fmtPp(opexPp)} percentage point, dari ${fmtPct(p.opexPct)} menjadi ${fmtPct(c.opexPct)}.`,
        'Kenaikan rasio terkonfirmasi; penyebab perlu diurai per kategori OPEX dan evidence transaksi.',
        'Operating margin tertekan oleh beban operasional relatif terhadap revenue.',
        'Drill down OPEX per kategori, outlet, vendor, dan transaksi; pisahkan biaya one-off dari biaya berulang.',
        [opex], evidenceConfidence(opex, evidenceItems)
      ));
    }

    const op = metric(comparison, 'Operating Profit');
    const marginPp = pctPointChange(c.operatingMarginPct, p.operatingMarginPct);
    if (c.operatingProfit !== null && c.operatingProfit < 0) {
      findings.push(makeFinding('operating-loss', 'profitability', 'critical', 'Operating profit negatif',
        `Operating profit periode ${c.period} adalah ${fmt(c.operatingProfit)}.`,
        'Kerugian operasi terkonfirmasi dari formula Revenue − COGS − Labor − OPEX; root cause perlu diurai dari contributors.',
        'Bisnis menghasilkan rugi pada level operasi berdasarkan data yang tersedia.',
        'Prioritaskan contributor terbesar secara absolut, lalu susun corrective action yang dapat diukur pada periode berikutnya.',
        [op], evidenceConfidence(op, evidenceItems)
      ));
    } else if (marginPp !== null && marginPp <= -t.operatingMarginDeclinePp) {
      findings.push(makeFinding('operating-margin-decline', 'profitability', marginPp <= -5 ? 'high' : 'medium', 'Operating margin menurun',
        `Operating margin turun ${fmtPpAbs(marginPp)} percentage point, dari ${fmtPct(p.operatingMarginPct)} menjadi ${fmtPct(c.operatingMarginPct)}.`,
        'Penurunan margin terkonfirmasi; diagnosis akar masalah membutuhkan breakdown revenue dan biaya.',
        'Profitabilitas relatif terhadap revenue memburuk meskipun operating profit absolut belum tentu negatif.',
        'Bandingkan perubahan revenue, COGS, labor, dan OPEX secara simultan untuk menemukan contributor terbesar.',
        [op], evidenceConfidence(op, evidenceItems)
      ));
    }
  }

  if (findings.length === 0) {
    findings.push({
      id: 'no-material-signal', area: 'data_quality', severity: p ? 'info' : 'low', status: p ? 'confirmed' : 'blocked',
      title: p ? 'Tidak ada sinyal material berdasarkan threshold saat ini' : 'Diagnosis perubahan belum dapat dilakukan',
      problem: p ? 'Metric yang tersedia tidak melewati threshold diagnosis yang dikonfigurasi.' : 'Tidak ada periode pembanding yang cukup untuk diagnosis perubahan.',
      cause: p ? 'Tidak ditemukan perubahan yang melewati threshold eksplisit.' : 'Data periode pembanding tidak tersedia.',
      impact: p ? 'Tidak ada masalah material yang dapat dikonfirmasi oleh rule engine saat ini.' : 'Kesimpulan perubahan periode akan tidak lengkap.',
      recommendation: p ? 'Lanjutkan monitoring dan drill down bila ada perubahan operasional yang belum tercermin di P&L.' : 'Lengkapi periode pembanding sebelum menarik kesimpulan tren.',
      evidence: [], confidencePct: null
    });
  }

  const material = findings.filter(f => f.severity !== 'info');
  const conclusion = material.length
    ? `${material.length} sinyal bisnis material ditemukan pada ${c.period}. Prioritas utama: ${material.sort(prioritySort)[0].title}.`
    : `Tidak ada sinyal material yang dapat dikonfirmasi pada ${c.period} berdasarkan data dan threshold yang tersedia.`;

  return { currentPeriod: c.period, previousPeriod: p?.period ?? null, findings, evidenceAssessment, conclusion, limitations };
}

function metric(comparison: FinanceComparison, name: string): DiagnosisEvidence {
  const m = comparison.metrics.find(x => x.metric === name);
  return {
    id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-'), metric: name,
    current: m?.current ?? null, previous: m?.previous ?? null,
    change: m?.change ?? null, changePct: m?.changePct ?? null,
    currentPeriod: comparison.current.period, previousPeriod: comparison.previous?.period ?? null,
    source: 'Finance comparison'
  };
}

function makeFinding(id: string, area: DiagnosisArea, severity: DiagnosisSeverity, title: string, problem: string, cause: string, impact: string, recommendation: string, evidence: DiagnosisEvidence[], confidencePct: number | null): DiagnosisFinding {
  return { id, area, severity, status: 'confirmed', title, problem, cause, impact, recommendation, evidence, confidencePct };
}

function makeRatioFinding(id: string, area: DiagnosisArea, severity: DiagnosisSeverity, title: string, problem: string, cause: string, impact: string, recommendation: string, evidence: DiagnosisEvidence[], confidencePct: number | null): DiagnosisFinding {
  return makeFinding(id, area, severity, title, problem, cause, impact, recommendation, evidence, confidencePct);
}

function pctPointChange(current: number | null, previous: number | null): number | null {
  if (current === null || previous === null || !Number.isFinite(current) || !Number.isFinite(previous)) return null;
  return current - previous;
}

function evidenceConfidence(metricEvidence: DiagnosisEvidence, items: EvidenceItem[]): number | null {
  const related = items.filter(i => i.metric.toLowerCase() === metricEvidence.metric.toLowerCase() && i.status !== 'unavailable');
  if (!related.length) return null;
  const periods = new Set(related.map(i => i.period).filter(Boolean));
  const expectedPeriods = metricEvidence.previousPeriod ? 2 : 1;
  return Math.round(Math.min(1, periods.size / expectedPeriods) * 100);
}

function prioritySort(a: DiagnosisFinding, b: DiagnosisFinding) {
  const rank: Record<DiagnosisSeverity, number> = { critical: 5, high: 4, medium: 3, low: 2, info: 1 };
  return rank[b.severity] - rank[a.severity];
}
function fmt(v: number | null): string { return v === null ? 'tidak tersedia' : Number(v).toLocaleString('id-ID'); }
function fmtPct(v: number | null): string { return v === null ? 'tidak tersedia' : `${v.toFixed(2)}%`; }
function fmtPctAbs(v: number): string { return `${Math.abs(v).toFixed(2)}%`; }
function fmtPp(v: number): string { return `${v.toFixed(2)} pp`; }
function fmtPpAbs(v: number): string { return `${Math.abs(v).toFixed(2)} pp`; }

