export type RepairSafety = 'safe' | 'review_required' | 'blocked';
export type RepairAction = 'patch' | 'dependency' | 'config' | 'test' | 'manual';

export interface RepairStep {
  action: RepairAction;
  title: string;
  detail: string;
  file?: string;
  line?: number;
}

export interface DiagnosticRepairPlan {
  id: string;
  findingId: string;
  title: string;
  safety: RepairSafety;
  canApplyAutomatically: boolean;
  reason: string;
  steps: RepairStep[];
  verification: string[];
}

function base(f: DiagnosticFinding): DiagnosticRepairPlan {
  const first = f.evidence[0];
  return {
    id: `repair:${f.id}`,
    findingId: f.id,
    title: `Repair plan — ${f.title}`,
    safety: 'review_required',
    canApplyAutomatically: false,
    reason: 'Perubahan source code harus diverifikasi terhadap evidence dan tidak boleh diterapkan diam-diam.',
    steps: [{ action: 'manual', title: 'Review evidence', detail: f.solution, file: first?.file, line: first?.line }],
    verification: ['Rerun the relevant test.', 'Run typecheck/build before release.'],
  };
}

export function buildRepairPlan(f: DiagnosticFinding): DiagnosticRepairPlan {
  const plan = base(f);
  const file = f.evidence[0]?.file;
  const line = f.evidence[0]?.line;
  if (f.category === 'performance' && /cancellation|fetch|network/i.test(f.title + f.cause)) {
    plan.safety = 'safe';
    plan.canApplyAutomatically = false;
    plan.reason = 'Pattern is diagnosable, but the exact request boundary must be reviewed before changing control flow.';
    plan.steps = [
      { action: 'patch', title: 'Add bounded request cancellation', detail: 'Introduce AbortController/AbortSignal at the request owner and propagate the signal to the provider call.', file, line },
      { action: 'test', title: 'Add timeout regression', detail: 'Verify a stalled provider aborts within the configured deadline and does not poison the next job.', file, line },
    ];
  } else if (f.category === 'persistence') {
    plan.safety = 'review_required';
    plan.steps = [
      { action: 'patch', title: 'Replace unsafe operational persistence', detail: 'Move the operational write to the durable repository/checkpoint path while keeping compatibility fallback bounded.', file, line },
      { action: 'test', title: 'Verify crash/reload recovery', detail: 'Stop or interrupt the workflow, reload, and confirm the checkpoint can resume without data loss.', file, line },
    ];
  } else if (f.category === 'missing_dependency') {
    plan.safety = 'blocked';
    plan.steps = [{ action: 'dependency', title: 'Restore dependency resolution', detail: f.solution, file: 'package.json' }];
    plan.verification = ['Install dependencies successfully.', 'Run React typecheck.', 'Run production build.'];
  } else if (f.category === 'syntax') {
    plan.safety = 'review_required';
    plan.steps = [{ action: 'patch', title: 'Correct syntax at evidence location', detail: 'Apply the smallest source change that makes the reported syntax check pass. Preserve behavior outside the failing statement.', file, line }, { action: 'test', title: 'Re-run syntax/build checks', detail: 'Run node --check where applicable and then the production build.', file, line }];
  } else if (f.category === 'missing_data' || f.category === 'file_ingestion') {
    plan.safety = 'review_required';
    plan.steps = [{ action: 'manual', title: 'Do not invent missing values', detail: 'Fix the source mapping/parser or request the missing evidence. Never synthesize a business number.', file, line }, { action: 'test', title: 'Re-run intake regression', detail: 'Verify the same source file maps to the expected fields and preserves provenance.', file, line }];
  } else if (f.category === 'runtime_risk') {
    plan.safety = 'review_required';
    plan.steps = [{ action: 'patch', title: 'Fix the reported execution path', detail: f.solution, file, line }, { action: 'test', title: 'Add a regression test', detail: 'Reproduce the failure first, then verify the exact failing path and its adjacent error handling.', file, line }];
  }
  return plan;
}

export function buildRepairPlans(findings: DiagnosticFinding[]): DiagnosticRepairPlan[] {
  return findings.map(buildRepairPlan);
}

export interface RepairApplyRequest {
  findingId: string;
  plan: DiagnosticRepairPlan;
  approved: boolean;
  workspaceId?: string;
}

export async function requestRepairApply(request: RepairApplyRequest, endpoint='/api/diagnostic-repair', token?:string) {
  if (!request.approved) return { applied:false, status:'approval_required' as const };
  if (!request.plan.canApplyAutomatically) return { applied:false, status:'review_required' as const };
  if (typeof fetch === 'undefined' || !token) return { applied:false, status:'bridge_unavailable' as const };
  try {
    const response = await fetchWithTimeout(endpoint, { method:'POST', headers:{ Authorization:`Bearer ${token}`, 'Content-Type':'application/json' }, body:JSON.stringify(request) }, 15000);
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) return { applied:false, status:'failed' as const, reason:payload.error || `http_${response.status}` };
    return { applied:Boolean(payload.applied), status:payload.status || 'unknown', payload };
  } catch (error) {
    return { applied:false, status:'bridge_unavailable' as const, reason:error instanceof Error ? error.message : 'repair_bridge_unavailable' };
  }
}

// durableRecovery.ts
// Local-only recovery/checkpoint store for in-progress work (e.g. Data Intake drafts).
// This is a client-side safety net (localStorage-backed) — it never talks to Supabase
// or any production ledger. Its only job is to let a user resume a draft they were
// editing if the tab/browser closed before they finished.
//
// NOTE: this file was missing from the TRACE_v64_AUDITED package (main.tsx imports it
// but it did not exist anywhere in the archive). Reconstructed from the call-site
// contract in src/app/main.tsx. Please diff against your own git history / last known
// good version if you have one — this is a best-effort reimplementation, not a recovered
// original.

export type RecoverySnapshot<T> = {
  id: string;
  kind: string;
  createdAt: string;
  updatedAt: string;
  sourceName?: string;
  sourceHash?: string;
  status: string;
  data: T;
};

const STORAGE_PREFIX = 'trace:recovery:';

function hasLocalStorage(): boolean {
  try {
    return typeof localStorage !== 'undefined';
  } catch {
    return false;
  }
}

function storageKey(kind: string): string {
  return `${STORAGE_PREFIX}${kind}`;
}

function readAll<T>(kind: string): RecoverySnapshot<T>[] {
  if (!hasLocalStorage()) return [];
  try {
    const raw = localStorage.getItem(storageKey(kind));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as RecoverySnapshot<T>[]) : [];
  } catch {
    return [];
  }
}

function writeAll<T>(kind: string, rows: RecoverySnapshot<T>[]): void {
  if (!hasLocalStorage()) return;
  try {
    localStorage.setItem(storageKey(kind), JSON.stringify(rows));
  } catch {
    // Storage full or unavailable (e.g. private browsing) — fail silently,
    // this is a best-effort convenience feature, not a durability guarantee.
  }
}

function allKnownKinds(): string[] {
  if (!hasLocalStorage()) return [];
  const kinds: string[] = [];
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith(STORAGE_PREFIX)) {
        kinds.push(key.slice(STORAGE_PREFIX.length));
      }
    }
  } catch {
    return [];
  }
  return kinds;
}

/** List saved snapshots for a given kind, most recently updated first. */
export async function listRecoverySnapshots<T>(kind: string): Promise<RecoverySnapshot<T>[]> {
  const rows = readAll<T>(kind);
  return [...rows].sort((a, b) => (b.updatedAt || '').localeCompare(a.updatedAt || ''));
}

/** Create or update (upsert by id) a snapshot within its kind's bucket. */
export async function saveRecoverySnapshot<T>(snapshot: RecoverySnapshot<T>): Promise<void> {
  const rows = readAll<T>(snapshot.kind);
  const idx = rows.findIndex((row) => row.id === snapshot.id);
  if (idx >= 0) {
    rows[idx] = snapshot;
  } else {
    rows.unshift(snapshot);
  }
  writeAll(snapshot.kind, rows);
}

/**
 * Delete a snapshot by id. The kind isn't known at call sites that only hold
 * an id (see main.tsx), so this scans all known kind buckets.
 */
export async function deleteRecoverySnapshot(id: string): Promise<void> {
  for (const kind of allKnownKinds()) {
    const rows = readAll(kind);
    const filtered = rows.filter((row) => row.id !== id);
    if (filtered.length !== rows.length) {
      writeAll(kind, filtered);
    }
  }
}

export type EvidenceStatus = 'available' | 'unavailable' | 'manual';

export interface EvidenceItem {
  id: string;
  metric: string;
  status: EvidenceStatus;
  value?: number | string | null;
  unit?: string;
  period?: string;
  source?: string;
  sourceUrl?: string;
  capturedAt?: string;
  notes?: string;
}

export interface EvidenceAssessment {
  total: number;
  available: number;
  unavailable: number;
  manual: number;
  completenessPct: number;
  missing: string[];
}

export function assessEvidence(items: EvidenceItem[]): EvidenceAssessment {
  const total = items.length;
  const available = items.filter(i => i.status === 'available').length;
  const unavailable = items.filter(i => i.status === 'unavailable').length;
  const manual = items.filter(i => i.status === 'manual').length;
  return {
    total,
    available,
    unavailable,
    manual,
    completenessPct: total ? Math.round(((available + manual) / total) * 10000) / 100 : 0,
    missing: items.filter(i => i.status === 'unavailable').map(i => i.metric)
  };
}

export function evidenceSourceLabel(item: EvidenceItem): string {
  if (item.status === 'manual') return 'Manual / Owner-provided';
  if (item.status === 'unavailable') return 'Tidak tersedia pada sumber yang diperoleh';
  return item.source || 'Source not recorded';
}

import { buildIntakeResult, calculateAvailableFinance, findMappedField, normalizeHeader, parseAmount, type IntakeResult } from './dataIntake.js';
import { mapTabularRows, type CanonicalPOSEventInput } from './canonicalImport.js';

export interface FileAdapterResult {
  result: IntakeResult;
  sourceType: string;
  sheets?: string[];
  extractedRows?: number;
  warnings: string[];
  tabularRows?: CanonicalPOSEventInput[];
}

function valueFromText(text: string, labels: string[]): string | null {
  const escaped = labels.map(x => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  const re = new RegExp(`(?:^|\\n)\\s*(?:${escaped})\\s*[:=\\-]?\\s*(?:Rp\\s*)?([^\\n\\r]+)`, 'i');
  const m = text.match(re);
  return m?.[1]?.trim() || null;
}

function buildFromUnstructuredText(text: string, sourceFile: string): IntakeResult {
  const businessName = valueFromText(text, ['Nama Bisnis','Nama Usaha','Business Name','Company','Nama Coffee','Nama Cafe']);
  const outletName = valueFromText(text, ['Outlet','Nama Outlet','Cabang','Branch','Lokasi']);
  const period = valueFromText(text, ['Periode','Period','Bulan','Month']);
  const revenue = parseAmount(valueFromText(text, ['Revenue','Sales','Penjualan Bersih','Penjualan','Omzet','Omset','Total Sales']));
  const cogs = parseAmount(valueFromText(text, ['COGS','HPP','Cost of Goods Sold','Harga Pokok Penjualan']));
  const labor = parseAmount(valueFromText(text, ['Labor','Labour','Payroll','Gaji','Beban Gaji','Tenaga Kerja']));
  const opex = parseAmount(valueFromText(text, ['OPEX','Operating Expense','Beban Operasional','Biaya Operasional']));
  const result = calculateAvailableFinance(buildIntakeResult({businessName,outletName,period,revenue,cogs,labor,opex}));
  result.fields.forEach(f => { if (f.status === 'available') f.evidence = { sourceFile, rawValue: String(f.value ?? '') }; });
  return result;
}

// SECURITY NOTE (unresolved, tracked in SECURITY_KNOWN_ISSUES.md): the 'xlsx' package pinned in
// package.json (0.18.5) has two published high-severity advisories (GHSA-4r6h-8v6p-xvw6 prototype
// pollution, GHSA-5pgg-2g8v-p4x9 ReDoS) that are only patched in versions distributed via
// cdn.sheetjs.com — never republished to the public npm registry, so `npm install xlsx@latest`
// cannot fix this. Until someone with unrestricted network access installs the CDN-distributed
// build (or the app is migrated to an alternative library), this size cap is a partial mitigation
// only: it shrinks the worst-case input for the ReDoS path, it does NOT close the prototype
// pollution advisory. Do not remove this comment when "fixing" the dependency — replace it with a
// note of what was actually done.
const MAX_WORKBOOK_BYTES = 15 * 1024 * 1024;
export async function parseWorkbook(file: File, sourceIdentity=file.name): Promise<FileAdapterResult> {
  if (file.size > MAX_WORKBOOK_BYTES) {
    throw new Error(`File terlalu besar (maks ${MAX_WORKBOOK_BYTES / (1024*1024)}MB) untuk diproses.`);
  }
  const XLSX = await import('xlsx');
  const data = await file.arrayBuffer();
  const workbook = XLSX.read(data, { type: 'array', cellDates: true });
  const warnings: string[] = [];
  let combined: IntakeResult | null = null;
  let extractedRows = 0;
  let combinedIdentity: { businessName: string | null; outletName: string | null; period: string | null } | null = null;
  let mergeBlocked = false;
  const tabularRows: CanonicalPOSEventInput[] = [];
  for (const sheetName of workbook.SheetNames) {
    const sheet = workbook.Sheets[sheetName];
    const rows: unknown[][] = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: false, defval: null }) as unknown[][];
    extractedRows += rows.length;
    if (!rows.length) continue;
    const headers = rows[0] ?? [];
    const indices = {
      businessName: findMappedField(headers, 'businessName'), outletName: findMappedField(headers, 'outletName'), period: findMappedField(headers, 'period'),
      revenue: findMappedField(headers, 'revenue'), cogs: findMappedField(headers, 'cogs'), labor: findMappedField(headers, 'labor'), opex: findMappedField(headers, 'opex')
    };
    const nonEmpty = rows.slice(1).filter((r: unknown[]) => r.some((v: unknown) => String(v ?? '').trim() !== ''));
    tabularRows.push(...mapTabularRows(headers, nonEmpty, file.name, sheetName, new Date(), sourceIdentity));
    const sum = (idx: number) => idx < 0 ? null : nonEmpty.map((r: unknown[]) => parseAmount(r[idx])).filter((v: number | null): v is number => v !== null).reduce((a: number,b: number)=>a+b,0);
    const first = (idx: number) => idx < 0 ? null : String(nonEmpty.find((r: unknown[]) => r[idx] !== null && String(r[idx]).trim() !== '')?.[idx] ?? '').trim() || null;
    const candidate = calculateAvailableFinance(buildIntakeResult({ businessName:first(indices.businessName), outletName:first(indices.outletName), period:first(indices.period), revenue:sum(indices.revenue), cogs:sum(indices.cogs), labor:sum(indices.labor), opex:sum(indices.opex) }));
    candidate.fields.forEach((f) => { if (f.status === 'available') f.evidence = { sourceFile: file.name, sourceSheet: sheetName, rawValue: String(f.value ?? '') }; });
    const identity = { businessName: candidate.businessName.value, outletName: candidate.outletName.value, period: candidate.period.value };
    if (!combined) {
      combined = candidate;
      combinedIdentity = identity;
    } else if (!mergeBlocked && combinedIdentity && identity.businessName === combinedIdentity.businessName && identity.outletName === combinedIdentity.outletName && identity.period === combinedIdentity.period) {
      // Sheets are merged only when their business/outlet/period identity matches.
      // This prevents silently summing unrelated months, outlets, or businesses.
      for (const key of ['revenue','cogs','labor','opex'] as const) {
        const target = combined[key]; const incoming = candidate[key];
        if (incoming.value !== null) { target.value = (target.value ?? 0) + incoming.value; target.status = 'available'; target.evidence = incoming.evidence; }
      }
    } else if (!mergeBlocked) {
      mergeBlocked = true;
      warnings.push(`Workbook memiliki beberapa sheet dengan konteks bisnis/outlet/periode berbeda; TRACE tidak menjumlahkannya secara otomatis. Review sheet secara terpisah untuk mencegah double-counting atau pencampuran periode.`);
    }
  }
  if (!combined) warnings.push('Workbook tidak memiliki data yang dapat dipetakan.');
  if (combined) {
    const gross = combined.revenue.value !== null && combined.cogs.value !== null ? combined.revenue.value - combined.cogs.value : null;
    const op = gross !== null && combined.labor.value !== null && combined.opex.value !== null ? gross - combined.labor.value - combined.opex.value : null;
    const grossField = combined.fields.find((f) => f.key === 'grossProfit');
    const opField = combined.fields.find((f) => f.key === 'operatingProfit');
    if (gross !== null && grossField) grossField.value = gross;
    if (op !== null && opField) opField.value = op;
  }
  return { result: combined ?? buildIntakeResult({}), sourceType: file.name.toLowerCase().endsWith('.xls') ? 'xls' : 'xlsx', sheets: workbook.SheetNames, extractedRows, warnings, tabularRows };
}

export async function parseDocx(file: File): Promise<FileAdapterResult> {
  const mammoth = await import('mammoth');
  const buffer = await file.arrayBuffer();
  const out = await mammoth.extractRawText({ arrayBuffer: buffer });
  return { result: buildFromUnstructuredText(out.value, file.name), sourceType: 'docx', warnings: out.messages.map((m: { message: string }) => m.message) };
}

export async function parsePdf(file: File, onProgress?: (message: string) => void): Promise<FileAdapterResult> {
  const pdfjs = await import('pdfjs-dist');
  const buffer = await file.arrayBuffer();
  const pdf = await pdfjs.getDocument({ data: buffer }).promise;
  const chunks: string[] = [];
  for (let pageNo = 1; pageNo <= pdf.numPages; pageNo++) {
    onProgress?.(`Membaca PDF halaman ${pageNo}/${pdf.numPages}…`);
    const page = await pdf.getPage(pageNo);
    const content = await page.getTextContent();
    chunks.push(content.items.map((item: any) => String(item.str ?? '')).join(' '));
  }
  const text = chunks.join('\n');
  const result = buildFromUnstructuredText(text, file.name);
  const warnings = text.trim() ? [] : ['PDF tidak memiliki text layer. OCR diperlukan untuk PDF hasil scan.'];
  return { result, sourceType: 'pdf', extractedRows: pdf.numPages, warnings };
}

export async function parseText(file: File): Promise<FileAdapterResult> {
  const text = await file.text();
  const result = file.name.toLowerCase().endsWith('.json') ? parseJsonText(text, file.name) : buildFromUnstructuredText(text, file.name);
  return { result, sourceType: file.name.split('.').pop()?.toLowerCase() ?? 'text', warnings: [] };
}

function parseJsonText(text: string, sourceFile: string): IntakeResult {
  try {
    const data = JSON.parse(text) as Record<string, unknown>;
    const get = (key: string) => Object.entries(data).find(([k]) => normalizeHeader(k) === normalizeHeader(key) || normalizeHeader(k).includes(normalizeHeader(key)))?.[1] ?? null;
    return calculateAvailableFinance(buildIntakeResult({ businessName:get('businessName') ?? get('nama bisnis'), outletName:get('outlet') ?? get('nama outlet'), period:get('period') ?? get('periode'), revenue:parseAmount(get('revenue') ?? get('sales') ?? get('penjualan')), cogs:parseAmount(get('cogs') ?? get('hpp')), labor:parseAmount(get('labor') ?? get('gaji')), opex:parseAmount(get('opex') ?? get('biaya operasional')) }));
  } catch { return buildFromUnstructuredText(text, sourceFile); }
}


export async function parseImage(file: File, onProgress?: (message: string) => void): Promise<FileAdapterResult> {
  const Tesseract = await import('tesseract.js');
  onProgress?.('OCR membaca gambar…');
  const out = await Tesseract.recognize(file, 'ind+eng', { logger: (m: { status?: string; progress?: number }) => { if (m.status) onProgress?.(`OCR: ${m.status}${typeof m.progress === 'number' ? ` ${Math.round(m.progress * 100)}%` : ''}`); } });
  return { result: buildFromUnstructuredText(out.data.text, file.name), sourceType: 'image', warnings: out.data.text.trim() ? [] : ['OCR tidak menemukan teks yang dapat dibaca.'] };
}

export type FinanceSourceKind = 'system' | 'manual' | 'imported';

export interface FinanceEvidence { id: string; source: FinanceSourceKind; sourceRef?: string; capturedAt?: string; note?: string; }
export type FinanceStatementSection = 'pendapatan_usaha'|'biaya_produksi'|'biaya_usaha_lain'|'biaya_operasional'|'biaya_non_operasional'|'pendapatan_lain'|'pengeluaran_lain';
export interface FinanceRecord { id: string; period: string; amount: number; category: 'revenue' | 'cogs' | 'labor' | 'opex'; outletId?: string; evidence?: FinanceEvidence; accountLabel?: string; statementSection?: FinanceStatementSection; }

export interface FinanceSummary {
  period: string;
  revenue: number | null;
  cogs: number | null;
  grossProfit: number | null;
  labor: number | null;
  opex: number | null;
  operatingProfit: number | null;
  grossMarginPct: number | null;
  cogsPct: number | null;
  laborPct: number | null;
  opexPct: number | null;
  operatingMarginPct: number | null;
  recordCount: number;
  evidenceCount: number;
  missingMetrics: string[];
}

export interface FinanceComparison {
  current: FinanceSummary;
  previous: FinanceSummary | null;
  metrics: Array<{
    metric: string;
    current: number | null;
    previous: number | null;
    change: number | null;
    changePct: number | null;
    status: 'calculated' | 'insufficient_data' | 'undefined_baseline';
    formula: string;
  }>;
}

/** Missing categories remain null. TRACE never treats unavailable data as zero. */
export function summarizeFinance(records: FinanceRecord[], period: string): FinanceSummary {
  const scoped = records.filter(r => r.period === period && Number.isFinite(r.amount));
  const revenue = categoryTotal(scoped, 'revenue');
  const cogs = categoryTotal(scoped, 'cogs');
  const labor = categoryTotal(scoped, 'labor');
  const opex = categoryTotal(scoped, 'opex');
  const grossProfit = revenue !== null && cogs !== null ? revenue - cogs : null;
  const operatingProfit = revenue !== null && cogs !== null && labor !== null && opex !== null ? revenue - cogs - labor - opex : null;
  const evidenceCount = scoped.filter(r => r.evidence).length;
  const missingMetrics: string[] = [];
  if (revenue === null) missingMetrics.push('Revenue');
  if (cogs === null) missingMetrics.push('COGS');
  if (labor === null) missingMetrics.push('Labor');
  if (opex === null) missingMetrics.push('OPEX');
  return {
    period, revenue, cogs, grossProfit, labor, opex, operatingProfit,
    grossMarginPct: pct(grossProfit, revenue), cogsPct: pct(cogs, revenue), laborPct: pct(labor, revenue), opexPct: pct(opex, revenue), operatingMarginPct: pct(operatingProfit, revenue),
    recordCount: scoped.length, evidenceCount, missingMetrics
  };
}

export function compareFinancePeriods(records: FinanceRecord[], currentPeriod: string, previousPeriod?: string): FinanceComparison {
  const current = summarizeFinance(records, currentPeriod);
  const previous = previousPeriod ? summarizeFinance(records, previousPeriod) : null;
  const metrics = [
    ['Revenue', current.revenue, previous?.revenue ?? null], ['COGS', current.cogs, previous?.cogs ?? null], ['Gross Profit', current.grossProfit, previous?.grossProfit ?? null],
    ['Labor', current.labor, previous?.labor ?? null], ['OPEX', current.opex, previous?.opex ?? null], ['Operating Profit', current.operatingProfit, previous?.operatingProfit ?? null]
  ].map(([metric, cur, prev]) => changeMetric(String(metric), cur as number | null, prev as number | null));
  return { current, previous, metrics };
}

function changeMetric(metric: string, current: number | null, previous: number | null): FinanceComparison['metrics'][number] {
  const formula = '(current - previous) / previous × 100';
  if (current === null || previous === null || !Number.isFinite(current) || !Number.isFinite(previous)) return { metric, current, previous, change: null, changePct: null, status: 'insufficient_data', formula };
  const change = current - previous;
  if (previous === 0) return { metric, current, previous, change, changePct: null, status: 'undefined_baseline', formula };
  return { metric, current, previous, change, changePct: (change / previous) * 100, status: 'calculated', formula };
}

function categoryTotal(records: FinanceRecord[], category: FinanceRecord['category']): number | null {
  const matching = records.filter(r => r.category === category);
  return matching.length ? matching.reduce((total, r) => total + r.amount, 0) : null;
}
function pct(value: number | null, denominator: number | null): number | null {
  if (value === null || denominator === null || !Number.isFinite(value) || !Number.isFinite(denominator) || denominator === 0) return null;
  return (value / denominator) * 100;
}

import type { FinanceRecord } from './finance.js';

export type FinanceInputIssue = {
  field: keyof FinanceRecord | 'evidence';
  severity: 'error' | 'warning';
  code: string;
  message: string;
  suggestion: string;
};

const PERIOD_RE = /^\d{4}-(0[1-9]|1[0-2])$/;

export function validateFinanceRecord(input: Partial<FinanceRecord>): FinanceInputIssue[] {
  const issues: FinanceInputIssue[] = [];
  if (!input.id?.trim()) issues.push({field:'id', severity:'error', code:'MISSING_ID', message:'ID transaksi belum diisi.', suggestion:'Gunakan ID unik untuk setiap catatan.'});
  if (!input.period || !PERIOD_RE.test(input.period)) issues.push({field:'period', severity:'error', code:'INVALID_PERIOD', message:'Periode harus berformat YYYY-MM.', suggestion:'Contoh: 2026-08.'});
  if (!input.category || !['revenue','cogs','labor','opex'].includes(input.category)) issues.push({field:'category', severity:'error', code:'INVALID_CATEGORY', message:'Kategori keuangan belum valid.', suggestion:'Pilih Revenue, COGS, Labor, atau OPEX.'});
  if (input.amount === undefined || !Number.isFinite(input.amount)) issues.push({field:'amount', severity:'error', code:'INVALID_AMOUNT', message:'Nominal belum diisi dengan angka yang valid.', suggestion:'Masukkan angka tanpa simbol mata uang.'});
  else if (input.amount < 0) issues.push({field:'amount', severity:'error', code:'NEGATIVE_AMOUNT', message:'Nominal negatif terdeteksi.', suggestion:'Periksa apakah ini memang transaksi pembalik. Jika iya, catat sebagai adjustment dengan sumber yang jelas.'});
  if (input.evidence?.source === 'manual' && !input.evidence.note?.trim()) issues.push({field:'evidence', severity:'warning', code:'MANUAL_WITHOUT_NOTE', message:'Data manual belum memiliki catatan sumber.', suggestion:'Tambahkan sumber atau catatan agar angka dapat diaudit.'});
  return issues;
}

export function financeInputGuidance(issues: FinanceInputIssue[]) {
  if (!issues.length) return { status: 'ready' as const, title: 'Data siap diperiksa', message: 'Tidak ada kesalahan format pada input ini.' };
  const errors = issues.filter(i => i.severity === 'error').length;
  return errors ? { status: 'blocked' as const, title: 'Periksa input sebelum disimpan', message: `${errors} kesalahan perlu diperbaiki. TRACE tidak akan menganggap data ini valid sebelum diperbaiki.` } : { status: 'review' as const, title: 'Input dapat disimpan dengan catatan', message: 'Ada informasi yang sebaiknya dilengkapi agar analisis lebih dapat dipertanggungjawabkan.' };
}

import type { FinanceRecord, FinanceSummary, FinanceComparison } from './finance.js';
import type { IncomeStatement, StatementGroup } from './financeStatement.js';
import { computePieSlices, renderPieChartPng } from './chartRender.js';

export interface FinanceReportMeta {
  clientName: string;
  currentPeriod: string;
  previousPeriod?: string;
  generatedAt?: string;
}

const CATEGORY_LABEL: Record<FinanceRecord['category'], string> = {
  revenue: 'Revenue', cogs: 'COGS', labor: 'Labor', opex: 'OPEX',
};

function fmtRp(n: number | null): string {
  if (n === null || !Number.isFinite(n)) return 'Belum tersedia';
  return 'Rp ' + Math.round(n).toLocaleString('id-ID');
}
function fmtPct(n: number | null): string {
  if (n === null || !Number.isFinite(n)) return 'Belum tersedia';
  return n.toFixed(1) + '%';
}
function summaryRows(summary: FinanceSummary) {
  return [
    ['Revenue', fmtRp(summary.revenue)],
    ['COGS', fmtRp(summary.cogs)],
    ['Gross Profit', fmtRp(summary.grossProfit)],
    ['Gross Margin %', fmtPct(summary.grossMarginPct)],
    ['Labor', fmtRp(summary.labor)],
    ['OPEX', fmtRp(summary.opex)],
    ['Operating Profit', fmtRp(summary.operatingProfit)],
    ['Operating Margin %', fmtPct(summary.operatingMarginPct)],
  ];
}

/** Builds and downloads a multi-sheet .xlsx: Ringkasan, Perbandingan Periode, Detail Transaksi. */
export async function exportFinanceExcel(
  records: FinanceRecord[],
  comparison: FinanceComparison,
  meta: FinanceReportMeta,
): Promise<void> {
  const XLSX = await import('xlsx');
  const wb = XLSX.utils.book_new();

  const summarySheetRows = [
    ['TRACE CONSULTANTS — Laporan Keuangan'],
    ['Klien', meta.clientName],
    ['Periode', meta.currentPeriod + (meta.previousPeriod ? ` (vs ${meta.previousPeriod})` : '')],
    ['Dibuat', meta.generatedAt ?? new Date().toISOString()],
    [],
    ['Metrik', 'Nilai'],
    ...summaryRows(comparison.current),
    [],
    ['Catatan', 'Metrik yang datanya belum lengkap ditandai "Belum tersedia", bukan dianggap 0, agar tidak menyesatkan analisis.'],
  ];
  const wsSummary = XLSX.utils.aoa_to_sheet(summarySheetRows);
  wsSummary['!cols'] = [{ wch: 24 }, { wch: 40 }];
  XLSX.utils.book_append_sheet(wb, wsSummary, 'Ringkasan');

  const comparisonRows = [
    ['Metrik', `Periode ${meta.currentPeriod}`, meta.previousPeriod ? `Periode ${meta.previousPeriod}` : 'Periode sebelumnya', 'Perubahan', 'Perubahan %', 'Status', 'Formula'],
    ...comparison.metrics.map(m => [
      m.metric, m.current ?? 'Belum tersedia', m.previous ?? 'Belum tersedia',
      m.change ?? 'Belum tersedia', m.changePct === null ? 'Belum tersedia' : Number(m.changePct.toFixed(2)),
      m.status === 'calculated' ? 'Terhitung' : m.status === 'insufficient_data' ? 'Data belum cukup' : 'Baseline tidak terdefinisi (periode lalu = 0)',
      m.formula,
    ]),
  ];
  const wsComparison = XLSX.utils.aoa_to_sheet(comparisonRows);
  wsComparison['!cols'] = [{ wch: 20 }, { wch: 16 }, { wch: 16 }, { wch: 14 }, { wch: 14 }, { wch: 26 }, { wch: 34 }];
  XLSX.utils.book_append_sheet(wb, wsComparison, 'Perbandingan Periode');

  const detailRows = [
    ['Periode', 'Kategori', 'Nominal', 'Sumber Evidence', 'Catatan', 'Dibuat'],
    ...records
      .filter(r => r.period === meta.currentPeriod || r.period === meta.previousPeriod)
      .sort((a, b) => a.period.localeCompare(b.period) || a.category.localeCompare(b.category))
      .map(r => [r.period, CATEGORY_LABEL[r.category], r.amount, r.evidence?.source ?? '—', r.evidence?.note ?? '', r.evidence?.capturedAt ?? '']),
  ];
  const wsDetail = XLSX.utils.aoa_to_sheet(detailRows);
  wsDetail['!cols'] = [{ wch: 10 }, { wch: 12 }, { wch: 16 }, { wch: 14 }, { wch: 30 }, { wch: 20 }];
  XLSX.utils.book_append_sheet(wb, wsDetail, 'Detail Transaksi');

  const fileScope = meta.clientName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'internal';
  XLSX.writeFile(wb, `trace-consultant-${fileScope}-${meta.currentPeriod}.xlsx`);
}

/**
 * Builds and downloads a .xlsx with a "Dashboard" sheet that includes a chart image
 * (pie: distribusi COGS/Labor/OPEX untuk periode berjalan), plus a raw-data sheet.
 * Uses `exceljs`, NOT `xlsx` — the `xlsx` package's own README lists "images/graphs" as a
 * SheetJS Pro-only feature, so it cannot embed pictures when writing. exceljs's addImage is a
 * real, documented open-source feature (see node_modules/exceljs/README.md "Images" section),
 * verified before this function was written, not assumed.
 * The chart is a static PNG, not a native/editable Excel chart object — opening the file in Excel
 * shows a picture, not something you can right-click "Edit Data" on.
 */
export async function exportFinanceDashboardExcel(
  records: FinanceRecord[],
  meta: FinanceReportMeta,
): Promise<void> {
  const ExcelJS = await import('exceljs');
  const wb = new ExcelJS.Workbook();
  wb.creator = 'TRACE Consultant OS';
  wb.created = new Date();

  const currentRecords = records.filter(r => r.period === meta.currentPeriod);
  const byCategory: Array<{ label: string; value: number }> = (['cogs', 'labor', 'opex'] as const).map(cat => ({
    label: CATEGORY_LABEL[cat],
    value: currentRecords.filter(r => r.category === cat).reduce((s, r) => s + r.amount, 0),
  }));
  const slices = computePieSlices(byCategory);
  const dataUrl = renderPieChartPng(slices, { title: `Distribusi Biaya · ${meta.currentPeriod}` });

  const wsDash = wb.addWorksheet('Dashboard');
  wsDash.getCell('A1').value = `Dashboard Keuangan — ${meta.clientName} — ${meta.currentPeriod}`;
  wsDash.getCell('A1').font = { bold: true, size: 14 };
  wsDash.getCell('A2').value = 'Grafik di bawah adalah gambar statis (PNG), bukan native Excel chart — tidak bisa diedit datanya langsung dari Excel, hanya untuk tampilan.';
  wsDash.getCell('A2').font = { italic: true, size: 10, color: { argb: 'FF666666' } };
  const imageId = wb.addImage({ base64: dataUrl, extension: 'png' });
  wsDash.addImage(imageId, 'A4:H24');

  const wsData = wb.addWorksheet('Data Mentah');
  wsData.columns = [{ header: 'Periode', key: 'period', width: 12 }, { header: 'Kategori', key: 'category', width: 14 }, { header: 'Nominal', key: 'amount', width: 18 }];
  currentRecords.forEach(r => wsData.addRow({ period: r.period, category: CATEGORY_LABEL[r.category], amount: r.amount }));
  wsData.getRow(1).font = { bold: true };

  const fileScope = meta.clientName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'internal';
  const buf = await wb.xlsx.writeBuffer();
  const blob = new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `trace-dashboard-${fileScope}-${meta.currentPeriod}.xlsx`;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}

/** Builds and downloads a multi-page PDF report with page header/footer + autoTable tables. */
export async function exportFinancePdf(
  comparison: FinanceComparison,
  meta: FinanceReportMeta,
): Promise<void> {
  const { jsPDF } = await import('jspdf');
  const { default: autoTable } = await import('jspdf-autotable');
  const doc = new jsPDF({ unit: 'pt', format: 'a4', compress: true });
  const M = 40;
  const W = doc.internal.pageSize.getWidth();
  const H = doc.internal.pageSize.getHeight();
  const navy: [number, number, number] = [23, 23, 23];

  const header = () => {
    doc.setFontSize(9); doc.setTextColor(120);
    doc.text('TRACE CONSULTANTS · Laporan Keuangan', M, 24);
    doc.text(meta.clientName, W - M, 24, { align: 'right' });
    doc.setDrawColor(230); doc.line(M, 30, W - M, 30);
  };
  const footer = (page: number, totalPagesExp: string) => {
    doc.setFontSize(8); doc.setTextColor(150);
    doc.text(`Halaman ${page} dari ${totalPagesExp}`, W - M, H - 18, { align: 'right' });
    doc.text(`Dibuat: ${new Date(meta.generatedAt ?? Date.now()).toLocaleDateString('id-ID')}`, M, H - 18);
  };

  doc.setFontSize(18); doc.setTextColor(...(navy as [number, number, number]));
  doc.text('Laporan Keuangan', M, 60);
  doc.setFontSize(11); doc.setTextColor(90);
  doc.text(`Klien: ${meta.clientName}`, M, 80);
  doc.text(`Periode: ${meta.currentPeriod}${meta.previousPeriod ? ` (dibandingkan ${meta.previousPeriod})` : ''}`, M, 96);

  doc.setFontSize(12); doc.setTextColor(...(navy as [number, number, number]));
  doc.text('Ringkasan', M, 124);
  autoTable(doc, {
    startY: 132, margin: { left: M, right: M, top: 38, bottom: 40 },
    head: [['Metrik', 'Nilai']], body: summaryRows(comparison.current),
    styles: { font: 'helvetica', fontSize: 9, cellPadding: 6 },
    headStyles: { fillColor: navy, textColor: 255, fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [249, 250, 252] },
    didDrawPage: header,
  });

  // @ts-expect-error jspdf-autotable still sets doc.lastAutoTable at runtime
  let y = doc.lastAutoTable.finalY + 24;
  doc.setFontSize(12); doc.setTextColor(...(navy as [number, number, number]));
  doc.text('Perbandingan Periode', M, y);
  autoTable(doc, {
    startY: y + 8, margin: { left: M, right: M, top: 38, bottom: 40 },
    head: [['Metrik', `Saat ini (${meta.currentPeriod})`, 'Sebelumnya', 'Perubahan', 'Perubahan %', 'Formula']],
    body: comparison.metrics.map(m => [
      m.metric, m.current === null ? 'Belum tersedia' : fmtRp(m.current), m.previous === null ? 'Belum tersedia' : fmtRp(m.previous),
      m.change === null ? 'Belum tersedia' : fmtRp(m.change), m.changePct === null ? 'Belum tersedia' : fmtPct(m.changePct), m.formula,
    ]),
    styles: { font: 'helvetica', fontSize: 8, cellPadding: 5 },
    headStyles: { fillColor: navy, textColor: 255, fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [249, 250, 252] },
    columnStyles: { 5: { cellWidth: 140 } },
    didDrawPage: header,
    didParseCell: (d: any) => {
      if (d.section === 'body' && (d.column.index === 3) && String(d.cell.raw).includes('-')) {
        d.cell.styles.textColor = [185, 28, 28]; d.cell.styles.fontStyle = 'bold';
      }
    },
  });

  doc.setFontSize(8); doc.setTextColor(140);
  // @ts-expect-error jspdf-autotable still sets doc.lastAutoTable at runtime
  const notesY = Math.min(doc.lastAutoTable.finalY + 20, H - 60);
  doc.text('Catatan: metrik yang datanya belum lengkap ditandai "Belum tersedia", bukan dianggap nol.', M, notesY, { maxWidth: W - M * 2 });

  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) { doc.setPage(i); footer(i, String(pageCount)); }

  const fileScope = meta.clientName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'internal';
  doc.save(`trace-consultant-${fileScope}-${meta.currentPeriod}.pdf`);
}

function groupRows(g: StatementGroup): (string | number)[][] {
  const rows: (string | number)[][] = g.lines.map(l => ['', l.label, l.amount]);
  rows.push(['', `Total ${g.title}`, g.total]);
  return rows;
}

/** Multi-sheet .xlsx matching a standard Laba Rugi layout (Pendapatan Usaha -> Laba
 *  Kotor -> Laba Operasi -> Laba Bersih), built from buildIncomeStatement() output. */
export async function exportIncomeStatementExcel(stmt: IncomeStatement, meta: FinanceReportMeta): Promise<void> {
  const XLSX = await import('xlsx');
