}

/** Multi-page PDF, same hierarchical layout, bold subtotal/total rows. */
export async function exportIncomeStatementPdf(stmt: IncomeStatement, meta: FinanceReportMeta): Promise<void> {
  const { jsPDF } = await import('jspdf');
  const { default: autoTable } = await import('jspdf-autotable');
  const doc = new jsPDF({ unit: 'pt', format: 'a4', compress: true });
  const M = 40; const W = doc.internal.pageSize.getWidth(); const H = doc.internal.pageSize.getHeight();
  const navy: [number, number, number] = [23, 23, 23];

  const header = () => {
    doc.setFontSize(9); doc.setTextColor(120);
    doc.text('TRACE CONSULTANTS · Laporan Laba Rugi', M, 24);
    doc.text(meta.clientName, W - M, 24, { align: 'right' });
    doc.setDrawColor(230); doc.line(M, 30, W - M, 30);
  };

  doc.setFontSize(18); doc.setTextColor(...navy);
  doc.text('Laba Rugi', M, 60);
  doc.setFontSize(11); doc.setTextColor(90);
  doc.text(`${meta.clientName} · Periode ${stmt.period}`, M, 80);

  const body: (string | number)[][] = [];
  const boldRows: number[] = [];
  const pushGroup = (label: string, g: StatementGroup) => {
    body.push([label, '']);
    for (const l of g.lines) body.push([`   ${l.label}`, fmtRp(l.amount)]);
    body.push([`Total ${g.title}`, fmtRp(g.total)]); boldRows.push(body.length - 1);
  };
  pushGroup('Pendapatan Usaha', stmt.pendapatanUsaha);
  body.push(['Total Pendapatan', fmtRp(stmt.pendapatanUsaha.total)]); boldRows.push(body.length - 1);
  pushGroup('Biaya Produksi', stmt.biayaProduksi);
  pushGroup('Biaya Usaha Lain', stmt.biayaUsahaLain);
  body.push(['Total Biaya Atas Pendapatan', fmtRp(stmt.totalBiayaAtasPendapatan)]); boldRows.push(body.length - 1);
  body.push(['Laba/Rugi Kotor', fmtRp(stmt.labaKotor)]); boldRows.push(body.length - 1);
  pushGroup('Biaya Operasional', stmt.biayaOperasional);
  pushGroup('Biaya Non Operasional', stmt.biayaNonOperasional);
  body.push(['Total Pengeluaran Operasional', fmtRp(stmt.totalPengeluaranOperasional)]); boldRows.push(body.length - 1);
  body.push(['Laba/Rugi Operasi', fmtRp(stmt.labaOperasi)]); boldRows.push(body.length - 1);
  pushGroup('Pendapatan Lain', stmt.pendapatanLain);
  pushGroup('Pengeluaran Lain', stmt.pengeluaranLain);
  body.push(['Laba/Rugi Bersih', fmtRp(stmt.labaBersih)]); boldRows.push(body.length - 1);

  autoTable(doc, {
    startY: 100, margin: { left: M, right: M, top: 38, bottom: 40 },
    head: [['Akun', 'Saldo']], body,
    styles: { font: 'helvetica', fontSize: 9, cellPadding: 5 },
    headStyles: { fillColor: navy, textColor: 255, fontStyle: 'bold' },
    columnStyles: { 1: { halign: 'right' } },
    didParseCell: (d: any) => { if (d.section === 'body' && boldRows.includes(d.row.index)) { d.cell.styles.fontStyle = 'bold'; d.cell.styles.fillColor = [244, 244, 242]; } },
    didDrawPage: header,
  });

  if (stmt.unclassified.length) {
    doc.setFontSize(9); doc.setTextColor(185, 28, 28);
    // @ts-expect-error jspdf-autotable still sets doc.lastAutoTable at runtime
    doc.text(`Perhatian: ${stmt.unclassified.length} entri belum diklasifikasi ke bagian laporan manapun dan tidak ikut dihitung di atas.`, M, doc.lastAutoTable.finalY + 20, { maxWidth: W - M * 2 });
  }
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i); doc.setFontSize(8); doc.setTextColor(150);
    doc.text(`Halaman ${i} dari ${pageCount}`, W - M, H - 18, { align: 'right' });
  }
  const fileScope = meta.clientName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'internal';
  doc.save(`trace-consultant-laba-rugi-${fileScope}-${stmt.period}.pdf`);
}

import type { FinanceRecord, FinanceStatementSection } from './finance.js';

export interface StatementLine { label: string; amount: number; }
export interface StatementGroup { section: FinanceStatementSection; title: string; lines: StatementLine[]; total: number; }
export interface IncomeStatement {
  period: string;
  pendapatanUsaha: StatementGroup;
  biayaProduksi: StatementGroup;
  biayaUsahaLain: StatementGroup;
  totalBiayaAtasPendapatan: number;
  labaKotor: number;
  biayaOperasional: StatementGroup;
  biayaNonOperasional: StatementGroup;
  totalPengeluaranOperasional: number;
  labaOperasi: number;
  pendapatanLain: StatementGroup;
  pengeluaranLain: StatementGroup;
  labaBersih: number;
  /** Records with no statementSection set (legacy flat entries) — surfaced so nothing is silently dropped. */
  unclassified: StatementLine[];
}

const SECTION_TITLES: Record<FinanceStatementSection, string> = {
  pendapatan_usaha: 'Pendapatan Usaha', biaya_produksi: 'Biaya Produksi', biaya_usaha_lain: 'Biaya Usaha Lain',
  biaya_operasional: 'Biaya Operasional', biaya_non_operasional: 'Biaya Non Operasional',
  pendapatan_lain: 'Pendapatan Lain', pengeluaran_lain: 'Pengeluaran Lain',
};

function group(records: FinanceRecord[], section: FinanceStatementSection): StatementGroup {
  const rows = records.filter(r => r.statementSection === section);
  const lines = rows.map(r => ({ label: r.accountLabel?.trim() || SECTION_TITLES[section], amount: r.amount }));
  return { section, title: SECTION_TITLES[section], lines, total: lines.reduce((s, l) => s + l.amount, 0) };
}

/** Builds a hierarchical income statement for one period. Sections with zero classified
 *  records still render (with an empty lines array, total 0) so the report shape stays
 *  consistent across periods — never silently reshaped by which accounts happened to be used. */
export function buildIncomeStatement(records: FinanceRecord[], period: string): IncomeStatement {
  const scoped = records.filter(r => r.period === period);
  const pendapatanUsaha = group(scoped, 'pendapatan_usaha');
  const biayaProduksi = group(scoped, 'biaya_produksi');
  const biayaUsahaLain = group(scoped, 'biaya_usaha_lain');
  const totalBiayaAtasPendapatan = biayaProduksi.total + biayaUsahaLain.total;
  const labaKotor = pendapatanUsaha.total - totalBiayaAtasPendapatan;
  const biayaOperasional = group(scoped, 'biaya_operasional');
  const biayaNonOperasional = group(scoped, 'biaya_non_operasional');
  const totalPengeluaranOperasional = biayaOperasional.total + biayaNonOperasional.total;
  const labaOperasi = labaKotor - totalPengeluaranOperasional;
  const pendapatanLain = group(scoped, 'pendapatan_lain');
  const pengeluaranLain = group(scoped, 'pengeluaran_lain');
  const labaBersih = labaOperasi + pendapatanLain.total - pengeluaranLain.total;
  const unclassified = scoped.filter(r => !r.statementSection).map(r => ({ label: r.accountLabel?.trim() || r.category, amount: r.amount }));
  return { period, pendapatanUsaha, biayaProduksi, biayaUsahaLain, totalBiayaAtasPendapatan, labaKotor, biayaOperasional, biayaNonOperasional, totalPengeluaranOperasional, labaOperasi, pendapatanLain, pengeluaranLain, labaBersih, unclassified };
}

/**
 * ============================================================================
 * ASET TETAP & PENYUSUTAN (FIXED ASSETS & DEPRECIATION)
 * ============================================================================
 * Peralatan dapur, mesin kopi, kulkas, interior — semua ini bernilai besar
 * di awal tapi nilainya turun seiring waktu. Tanpa modul ini, TRACE tidak
 * bisa: (1) menghitung Beban Penyusutan bulanan yang dibutuhkan Laba Rugi
 * & Arus Kas, atau (2) menunjukkan nilai buku aset yang tersisa di Neraca.
 *
 * Dipakai Metode Garis Lurus (Straight-Line) karena paling mudah dijelaskan
 * ke pemilik F&B yang bukan orang akuntansi, dan paling umum dipakai UMKM.
 */

export interface FixedAsset {
  id: string;
  clientId: string;
  name: string;
  acquisitionDate: string; // ISO date, kapan aset dibeli
  acquisitionCost: number; // harga perolehan
  usefulLifeMonths: number; // umur manfaat, dalam bulan (mis. 60 = 5 tahun)
  residualValue: number;    // estimasi nilai sisa di akhir umur manfaat (boleh 0)
}

export interface DepreciationScheduleRow {
  period: string; // "2026-09" dst.
  monthlyDepreciation: number;
  accumulatedDepreciation: number;
  bookValue: number; // harga perolehan − akumulasi penyusutan
}

export interface DepreciationSchedule {
  asset: FixedAsset;
  monthlyDepreciation: number;
  schedule: DepreciationScheduleRow[];
  fullyDepreciated: boolean;
}

/**
 * Formula: Penyusutan per bulan = (Harga Perolehan − Nilai Residu) / Umur Manfaat (bulan)
 * `periods` adalah daftar periode ("2026-01", "2026-02", ...) yang ingin dihitung —
 * biasanya dari bulan pembelian sampai bulan berjalan.
 */
export function buildDepreciationSchedule(asset: FixedAsset, periods: string[]): DepreciationSchedule {
  const depreciableBase = Math.max(0, asset.acquisitionCost - asset.residualValue);
  const monthlyDepreciation = asset.usefulLifeMonths > 0
    ? Math.round((depreciableBase / asset.usefulLifeMonths) * 100) / 100
    : 0;

  let accumulated = 0;
  const schedule: DepreciationScheduleRow[] = periods.map(period => {
    const remainingBase = depreciableBase - accumulated;
    const thisMonth = Math.min(monthlyDepreciation, Math.max(0, remainingBase));
    accumulated = Math.round((accumulated + thisMonth) * 100) / 100;
    return {
      period,
      monthlyDepreciation: thisMonth,
      accumulatedDepreciation: accumulated,
      bookValue: Math.round((asset.acquisitionCost - accumulated) * 100) / 100,
    };
  });

  return { asset, monthlyDepreciation, schedule, fullyDepreciated: accumulated >= depreciableBase - 0.5 };
}

/** Total beban penyusutan bulanan gabungan semua aset — dipakai langsung
 *  sebagai input `bebanPenyusutan` di cashFlowStatement.ts dan sebagai baris
 *  "Beban Penyusutan" di Laba Rugi. */
export function totalMonthlyDepreciation(assets: FixedAsset[]): number {
  const total = assets.reduce((sum, a) => {
    const base = Math.max(0, a.acquisitionCost - a.residualValue);
    const monthly = a.usefulLifeMonths > 0 ? base / a.usefulLifeMonths : 0;
    return sum + monthly;
  }, 0);
  return Math.round(total * 100) / 100;
}

