export type HealthStatus='healthy'|'attention'|'critical'|'blocked'|'unknown';
export interface LeaderClientSnapshot { clientId:string; clientName:string; health:HealthStatus; healthReason:string; kpis:KPIResult[]; diagnosis?:DiagnosisReport; actionPlan?:ActionPlan; openActions:number; blockedActions:number; dataCoveragePct:number|null; lastActivityAt?:string; }
export interface LeaderCommandCenter { generatedAt:string; totalClients:number; counts:{healthy:number;attention:number;critical:number;blocked:number;unknown:number}; priorityClients:LeaderClientSnapshot[]; actionSummary:{open:number;blocked:number;overdue:number}; dataQuality:{clientsWithMissingData:number;averageCoveragePct:number|null}; }

export function buildLeaderCommandCenter(clients:LeaderClientSnapshot[], now=new Date()):LeaderCommandCenter {
  const counts={healthy:0,attention:0,critical:0,blocked:0,unknown:0};
  for(const c of clients) counts[c.health]++;
  const open=clients.reduce((n,c)=>n+c.openActions,0), blocked=clients.reduce((n,c)=>n+c.blockedActions,0);
  const overdue=clients.reduce((n,c)=>n+(c.actionPlan?.items.filter(i=>{if(!i.dueDate||['completed','cancelled'].includes(i.status))return false;const due=new Date(i.dueDate);return Number.isFinite(due.getTime())&&due<now;}).length??0),0);
  const coverages=clients.map(c=>c.dataCoveragePct).filter((x):x is number=>x!==null&&Number.isFinite(x)&&x>=0&&x<=100);
  const priority=[...clients].sort((a,b)=>healthRank(b.health)-healthRank(a.health)||b.blockedActions-a.blockedActions||b.openActions-a.openActions);
  return {generatedAt:now.toISOString(),totalClients:clients.length,counts,priorityClients:priority,actionSummary:{open,blocked,overdue},dataQuality:{clientsWithMissingData:clients.filter(c=>c.dataCoveragePct===null||!Number.isFinite(c.dataCoveragePct)||c.dataCoveragePct<100).length,averageCoveragePct:coverages.length?Number((coverages.reduce((a,b)=>a+b,0)/coverages.length).toFixed(1)):null}};
}
function healthRank(s:HealthStatus){return {critical:5,blocked:4,attention:3,unknown:2,healthy:1}[s]}

export type MarketingChannel = 'instagram' | 'tiktok' | 'facebook' | 'google' | 'website' | 'whatsapp' | 'offline' | 'other';
export type MarketingSourceKind = 'system' | 'manual' | 'imported';

export interface MarketingEvidence {
  id?: string;
  sourceKind: MarketingSourceKind;
  source?: string;
  reference?: string;
  period?: string;
  note?: string;
}

export interface MarketingActivity {
  id: string;
  period: string; // YYYY-MM
  name: string;
  channel: MarketingChannel;
  objective?: string;
  cost: number;
  attributedRevenue: number | null;
  leads?: number | null;
  meetings?: number | null;
  conversions?: number | null;
  impressions?: number | null;
  engagement?: number | null;
  status?: 'planned' | 'active' | 'completed' | 'cancelled';
  sourceKind: MarketingSourceKind;
  evidence?: MarketingEvidence[];
}

export interface MarketingPeriodComparison {
  period: string;
  previousPeriod: string | null;
  current: MarketingSummary;
  previous: MarketingSummary | null;
  changes: MarketingChanges;
  limitations: string[];
}

export interface MarketingSummary {
  period: string;
  spend: number;
  attributedRevenue: number | null;
  roiPct: number | null;
  roas: number | null;
  activities: number;
  completedActivities: number;
  leads: number | null;
  meetings: number | null;
  conversions: number | null;
  conversionRatePct: number | null;
  impressions: number | null;
  engagement: number | null;
  dataQuality: 'complete' | 'partial' | 'insufficient';
  invalidCostCount: number;
}

export interface MarketingChanges {
  spend: number | null;
  spendPct: number | null;
  attributedRevenue: number | null;
  attributedRevenuePct: number | null;
  roiPctPoint: number | null;
  leads: number | null;
  meetings: number | null;
  conversions: number | null;
}

export interface MarketingInsight {
  id: string;
  severity: 'critical' | 'high' | 'medium' | 'low' | 'info';
  status: 'confirmed' | 'suspected' | 'blocked';
  title: string;
  finding: string;
  cause: string;
  impact: string;
  recommendation: string;
  evidence: string[];
}

const n = (v: unknown): number | null => {
  if (v === null || v === undefined || v === '') return null;
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
};

export function marketingRoiPct(cost: number, revenue: number | null): number | null {
  if (!(cost > 0) || revenue === null || !Number.isFinite(revenue)) return null;
  return ((revenue - cost) / cost) * 100;
}

export function marketingRoas(cost: number, revenue: number | null): number | null {
  if (!(cost > 0) || revenue === null || !Number.isFinite(revenue)) return null;
  return revenue / cost;
}

export function summarizeMarketing(activities: MarketingActivity[], period: string): MarketingSummary {
  const rows = activities.filter(x => x.period === period);
  // Invalid negative spend must not be silently converted into zero.
  // Keep the summary mathematically conservative and disclose the invalid input.
  const invalidCostCount = rows.filter(x => !Number.isFinite(Number(x.cost)) || Number(x.cost) < 0).length;
  const validSpend = rows.reduce((s, x) => s + (Number.isFinite(Number(x.cost)) && Number(x.cost) >= 0 ? Number(x.cost) : 0), 0);
  // Keep valid spend visible for operational review, but NEVER calculate ROI/ROAS
  // from a partial cost denominator. Invalid rows make financial attribution incomplete.
  const spend = validSpend;
  const revenueValues = rows.map(x => n(x.attributedRevenue)).filter((x): x is number => x !== null);
  const attributedRevenue = revenueValues.length ? revenueValues.reduce((s, x) => s + x, 0) : null;
  const leads = sumNullable(rows.map(x => n(x.leads)));
  const meetings = sumNullable(rows.map(x => n(x.meetings)));
  const conversions = sumNullable(rows.map(x => n(x.conversions)));
  const impressions = sumNullable(rows.map(x => n(x.impressions)));
  const engagement = sumNullable(rows.map(x => n(x.engagement)));
  const conversionRatePct = leads !== null && leads > 0 && conversions !== null ? (conversions / leads) * 100 : null;
  const completeSignals = rows.length > 0 && revenueValues.length === rows.length && rows.every(x => Number.isFinite(Number(x.cost)) && Number(x.cost) >= 0);
  return {
    period, spend, attributedRevenue,
    roiPct: invalidCostCount ? null : marketingRoiPct(spend, attributedRevenue),
    roas: invalidCostCount ? null : marketingRoas(spend, attributedRevenue),
    activities: rows.length,
    completedActivities: rows.filter(x => x.status === 'completed' || x.status === undefined).length,
    leads, meetings, conversions, conversionRatePct, impressions, engagement,
    dataQuality: !rows.length ? 'insufficient' : completeSignals ? 'complete' : 'partial',
    invalidCostCount
  };
}

function sumNullable(values: Array<number | null>): number | null {
  if (!values.length || values.every(x => x === null)) return null;
  return values.reduce<number>((s, x) => s + (x ?? 0), 0);
}

function pctChange(current: number | null, previous: number | null): number | null {
  if (current === null || previous === null || previous === 0) return null;
  return ((current - previous) / Math.abs(previous)) * 100;
}

export function compareMarketingPeriods(activities: MarketingActivity[], period: string, previousPeriod: string | null): MarketingPeriodComparison {
  const current = summarizeMarketing(activities, period);
  const previous = previousPeriod ? summarizeMarketing(activities, previousPeriod) : null;
  const limitations: string[] = [];
  if (!previous) limitations.push('Periode pembanding marketing tidak tersedia.');
  if (current.dataQuality !== 'complete') limitations.push('Sebagian aktivitas belum memiliki attributed revenue atau memiliki input cost yang perlu direview; ROI/ROAS dapat tidak lengkap.');
  if (current.invalidCostCount > 0) limitations.push(`Terdapat ${current.invalidCostCount} aktivitas dengan cost invalid; ROI/ROAS sengaja tidak dihitung agar tidak menggunakan denominator yang salah.`);
  if (current.leads === null) limitations.push('Data leads tidak tersedia pada periode ini.');
  if (current.conversions === null) limitations.push('Data conversions tidak tersedia pada periode ini.');
  return {
    period, previousPeriod, current, previous,
    changes: previous ? {
      spend: current.spend - previous.spend,
      spendPct: pctChange(current.spend, previous.spend),
      attributedRevenue: current.attributedRevenue !== null && previous.attributedRevenue !== null ? current.attributedRevenue - previous.attributedRevenue : null,
      attributedRevenuePct: pctChange(current.attributedRevenue, previous.attributedRevenue),
      roiPctPoint: current.roiPct !== null && previous.roiPct !== null ? current.roiPct - previous.roiPct : null,
      leads: current.leads !== null && previous.leads !== null ? current.leads - previous.leads : null,
      meetings: current.meetings !== null && previous.meetings !== null ? current.meetings - previous.meetings : null,
      conversions: current.conversions !== null && previous.conversions !== null ? current.conversions - previous.conversions : null
    } : { spend: null, spendPct: null, attributedRevenue: null, attributedRevenuePct: null, roiPctPoint: null, leads: null, meetings: null, conversions: null },
    limitations
  };
}

export function diagnoseMarketing(comparison: MarketingPeriodComparison): MarketingInsight[] {
  const c = comparison.current;
  const p = comparison.previous;
  const out: MarketingInsight[] = [];
  if (!c.activities) return [{ id:'marketing-data-missing', severity:'low', status:'blocked', title:'Data marketing belum tersedia', finding:`Tidak ada aktivitas marketing pada ${c.period}.`, cause:'Tidak ada record aktivitas pada periode.', impact:'Efektivitas channel/campaign belum dapat dinilai.', recommendation:'Masukkan aktivitas dan evidence marketing yang benar.', evidence:[] }];
  if (!p) return [{ id:'marketing-no-comparison', severity:'info', status:'blocked', title:'Periode pembanding belum tersedia', finding:`Aktivitas marketing tersedia pada ${c.period}, tetapi periode pembanding belum tersedia.`, cause:'Data periode sebelumnya tidak tersedia.', impact:'Tren marketing belum dapat dikonfirmasi.', recommendation:'Lengkapi periode sebelumnya untuk analisis perubahan.', evidence:[`Period: ${c.period}`] }];
  const attributionIncomplete = c.activities > 0 && c.dataQuality !== 'complete';
  if (c.spend > 0 && attributionIncomplete) out.push({ id:'marketing-attribution-missing', severity:'medium', status:'confirmed', title:'Spend ada tetapi attributed revenue belum lengkap', finding:`Spend ${money(c.spend)} tercatat, namun attributed revenue belum tersedia untuk seluruh aktivitas.`, cause:'Attribution/evidence revenue belum diisi.', impact:'ROI dan ROAS tidak dapat dikonfirmasi penuh.', recommendation:'Lengkapi attributed revenue hanya jika ada evidence yang mendukung; jangan mengalokasikan revenue outlet secara otomatis.', evidence:[`Spend ${money(c.spend)}`, `Data quality: ${c.dataQuality}`] });
  if (comparison.changes.roiPctPoint !== null && comparison.changes.roiPctPoint < -5) out.push({ id:'marketing-roi-decline', severity:'high', status:'confirmed', title:'ROI marketing menurun', finding:`ROI turun ${Math.abs(comparison.changes.roiPctPoint).toFixed(2)} pp dari periode sebelumnya.`, cause:'Perubahan ROI terkonfirmasi secara matematis; driver campaign/channel belum dapat dipastikan dari summary saja.', impact:'Efisiensi spend marketing memburuk.', recommendation:'Drill down campaign, channel, audience, spend, dan evidence attributed revenue sebelum mengubah budget.', evidence:[`ROI current ${pct(c.roiPct)}`, `ROI previous ${pct(p.roiPct)}`] });
  if (comparison.changes.spendPct !== null && comparison.changes.spendPct > 20 && comparison.changes.attributedRevenuePct !== null && comparison.changes.attributedRevenuePct < 0) out.push({ id:'marketing-spend-revenue-mismatch', severity:'high', status:'confirmed', title:'Spend naik sementara attributed revenue turun', finding:`Spend naik ${comparison.changes.spendPct.toFixed(2)}% sementara attributed revenue turun ${Math.abs(comparison.changes.attributedRevenuePct).toFixed(2)}%.`, cause:'Mismatch perubahan spend dan attributed revenue terkonfirmasi; akar masalah campaign belum teridentifikasi.', impact:'Efisiensi investasi marketing berpotensi memburuk.', recommendation:'Audit campaign-level spend, creative, channel, targeting, timing, dan attribution evidence.', evidence:[`Spend change ${comparison.changes.spendPct.toFixed(2)}%`, `Attributed revenue change ${comparison.changes.attributedRevenuePct.toFixed(2)}%`] });
  if (out.length === 0) out.push({ id:'marketing-no-material-signal', severity:'info', status:'confirmed', title:'Tidak ada sinyal marketing material', finding:`Tidak ada perubahan material yang dapat dikonfirmasi pada ${c.period}.`, cause:'Metric tersedia tidak melewati rule diagnosis.', impact:'Tidak ada masalah marketing material yang dapat dikonfirmasi.', recommendation:'Lanjutkan monitoring dan kumpulkan evidence channel/campaign secara konsisten.', evidence:[`Activities ${c.activities}`, `Data quality ${c.dataQuality}`] });
  return out;
}

function money(v:number){ return `Rp${Math.round(v).toLocaleString('id-ID')}`; }
function pct(v:number|null){ return v === null ? 'N/A' : `${v.toFixed(2)}%`; }

/**
 * ============================================================================
 * TUTUP BUKU (PERIOD CLOSE)
 * ============================================================================
 * Dua masalah nyata yang ditutup modul ini:
 *
 * 1. TANPA period lock, siapa pun bisa mengubah jurnal bulan lalu setelah
 *    laporan sudah dikirim ke klien — angka yang klien lihat bulan lalu
 *    diam-diam berbeda dari yang tersimpan sekarang. `assertPeriodNotLocked`
 *    mencegah ini dengan melempar error sebelum jurnal baru diposting ke
 *    periode yang sudah ditutup.
 *
 * 2. TANPA jurnal penutup, saldo akun Pendapatan/HPP/Beban akan terus
 *    menumpuk dari bulan ke bulan alih-alih mulai dari nol tiap periode baru
 *    — ini bikin Trial Balance & Neraca salah untuk periode berikutnya.
 *    `buildClosingEntry` meniru siklus akuntansi manual: memindahkan laba
 *    bersih periode itu ke akun "Laba Ditahan", lalu me-reset akun nominal
 *    (Pendapatan/HPP/Beban) ke nol.
 */

import type { JournalEntry, JournalLine } from './accounting.js';

export interface PeriodLock {
  period: string;   // "2026-08"
  clientId: string;
  lockedAt: string;
  lockedBy: string;
}

export function isPeriodLocked(period: string, clientId: string, locks: PeriodLock[]): boolean {
  return locks.some(l => l.period === period && l.clientId === clientId);
}

/** Dipanggil sebelum memposting jurnal baru manapun. Melempar error kalau periode terkunci. */
export function assertPeriodNotLocked(period: string, clientId: string, locks: PeriodLock[]): void {
  if (isPeriodLocked(period, clientId, locks)) {
    throw new Error(
      `Periode ${period} untuk klien ini sudah ditutup (locked). ` +
      `Tidak bisa memposting jurnal baru ke periode yang laporannya sudah selesai dikirim. ` +
      `Kalau memang perlu koreksi, buat jurnal penyesuaian di periode berjalan, jangan buka kunci periode lama.`,
    );
  }
}

export interface ClosingEntryParams {
  clientId: string;
  period: string;
  labaBersih: number;                  // hasil akhir Income Statement periode ini
  retainedEarningsAccountId: string;   // id akun "Laba Ditahan"
  /** Saldo tiap akun Pendapatan/HPP/Beban pada periode ini (dari Trial Balance),
   *  yang akan direset ke nol lewat jurnal penutup. */
  nominalAccountBalances: Array<{ accountId: string; balance: number }>;
  entryId: string;
  entryDate: string;
}

export interface ClosingEntryResult {
  closingEntry: JournalEntry;
  labaBersihDipindahkan: number;
}

export function buildClosingEntry(params: ClosingEntryParams): ClosingEntryResult {
  const lines: JournalLine[] = params.nominalAccountBalances.map(a => ({
    accountId: a.accountId,
    // Membalik saldo akun nominal ke nol: akun bersaldo kredit (Pendapatan) didebit,
    // akun bersaldo debit (HPP/Beban) dikredit.
    debit: a.balance < 0 ? Math.abs(a.balance) : 0,
    credit: a.balance > 0 ? a.balance : 0,
    memo: 'Jurnal penutup — reset akun nominal ke nol',
  }));

  lines.push({
    accountId: params.retainedEarningsAccountId,
    debit: params.labaBersih < 0 ? Math.abs(params.labaBersih) : 0,
    credit: params.labaBersih > 0 ? params.labaBersih : 0,
    memo: 'Pemindahan laba/rugi bersih periode ke Laba Ditahan',
  });

  return {
    closingEntry: {
      id: params.entryId,
      clientId: params.clientId,
      date: params.entryDate,
      memo: `Jurnal Penutup — Periode ${params.period}`,
      source: 'adjustment',
      lines,
    },
    labaBersihDipindahkan: params.labaBersih,
  };
}

export type POSEventType='sale'|'void'|'refund'|'discount'|'price_override'|'payment'|'cash_discrepancy'|'comp'|'cancellation';
export interface POSEvent { id:string; organizationId:string; outletId?:string; employeeId?:string; cashierId?:string; productId?:string; type:POSEventType; amount:number; occurredAt:string; linkedSaleId?:string; sourceRecordId?:string; }
export interface POSAnomaly { code:string; title:string; severity:'LOW'|'MEDIUM'|'HIGH'|'CRITICAL'; eventType:POSEventType; entity?:string; observed:number; baseline:number|null; ratioPct:number|null; financialImpact:number|null; evidenceIds:string[]; explanation:string; confidence:'VERIFIED'|'HIGH CONFIDENCE'|'MEDIUM CONFIDENCE'|'LOW CONFIDENCE'|'INSUFFICIENT DATA'; }
export interface POSHealthResult { score:number|null; anomalies:POSAnomaly[]; metrics:{transactions:number;voidRatePct:number|null;refundRatePct:number|null;discountRatePct:number|null;priceOverrideRatePct:number|null;cashDiscrepancy:number|null}; }
const pct=(a:number,b:number)=>b>0?(a/b)*100:null;
const ratio=(v:number,b:number)=>b>0?(v/b)*100:null;
function severity(ratioPct:number){if(ratioPct>=500)return 'CRITICAL' as const;if(ratioPct>=250)return 'HIGH' as const;if(ratioPct>=150)return 'MEDIUM' as const;return 'LOW' as const;}
export function analyzePOSHealth(events:POSEvent[], previousEvents:POSEvent[]=[]):POSHealthResult{
  const sales=events.filter(e=>e.type==='sale').length; const count=(t:POSEventType)=>events.filter(e=>e.type===t).length;
  const voids=count('void'), refunds=count('refund'), discounts=count('discount'), overrides=count('price_override');
  const prevSales=previousEvents.filter(e=>e.type==='sale').length;
  const prevRate=(t:POSEventType)=>pct(previousEvents.filter(e=>e.type===t).length,prevSales);
  const mk=(type:POSEventType,title:string,current:number,severityBase:boolean):POSAnomaly|null=>{const base=prevRate(type); if(!severityBase||current===0)return null; const r=base&&base>0?current/base*100:null; return {code:`ABNORMAL_${type.toUpperCase()}_RATE`,title,severity:r===null?'LOW':severity(r),eventType:type,observed:current,baseline:base,ratioPct:r,financialImpact:events.filter(e=>e.type===type).reduce((s,e)=>s+e.amount,0)||null,evidenceIds:events.filter(e=>e.type===type).map(e=>e.id).slice(0,20),explanation:`Rate ${type} saat ini ${current.toFixed(2)}%; baseline periode pembanding ${base===null?'tidak tersedia':base.toFixed(2)+'%'}.`,confidence:base===null?'INSUFFICIENT DATA':'HIGH CONFIDENCE'};};
  const anomalies=[mk('void','Void rate abnormal',pct(voids,sales)??0,true),mk('refund','Refund rate abnormal',pct(refunds,sales)??0,true),mk('discount','Discount rate abnormal',pct(discounts,sales)??0,true),mk('price_override','Manual price override abnormal',pct(overrides,sales)??0,true)].filter(Boolean) as POSAnomaly[];
  const cash=events.filter(e=>e.type==='cash_discrepancy').reduce((s,e)=>s+Math.abs(e.amount),0); if(cash>0) anomalies.push({code:'CASH_DISCREPANCY',title:'Cash discrepancy terdeteksi',severity:'HIGH',eventType:'cash_discrepancy',observed:cash,baseline:null,ratioPct:null,financialImpact:cash,evidenceIds:events.filter(e=>e.type==='cash_discrepancy').map(e=>e.id),explanation:'Selisih kas tercatat; sistem tidak menyimpulkan fraud tanpa evidence tambahan.',confidence:'VERIFIED'});
  const sequenceAnomalies=detectSuspiciousSequences(events); anomalies.push(...sequenceAnomalies);
  const penalties=anomalies.reduce((s,a)=>s+(a.severity==='CRITICAL'?30:a.severity==='HIGH'?20:a.severity==='MEDIUM'?10:5),0); const score=sales?Math.max(0,Math.min(100,100-penalties)):null;
  return {score,anomalies,metrics:{transactions:sales,voidRatePct:pct(voids,sales),refundRatePct:pct(refunds,sales),discountRatePct:pct(discounts,sales),priceOverrideRatePct:pct(overrides,sales),cashDiscrepancy:cash||null}};
}

function detectSuspiciousSequences(events:POSEvent[]):POSAnomaly[]{
  const bySale=new Map<string,POSEvent[]>();
  for(const e of events){const key=e.linkedSaleId||e.sourceRecordId; if(!key) continue; const arr=bySale.get(key)??[]; arr.push(e); bySale.set(key,arr);}
  const findings:POSAnomaly[]=[];
  for(const [key,arr] of bySale){arr.sort((a,b)=>a.occurredAt.localeCompare(b.occurredAt)); const types=arr.map(e=>e.type);
    const suspicious=(types.includes('payment')&&types.includes('void'))||(types.includes('refund')&&types.includes('discount'));
    if(suspicious) findings.push({code:'SUSPICIOUS_TRANSACTION_SEQUENCE',title:'Urutan transaksi perlu ditinjau',severity:'MEDIUM',eventType:types.includes('void')?'void':'refund',observed:1,baseline:null,ratioPct:null,financialImpact:arr.reduce((s,e)=>s+e.amount,0)||null,evidenceIds:arr.map(e=>e.id),explanation:`Transaksi ${key} memiliki kombinasi event ${types.join(' → ')} yang perlu direview. Ini bukan bukti fraud.`,confidence:'MEDIUM CONFIDENCE'});
  }
  return findings.slice(0,50);
}

import type { FinanceComparison } from './finance.js';
import type { DiagnosisReport } from './diagnosis.js';
import type { ActionPlan } from './actionPlan.js';
import type { KPIResult } from './kpi.js';

export interface ReportEvidence { source:string; period?:string; detail:string; }
export interface ConsultingReport { title:string; clientName:string; generatedAt:string; periods:{current:string;previous:string|null}; executiveSummary:string; finance:FinanceComparison; diagnosis:DiagnosisReport; kpis:KPIResult[]; actionPlan?:ActionPlan; evidence:ReportEvidence[]; limitations:string[]; }
export function buildConsultingReport(input:Omit<ConsultingReport,'generatedAt'> & {generatedAt?:string}):ConsultingReport{return{...input,generatedAt:input.generatedAt??new Date().toISOString(),evidence:[...input.evidence],limitations:[...input.limitations]}}
export function reportToPlainText(report:ConsultingReport){const lines=[`# ${report.title}`,`Client: ${report.clientName}`,`Generated: ${report.generatedAt}`,`Period: ${report.periods.current} vs ${report.periods.previous??'tidak tersedia'}`,'',`## Executive Summary`,report.executiveSummary,'',`## Finance`,...report.finance.metrics.map(m=>`${m.metric}: current=${m.current??'N/A'} previous=${m.previous??'N/A'} change=${m.change??'N/A'} changePct=${m.changePct==null?'N/A':m.changePct.toFixed(2)+'%'} formula=${m.formula}`),'',`## Diagnosis`,report.diagnosis.conclusion,...report.diagnosis.findings.map(f=>`- ${f.title}: ${f.problem} Cause: ${f.cause} Recommendation: ${f.recommendation}`),'',`## Evidence`,...report.evidence.map(e=>`- ${e.source}${e.period?` (${e.period})`:''}: ${e.detail}`),'',`## Limitations`,...(report.limitations.length?report.limitations:['Tidak ada limitation yang dicatat.'])];return lines.join('\n')}
export function reportToCSV(report:ConsultingReport){const rows=[['Section','Metric','Current','Previous','Change','Change %','Formula','Status','Source','Period','Detail'],...report.finance.metrics.map(m=>['Finance',m.metric,m.current,m.previous,m.change,m.changePct,m.formula,m.status,'','','']),...report.kpis.map(k=>['KPI',k.name,k.current,k.previous,k.change,k.changePct,k.formula,k.status,k.evidence[0]?.source??'',k.evidence[0]?.period??'',k.conclusion]),...report.evidence.map(e=>['Evidence','', '', '', '', '', '', '',e.source,e.period??'',e.detail]),...report.limitations.map(l=>['Limitation','','','','','','','','','',l])];return rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n')}

export interface SaleLine {
  id: string; productName: string; menuCategory?: string; qty: number; unitPrice: number;
  channel: 'dine_in'|'gofood'|'grabfood'|'shopeefood'|'other'; outletId?: string; soldAt: string;
}
export interface BreakdownItem { label: string; value: number; sharePct: number; }

function amount(l: SaleLine): number { return l.qty * l.unitPrice; }

function rank(entries: Map<string, number>, limit = 5): BreakdownItem[] {
  const total = [...entries.values()].reduce((a, b) => a + b, 0);
  return [...entries.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([label, value]) => ({ label, value, sharePct: total > 0 ? Number(((value / total) * 100).toFixed(2)) : 0 }));
}

function bucketBy(lines: SaleLine[], keyFn: (l: SaleLine) => string): Map<string, number> {
  const m = new Map<string, number>();
  for (const l of lines) { const k = keyFn(l); m.set(k, (m.get(k) ?? 0) + amount(l)); }
  return m;
}

const CHANNEL_LABEL: Record<SaleLine['channel'], string> = { dine_in: 'Dine-in', gofood: 'GoFood', grabfood: 'GrabFood', shopeefood: 'ShopeeFood', other: 'Lainnya' };

function priceRangeLabel(price: number): string {
  if (price <= 20000) return 'Rp 0 - Rp 20,000';
  if (price <= 40000) return 'Rp 20,001 - Rp 40,000';
  if (price <= 60000) return 'Rp 40,001 - Rp 60,000';
  if (price <= 80000) return 'Rp 60,001 - Rp 80,000';
  if (price <= 100000) return 'Rp 80,001 - Rp 100,000';
  return 'Rp 100,001+';
}

export interface SalesDashboard {
  totalRevenue: number;
  topProducts: BreakdownItem[];
  topCategories: BreakdownItem[];
  priceRanges: BreakdownItem[];
  topOutlets: BreakdownItem[];
  topHours: BreakdownItem[];
  topChannels: BreakdownItem[];
  monthlyRevenue: { period: string; value: number }[];
}

/** All breakdowns are computed from raw per-line sales — nothing here is estimated
 *  or backfilled; a period/outlet/channel with zero transactions yields an empty entry,
 *  not a fabricated share. */
export function buildSalesDashboard(lines: SaleLine[]): SalesDashboard {
  const totalRevenue = lines.reduce((s, l) => s + amount(l), 0);
  const topProducts = rank(bucketBy(lines, l => l.productName));
  const topCategories = rank(bucketBy(lines, l => l.menuCategory?.trim() || 'Tanpa kategori'));
  const priceRanges = rank(bucketBy(lines, l => priceRangeLabel(l.unitPrice)));
  const topOutlets = rank(bucketBy(lines, l => l.outletId?.trim() || 'Outlet tidak diketahui'));
  const topHours = rank(bucketBy(lines, l => { const h = new Date(l.soldAt).getHours(); return `${String(h).padStart(2, '0')}:00 - ${String(h).padStart(2, '0')}:59`; }));
  const topChannels = rank(bucketBy(lines, l => CHANNEL_LABEL[l.channel]), 5);
  const byMonth = new Map<string, number>();
  for (const l of lines) { const p = l.soldAt.slice(0, 7); byMonth.set(p, (byMonth.get(p) ?? 0) + amount(l)); }
  const monthlyRevenue = [...byMonth.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([period, value]) => ({ period, value }));
  return { totalRevenue, topProducts, topCategories, priceRanges, topOutlets, topHours, topChannels, monthlyRevenue };
}

export type SOPStepStatus='pending'|'in_progress'|'done'|'blocked';
export interface SOPStep{id:string;order:number;title:string;instruction:string;owner:string;status:SOPStepStatus;requiredEvidence:string[];evidence:string[];control:string}
export interface SOP{id:string;name:string;purpose:string;trigger:string;steps:SOPStep[];version:number;active:boolean}
export function validateSOP(sop:SOP){const issues:string[]=[];if(!sop.id||!sop.name||!sop.purpose||!sop.trigger)issues.push('SOP identity, purpose, and trigger are required');const orders=sop.steps.map(s=>s.order);if(new Set(orders).size!==orders.length)issues.push('step order must be unique');for(const s of sop.steps){if(!s.title||!s.instruction||!s.owner)issues.push(`step ${s.id} missing required fields`);if(s.status==='done'&&s.requiredEvidence.some(e=>!s.evidence.includes(e)))issues.push(`step ${s.id} cannot be done without required evidence`);if(!s.control)issues.push(`step ${s.id} requires a control`)}return issues}
export function buildSOP(input:Omit<SOP,'version'>&{version?:number}){const sop={...input,version:input.version??1};const issues=validateSOP(sop);if(issues.length)throw new Error(`INVALID_SOP: ${issues.join('; ')}`);return sop}
export function nextSOPStep(sop:SOP){return [...sop.steps].sort((a,b)=>a.order-b.order).find(s=>s.status!=='done')??null}

/**
 * ============================================================================
 * KALKULATOR PAJAK SEDERHANA — PPN & PPh Final UMKM
 * ============================================================================
 * BATASAN TANGGUNG JAWAB (harap ditampilkan juga di UI, bukan cuma di kode):
 * Modul ini HANYA untuk ESTIMASI INTERNAL memakai tarif publik yang berlaku
 * umum saat file ini ditulis (PPN 11%, PPh Final UMKM 0,5%). Modul ini:
 *   - BUKAN pengganti akuntan/konsultan pajak resmi
 *   - BUKAN alat pelaporan SPT ke DJP
 *   - TIDAK memperhitungkan status PKP, jenis usaha, atau skema pajak khusus
 *     yang mungkin berlaku untuk klien tertentu
 *   - Tarif pajak bisa berubah kapan saja — SELALU verifikasi ke peraturan
 *     terbaru dan akuntan klien sebelum angka ini dipakai untuk keputusan
 *     atau pelaporan resmi.
 */

export interface PpnResult { dpp: number; tarifPersen: number; ppn: number; totalTermasukPpn: number; }

/** DPP = Dasar Pengenaan Pajak (harga SEBELUM PPN). */
export function calculatePpn(dpp: number, tarifPersen: number = 11): PpnResult {
  const ppn = Math.round(dpp * (tarifPersen / 100));
  return { dpp, tarifPersen, ppn, totalTermasukPpn: dpp + ppn };
}

/** Kebalikannya: harga yang diinput SUDAH termasuk PPN, cari mundur DPP-nya.
 *  Berguna kalau yang tercatat di kasir/POS adalah harga jual final ke pembeli. */
export function extractPpnFromGrossPrice(hargaTermasukPpn: number, tarifPersen: number = 11): PpnResult {
  const dpp = Math.round(hargaTermasukPpn / (1 + tarifPersen / 100));
  return { dpp, tarifPersen, ppn: hargaTermasukPpn - dpp, totalTermasukPpn: hargaTermasukPpn };
}

export interface PphFinalUmkmResult { omsetBulanan: number; tarifPersen: number; pphTerutang: number; }

/** PPh Final UMKM: 0,5% dari omset bulanan (bukan dari laba), untuk usaha dengan
 *  kriteria omset tertentu per tahun dan berlaku untuk jangka waktu terbatas
 *  sejak usaha terdaftar. Kelayakan tiap klien HARUS dicek dengan akuntan —
 *  fungsi ini tidak memvalidasi kelayakan tersebut. */
export function calculatePphFinalUmkm(omsetBulanan: number, tarifPersen: number = 0.5): PphFinalUmkmResult {
  return { omsetBulanan, tarifPersen, pphTerutang: Math.round(omsetBulanan * (tarifPersen / 100)) };
}

export interface TaxSummary {
  period: string;
  ppnKeluaran: number; // PPN dari penjualan ke pembeli
  ppnMasukan: number;  // PPN yang sudah dibayar ke supplier ber-PKP
  ppnKurangBayar: number;
  pphFinal: number;
  totalKewajibanPajak: number;
}

/** Rekap pajak bulanan sederhana: PPN Kurang Bayar = Keluaran − Masukan (tidak boleh negatif,
 *  kalau negatif artinya ada kelebihan bayar yang perlu dikonfirmasi ke akuntan, bukan dianggap 0 diam-diam). */
export function summarizeMonthlyTax(period: string, ppnKeluaran: number, ppnMasukan: number, pphFinal: number): TaxSummary {
  const ppnKurangBayar = Math.max(0, Math.round((ppnKeluaran - ppnMasukan) * 100) / 100);
  return { period, ppnKeluaran, ppnMasukan, ppnKurangBayar, pphFinal, totalKewajibanPajak: ppnKurangBayar + pphFinal };
}

