const CACHE_NAME = "trace-os-v17";
const APP_SHELL = ["./", "./index.html", "./manifest.json", "./icon-192.png", "./icon-512.png"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(APP_SHELL)));
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))));
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  if (event.request.url.includes("supabase.co")) return;
  const url = new URL(event.request.url);
  // HTML/JS app shell must prefer the network so a deployment cannot silently
  // keep an older report generator in the browser cache.
  if (event.request.mode === "navigate" || url.pathname.endsWith("/index.html") || url.pathname.endsWith("/sw.js")) {
    event.respondWith(fetch(event.request).then((response) => {
      const copy = response.clone();
      caches.open(CACHE_NAME).then((cache) => cache.put(event.request, copy));
      return response;
    }).catch(() => caches.match(event.request)));
    return;
  }
  event.respondWith(caches.match(event.request).then((cached) => cached || fetch(event.request)));
});

// load-app.js
//
// Loads the ACTUAL index.html into a jsdom window/document and runs its
// real inline <script> content, so tests call the real window.loadData,
// window.saveData, window.setupModule, etc. -- not a hand-copied
// reimplementation (that was the flaw in the old test_*.js files, and the
// exact flaw that let a stale, unreferenced script_1.js ship in this
// package undetected).
//
// Deliberately reads index.html fresh on every loadApp() call, instead of
// keeping a separately-maintained copy of the script -- so these tests can
// never drift out of sync with the file that actually ships to users.
//
// Usage:
//   const { loadApp } = require("./load-app");
//   const { win } = loadApp({ supabase: makeSupaMock(...) });
//   await win.loadData("someKey");

const fs = require("fs");
const path = require("path");
const { JSDOM } = require("jsdom");
const vm = require("vm");

// index.html lives one directory up from tests_real/ in this package.
const INDEX_HTML_PATH = path.join(__dirname, "..", "index.html");

// index.html relies on browser semantics for unhandled promise rejections:
// a rejected promise with no local catch just logs to the console (caught
// by index.html's OWN `window.addEventListener("unhandledrejection")`
// safety net from Tahap 11B). Node, unlike a browser tab, terminates the
// whole process on an unhandled rejection by default. Several real modules
// (Timeline, Kontak, Klien, Akuntansi, dst) call loadData() at top-level
// script boot with no local try/catch BY DESIGN -- so a network failure
// simulated during boot makes those unrelated background loads reject too.
// That is expected app behavior, not a test bug; without this guard Node
// would crash before any assertion runs.
process.on("unhandledRejection", () => { /* mirrors browser tab behavior */ });

/**
 * @param {object} opts
 * @param {object|undefined} opts.supabase - a fake `window.supabase` with a
 *   `.createClient()` method matching the real @supabase/supabase-js
 *   surface used by index.html (see make-supa-mock.js). Omit/undefined to
 *   force local-storage-only mode.
 */
function loadApp(opts = {}) {
  const html = fs.readFileSync(INDEX_HTML_PATH, "utf8");

  // Production contains the main app script plus a smaller Acquisition bridge.
  // Never assume there is exactly one non-empty inline script.
  const scriptMatches = [...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)]
    .filter(m => m[1].trim().length > 0);
  const appMatch = scriptMatches
    .filter(m => m[1].includes('function todayISO') && m[1].length > 100000)
    .sort((a,b) => b[1].length - a[1].length)[0];
  if (!appMatch) {
    throw new Error(`Could not locate production app inline script; found ${scriptMatches.length} non-empty blocks.`);
  }
  const code = appMatch[1];

  // Use the real page markup (full index.html, minus its own <script>
  // blocks) as the jsdom document. index.html makes several unguarded
  // document.getElementById("x").addEventListener(...) calls at top-level
  // load time, assuming those ids exist -- which they do in the real page.
  // A blank/synthetic shell would throw and abort the whole script before
  // any function is even defined.
  const shellHtml = html.replace(/<script(?:\s[^>]*)?>[\s\S]*?<\/script>/g, "");
  const dom = new JSDOM(shellHtml, {
    url: "https://trace-os.test/",
    runScripts: "outside-only"
  });
  const win = dom.window;

  // window.supabase must exist BEFORE the script runs, because
  // detectStorageMode() checks `window.supabase` synchronously at module
  // load time (see index.html, "Storage engine" section).
  win.supabase = opts.supabase || undefined;

  vm.runInContext(code, dom.getInternalVMContext(), { filename: "index.html (inline script, live)" });

  return { dom, win };
}

module.exports = { loadApp };

// make-supa-mock.js
//
// Mocks the exact chain of @supabase/supabase-js calls that index.html's
// loadData()/saveData()/detectStorageMode() make, so we can simulate
// network failures deterministically without a real network or a headless
// browser. Kept as a standalone module (not copy-pasted per test file) so
// every test that needs it shares one implementation.

function makeSupaMock(kv = new Map(), mode = { read: "ok", write: "ok", connect: "ok", session: { user: { id: "test-user", email: "tester@trace.local" } } }) {
  let authSession = mode.session === undefined ? { user: { id: "test-user", email: "tester@trace.local" } } : mode.session;
  let authCallback = null;
  const client = {
    from(table) {
      return {
        select(_cols) {
          return {
            // detectStorageMode(): supa.from(...).select("key").limit(1)
            limit(_n) {
              if (mode.connect === "network_fail") {
                return Promise.resolve({ data: null, error: { message: "network down" } });
              }
              return Promise.resolve({ data: [], error: null });
            },
            // loadData(): supa.from(...).select("value").eq("key",k).maybeSingle()
            // Production's overwrite guard also chains .abortSignal(controller.signal)
            // onto this same call (see saveDataUnlocked() in index.html), so the mock
            // must accept it too -- a thenable that also exposes maybeSingle()/abortSignal()
            // lets production code chain either method in either order without changing
            // the resolved value.
            eq(_col, key) {
              const resolveMaybeSingle = async () => {
                if (mode.read === "network_fail") {
                  return { data: null, error: { message: "network down" } };
                }
                if (kv.has(key)) return { data: { value: kv.get(key) }, error: null };
                return { data: null, error: null }; // key belum pernah diisi -- normal
              };
              const chain = {
                maybeSingle() {
                  const p = resolveMaybeSingle();
                  // maybeSingle() itself may also be followed by .abortSignal(signal)
                  // in production code, so keep supporting it on the returned promise.
                  p.abortSignal = () => chain.maybeSingle();
                  return p;
                },
                abortSignal(_signal) {
                  return chain;
                },
                then(resolve, reject) {
                  return resolveMaybeSingle().then(resolve, reject);
                }
              };
              return chain;
            }
          };
        },
        // saveData(): supa.from(...).upsert({key, value}), also chained with
        // .abortSignal(controller.signal) by the production overwrite guard.
        upsert({ key, value }) {
          const resolveUpsert = async () => {
            if (mode.write === "network_fail") {
              return { error: { message: "network down" } };
            }
            kv.set(key, value);
            return { error: null };
          };
          const chain = {
            abortSignal(_signal) {
              return chain;
            },
            then(resolve, reject) {
              return resolveUpsert().then(resolve, reject);
            }
          };
          return chain;
        }
      };
    },
    channel(_name) {
      return { on() { return this; }, subscribe() {} };
    },
    auth: {
      async getSession() { return { data: { session: authSession }, error: null }; },
      onAuthStateChange(cb) { authCallback = cb; return { data: { subscription: { unsubscribe() { if (authCallback === cb) authCallback = null; } } } }; },
      async signInWithPassword({ email }) {
        authSession = { user: { id: "test-user", email } };
        if (authCallback) setTimeout(() => authCallback("SIGNED_IN", authSession), 0);
        return { data: { session: authSession }, error: null };
      },
      async signOut() {
        authSession = null;
        if (authCallback) setTimeout(() => authCallback("SIGNED_OUT", null), 0);
        return { error: null };
      }
    }
  };

  return {
    createClient(_url, _key) { return client; },
    _client: client,
    _kv: kv,
    _mode: mode,
    _auth: { get session() { return authSession; } }
  };
}

module.exports = { makeSupaMock };

// make-test-module-dom.js
//
// setupModule() (index.html) expects specific element ids to already exist:
// `${prefix}_list`, `${prefix}Form`, and a submit button with class
// "submit" inside the form. The real page has these for Timeline/Kontak/
// Klien/etc, but reusing those would mean two competing setupModule()
// instances fight over the same DOM nodes (the real one boots automatically
// when app-inline.js loads). Instead we inject a brand-new, uniquely
// prefixed set of nodes -- same shape a real module's HTML takes -- so
// setupModule() runs exactly as it does in production, just scoped to a
// throwaway storage key.

function makeTestModuleDom(win, prefix) {
  const doc = win.document;
  const list = doc.createElement("div");
  list.id = `${prefix}_list`;
  doc.body.appendChild(list);

  const form = doc.createElement("form");
  form.id = `${prefix}Form`;
  const submitBtn = doc.createElement("button");
  submitBtn.className = "submit";
  submitBtn.type = "submit";
  form.appendChild(submitBtn);
  doc.body.appendChild(form);

  const status = doc.createElement("div");
  status.id = `${prefix}_status_msg`;
  doc.body.appendChild(status);

  return { list, form, status, submitBtn };
}

module.exports = { makeTestModuleDom };

