let pass = 0, fail = 0;
function assertEq(label, actual, expected) {
  if (actual === expected) { pass++; }
  else { fail++; console.error(`FAIL ${label}: expected ${expected}, got ${actual}`); }
}

async function newApp() {
  const supa = makeSupaMock();
